241	impl Camera for Camera3D {
242	    fn matrix(&self) -> Mat4 {
243	        let (width, height) = if let Some(rt) = &self.render_target {
244	            (rt.texture.width(), rt.texture.height())
245	        } else {
246	            (screen_width(), screen_height())
247	        };
248	        let aspect = self.aspect.unwrap_or(width / height);
249	
250	        match self.projection {
251	            Projection::Perspective => {
252	                Mat4::perspective_rh_gl(self.fovy, aspect, self.z_near, self.z_far)
253	                    * Mat4::look_at_rh(self.position, self.target, self.up)
254	            }
255	            Projection::Orthographics => {
256	                let top = self.fovy / 2.0;
257	                let right = top * aspect;
258	
259	                Mat4::orthographic_rh_gl(-right, right, -top, top, self.z_near, self.z_far)
260	                    * Mat4::look_at_rh(self.position, self.target, self.up)
261	            }
262	        }
263	    }
