                        Err(_) => white_image(),
                    }
                }
            }
            _ => white_image(),
        });
        m.dirty_base = false;
        m.dirty_tex = true;
    }
    if m.dirty_tex {
        let base = m.base.as_ref().unwrap();
        let mut out = base.clone();
        let br = m.brightness;
        let ct = 1.0 + m.contrast;
        let sat = 1.0 + m.saturation;
