                let p = poly[j];
                if cross2(a, b, p) >= 0.0 && cross2(b, c, p) >= 0.0 && cross2(c, a, p) >= 0.0 {
                    inside = true;
                    break;
                }
            }
            if inside {
                continue;
            }
            out.push([ia, ib, ic]);
