//! Tree generation: walks the generator graph and builds branch skins and leaf meshes.
use crate::model::*;
use crate::textures::triangulate;
use macroquad::models::Vertex;
use macroquad::prelude::*;
use std::collections::HashMap;
use std::f32::consts::PI;

pub const CHUNK_VERTS: usize = 30000;

pub struct Rng(u64);
impl Rng {
    pub fn new(seed: u64) -> Self {
        Rng(seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407) | 1)
    }
    pub fn next(&mut self) -> f32 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        ((self.0 >> 40) as f32) / ((1u64 << 24) as f32)
    }
    /// -1..1
    pub fn sym(&mut self) -> f32 {
        self.next() * 2.0 - 1.0
    }
}

pub struct Spine {
    pub node: u32,
    pub pts: Vec<Vec3>,
    pub rad: Vec<f32>,
    pub tan: Vec<Vec3>,
    pub nrm: Vec<Vec3>,
    pub cum: Vec<f32>,
    pub len: f32,
}

impl Spine {
    fn locate(&self, t: f32) -> (usize, f32) {
        let d = t.clamp(0.0, 1.0) * self.len;
        for k in 0..self.pts.len() - 1 {
            if d <= self.cum[k + 1] || k == self.pts.len() - 2 {
                let seg = (self.cum[k + 1] - self.cum[k]).max(1e-6);
                return (k, ((d - self.cum[k]) / seg).clamp(0.0, 1.0));
            }
        }
        (0, 0.0)
    }
    pub fn point(&self, t: f32) -> Vec3 {
        let (k, f) = self.locate(t);
        self.pts[k].lerp(self.pts[k + 1], f)
    }
    pub fn radius(&self, t: f32) -> f32 {
        let (k, f) = self.locate(t);
        self.rad[k] + (self.rad[k + 1] - self.rad[k]) * f
    }
    pub fn frame(&self, t: f32) -> (Vec3, Vec3, Vec3) {
        let (k, f) = self.locate(t);
        let tn = self.tan[k].lerp(self.tan[k + 1], f).normalize_or_zero();
        let mut n = self.nrm[k].lerp(self.nrm[k + 1], f);
        n = (n - tn * n.dot(tn)).normalize_or_zero();
        if n.length_squared() < 0.5 {
            n = any_perp(tn);
        }
        let b = tn.cross(n);
        (tn, n, b)
    }
}

fn any_perp(t: Vec3) -> Vec3 {
    let a = if t.x.abs() < 0.9 { Vec3::X } else { Vec3::Z };
    t.cross(a).normalize()
}

#[derive(Default)]
pub struct Chunk {
    pub v: Vec<Vertex>,
    pub i: Vec<u16>,
}

#[derive(Default)]
pub struct MatGeo {
    pub chunks: Vec<Chunk>,
}

impl MatGeo {
    fn chunk_for(&mut self, need: usize) -> &mut Chunk {
        let full = match self.chunks.last() {
            Some(c) => c.v.len() + need > CHUNK_VERTS,
            None => true,
        };
        if full {
            self.chunks.push(Chunk::default());
        }
        self.chunks.last_mut().unwrap()
    }
}

#[derive(Default)]
pub struct TreeGeo {
    pub mats: HashMap<usize, MatGeo>,
    pub tris: usize,
    pub verts: usize,
    pub spines: usize,
    pub leaves: usize,
    pub bmin: Vec3,
    pub bmax: Vec3,
    pub per_node: HashMap<u32, usize>,
}

impl TreeGeo {
    fn grow(&mut self, p: Vec3) {
        self.bmin = self.bmin.min(p);
        self.bmax = self.bmax.max(p);
    }
}

fn vtx(p: Vec3, uv: Vec2, col: [u8; 4], n: Vec3, ao: f32) -> Vertex {
    Vertex { position: p, uv, color: col, normal: vec4(n.x, n.y, n.z, ao) }
}

#[derive(Clone, Copy)]
enum ParentRef {
    Ground,
    Spine(usize),
}

pub struct GenCtx<'a> {
    pub nodes: &'a [Node],
    pub materials: &'a [Material],
    pub meshes: &'a [LeafMesh],
    pub selected: Option<u32>,
    pub highlight: bool,
}

pub fn generate(ctx: &GenCtx) -> TreeGeo {
    let mut geo = TreeGeo { bmin: Vec3::splat(f32::MAX), bmax: Vec3::splat(f32::MIN), ..Default::default() };
    let mut spines: Vec<Spine> = vec![];
    let root = match ctx.nodes.iter().find(|n| n.kind == Kind::Tree) {
        Some(r) => r,
        None => return geo,
    };
    let tree = root.p.clone();
    let lod = tree.lod_preview.max(0) as usize;
    let mut leaf_ranges: Vec<(usize, usize, usize)> = vec![]; // (material, chunk, vertex start)
    process(ctx, root.id, &[ParentRef::Ground], &tree, &mut spines, &mut geo, lod, &mut leaf_ranges);
    if geo.bmin.x > geo.bmax.x {
        geo.bmin = vec3(-5.0, 0.0, -5.0);
        geo.bmax = vec3(5.0, 10.0, 5.0);
    }
    // ambient occlusion for leaves: deeper inside the crown is darker
    let c = (geo.bmin + geo.bmax) * 0.5;
    let half = ((geo.bmax - geo.bmin) * 0.5).max(Vec3::splat(0.5));
    for (m, ci, start) in leaf_ranges {
        if let Some(mg) = geo.mats.get_mut(&m) {
            let ch = &mut mg.chunks[ci];
            let end = ch.v.len();
            for v in &mut ch.v[start..end] {
                let d = (v.position - c) / half;
                let r = (d.x * d.x + d.z * d.z).sqrt().min(1.0);
                let h = ((v.position.y - geo.bmin.y) / (half.y * 2.0)).clamp(0.0, 1.0);
                let ao = (0.35 + 0.45 * r.powf(0.8) + 0.25 * h).min(1.0);
                v.normal.w = v.normal.w.min(ao);
            }
        }
    }
    geo
}

#[allow(clippy::too_many_arguments)]
fn process(
    ctx: &GenCtx,
    node_id: u32,
    parents: &[ParentRef],
    tree: &Params,
    spines: &mut Vec<Spine>,
    geo: &mut TreeGeo,
    lod: usize,
    leaf_ranges: &mut Vec<(usize, usize, usize)>,
) {
    let children: Vec<&Node> = ctx.nodes.iter().filter(|n| n.parent == Some(node_id)).collect();
    for child in children {
        if child.hidden {
            continue;
        }
        let sel = ctx.highlight && ctx.selected == Some(child.id);
        let col: [u8; 4] = if sel { [255, 196, 120, 255] } else { [255, 255, 255, 255] };
        let p = &child.p;
        let mut new_spines: Vec<ParentRef> = vec![];
        let mut count = 0usize;
        for (pi, parent) in parents.iter().enumerate() {
            let mut rng = Rng::new((p.seed as u64) * 7919 + pi as u64 * 104729 + child.id as u64 * 31);
            let placements = distribute(p, *parent, spines, tree, &mut rng);
            for (t, roll, base_pos, azim_dir) in placements {
                match child.kind {
                    Kind::Trunk | Kind::Branch => {
                        if let Some(s) = make_spine(child, p, *parent, t, roll, base_pos, azim_dir, spines, &mut rng) {
                            skin(&s, p, col, geo, child.kind == Kind::Trunk);
                            spines.push(s);
                            new_spines.push(ParentRef::Spine(spines.len() - 1));
                            count += 1;
                        }
                    }
                    Kind::Leaf => {
                        make_leaf(ctx, p, *parent, t, roll, base_pos, spines, &mut rng, col, geo, lod, leaf_ranges);
                        count += 1;
                    }
                    Kind::Tree => {}
                }
            }
        }
        geo.per_node.insert(child.id, count);
        if child.kind.makes_spines() {
            geo.spines += count;
            if !new_spines.is_empty() {
                process(ctx, child.id, &new_spines, tree, spines, geo, lod, leaf_ranges);
            }
        } else if child.kind == Kind::Leaf {
            geo.leaves += count;
        }
    }
}

/// Where children go on a parent: (position along parent 0..1, roll angle in radians,
/// ground position, ground outward direction).
fn distribute(p: &Params, parent: ParentRef, spines: &[Spine], tree: &Params, rng: &mut Rng) -> Vec<(f32, f32, Vec3, Vec3)> {
    let mut out = vec![];
    let plen = match parent {
        ParentRef::Spine(i) => spines[i].len,
        ParentRef::Ground => 0.0,
    };
    let span = (p.last - p.first).max(0.0);
    let mut count = match p.gen_mode {
        MODE_ABSOLUTE => p.number.max(0) as f32,
        MODE_INTERVAL | MODE_PHYLLOTAXY => {
            if matches!(parent, ParentRef::Ground) {
                p.number.max(0) as f32
            } else {
                (plen * span / p.interval.max(0.05)).floor() + 1.0
            }
        }
        _ => p.frequency.max(0.0),
    };
    // fractional counts become a chance of one more
    let frac = count.fract();
    count = count.floor() + if rng.next() < frac { 1.0 } else { 0.0 };
    let n = (count as usize).min(2000);
    let spiral = p.spiral.to_radians();
    match parent {
        ParentRef::Ground => {
            for i in 0..n {
                let ang = i as f32 * spiral + p.roll_var.to_radians() * rng.sym();
                let dir = vec3(ang.cos(), 0.0, ang.sin());
                let r = if n <= 1 { 0.0 } else { tree.tree_radius * 0.5 * ((i as f32 + 0.5) / n as f32).sqrt() };
                out.push((0.0, ang, dir * r, dir));
            }
        }
        ParentRef::Spine(_) => {
            if p.gen_mode == MODE_PHYLLOTAXY {
                let per = p.per_node.max(1) as usize;
                for k in 0..n {
                    let t = if n <= 1 { p.first } else { p.first + span * k as f32 / (n - 1) as f32 };
                    for j in 0..per {
                        let roll = k as f32 * spiral + j as f32 * 2.0 * PI / per as f32 + p.roll_var.to_radians() * rng.sym();
                        out.push((t.clamp(0.0, 1.0), roll, Vec3::ZERO, Vec3::X));
                    }
                }
            } else {
                for i in 0..n {
                    let jit = p.jumble * rng.sym() * 0.5;
                    let t = p.first + span * ((i as f32 + 0.5 + jit) / n.max(1) as f32);
                    let roll = i as f32 * spiral + p.roll_var.to_radians() * rng.sym();
                    out.push((t.clamp(0.0, 1.0), roll, Vec3::ZERO, Vec3::X));
                }
            }
        }
    }
    out
}

#[allow(clippy::too_many_arguments)]
fn make_spine(
    node: &Node,
    p: &Params,
    parent: ParentRef,
    t: f32,
    roll: f32,
    ground_pos: Vec3,
    ground_dir: Vec3,
    spines: &[Spine],
    rng: &mut Rng,
) -> Option<Spine> {
    let angle = (p.start_angle + p.angle_var * rng.sym() + p.angle_profile * (t - 0.5)).clamp(0.0, 1.0) * PI;
    let (start, dir, plen, prad) = match parent {
        ParentRef::Ground => {
            // start angle measured up from the ground: 0.5 = straight up
            let d = (Vec3::Y * angle.sin() + ground_dir * angle.cos()).normalize();
            (ground_pos, d, 0.0, 0.0)
        }
        ParentRef::Spine(i) => {
            let ps = &spines[i];
            let (tn, n, b) = ps.frame(t);
            let perp = n * roll.cos() + b * roll.sin();
            let d = (tn * angle.cos() + perp * angle.sin()).normalize();
            (ps.point(t), d, ps.len, ps.radius(t))
        }
    };
    let prof = 1.0 - p.len_profile * ((t - p.first) / (p.last - p.first).max(0.01)).clamp(0.0, 1.0);
    let len = ((p.len_abs + p.len_pct * plen) * prof * (1.0 + p.len_var * rng.sym()) * p.size_scalar).max(0.0);
    if len < 0.05 {
        return None;
    }
    let mut r0 = (p.radius_abs + p.radius_pct * prad) * (1.0 + p.radius_var * rng.sym()) * p.size_scalar;
    if p.clamp_parent && prad > 0.0 {
        r0 = r0.min(prad * 0.95);
    }
    r0 = r0.max(0.005);
    let n = p.seg_len.clamp(2, 64) as usize;
    let step = len / n as f32;
    let f = 0.6 + 4.0 * p.noise_turb;
    let ph = [rng.next() * 6.28, rng.next() * 6.28, rng.next() * 6.28];
    let mut pts = Vec::with_capacity(n + 1);
    let mut d = dir;
    let mut pos = start;
    pts.push(pos);
    for k in 0..n {
        let kk = k as f32;
        let noise = vec3((kk * f + ph[0]).sin(), (kk * f * 1.13 + ph[1]).sin() * 0.5, (kk * f * 0.87 + ph[2]).sin());
        d = (d + noise * p.noise_amt * 1.6 / n as f32 + Vec3::NEG_Y * p.gravity * 2.5 / n as f32).normalize();
        if p.jink > 0.0 && rng.next() < 0.25 {
            d = (d + vec3(rng.sym(), rng.sym() * 0.3, rng.sym()) * p.jink * 0.5).normalize();
        }
        pos += d * step;
        pts.push(pos);
    }
    let _ = node;
    Some(build_spine(node.id, pts, r0, p))
}

fn build_spine(node: u32, pts: Vec<Vec3>, r0: f32, p: &Params) -> Spine {
    let m = pts.len();
    let mut cum = vec![0.0; m];
    for k in 1..m {
        cum[k] = cum[k - 1] + pts[k].distance(pts[k - 1]);
    }
    let len = cum[m - 1].max(1e-4);
    let mut tan = vec![Vec3::Y; m];
    for k in 0..m {
        let a = if k == 0 { pts[0] } else { pts[k - 1] };
        let b = if k == m - 1 { pts[m - 1] } else { pts[k + 1] };
        tan[k] = (b - a).normalize_or_zero();
    }
    let mut nrm = vec![Vec3::X; m];
    nrm[0] = any_perp(tan[0]);
    for k in 1..m {
        let n = nrm[k - 1] - tan[k] * nrm[k - 1].dot(tan[k]);
        nrm[k] = if n.length_squared() > 1e-8 { n.normalize() } else { any_perp(tan[k]) };
    }
    let rad = (0..m)
        .map(|k| {
            let s = cum[k] / len;
            let mut r = r0 * (1.0 - (1.0 - p.taper) * s.powf(0.9));
            if s < 0.18 {
                let q = 1.0 - s / 0.18;
                r *= 1.0 + p.flare * q * q;
            }
            r
        })
        .collect();
    Spine { node, pts, rad, tan, nrm, cum, len }
}

fn skin(s: &Spine, p: &Params, col: [u8; 4], geo: &mut TreeGeo, trunk: bool) {
    let radial = p.seg_radial.clamp(3, 48) as usize;
    let m = s.pts.len();
    let need = m * (radial + 1) + 1;
    let r0 = s.rad[0].max(0.01);
    let mat = geo.mats.entry(p.material).or_default();
    let ch = mat.chunk_for(need);
    let base = ch.v.len();
    let mut bmin = Vec3::splat(f32::MAX);
    let mut bmax = Vec3::splat(f32::MIN);
    for k in 0..m {
        let tn = s.tan[k];
        let n = s.nrm[k];
        let b = tn.cross(n);
        let sfrac = s.cum[k] / s.len;
        let v = s.cum[k] / (2.0 * PI * r0) * p.v_tile;
        let ao = if trunk { 0.8 + 0.2 * sfrac } else { 0.62 + 0.38 * sfrac };
        for j in 0..=radial {
            let a = j as f32 / radial as f32 * 2.0 * PI;
            let dir = n * a.cos() + b * a.sin();
            let pos = s.pts[k] + dir * s.rad[k];
            bmin = bmin.min(pos);
            bmax = bmax.max(pos);
            ch.v.push(vtx(pos, vec2(j as f32 / radial as f32 * p.u_tile, v), col, dir, ao));
        }
    }
    for k in 0..m - 1 {
        for j in 0..radial {
            let a = (base + k * (radial + 1) + j) as u16;
            let b = a + 1;
            let c = a + (radial + 1) as u16;
            let d = c + 1;
            ch.i.extend_from_slice(&[a, c, b, b, c, d]);
        }
    }
    // tip cap
    let tip = s.pts[m - 1] + s.tan[m - 1] * s.rad[m - 1] * 0.5;
    let ci = ch.v.len() as u16;
    ch.v.push(vtx(tip, vec2(0.5, s.cum[m - 1] / (2.0 * PI * r0) * p.v_tile), col, s.tan[m - 1], 1.0));
    let last = (base + (m - 1) * (radial + 1)) as u16;
    for j in 0..radial as u16 {
        ch.i.extend_from_slice(&[last + j, ci, last + j + 1]);
    }
    geo.tris += (m - 1) * radial * 2 + radial;
    geo.verts += need;
    geo.grow(bmin);
    geo.grow(bmax);
}

#[allow(clippy::too_many_arguments)]
fn make_leaf(
    ctx: &GenCtx,
    p: &Params,
    parent: ParentRef,
    t: f32,
    roll: f32,
    ground_pos: Vec3,
    spines: &[Spine],
    rng: &mut Rng,
    col: [u8; 4],
    geo: &mut TreeGeo,
    lod: usize,
    leaf_ranges: &mut Vec<(usize, usize, usize)>,
) {
    let angle = (p.start_angle + p.angle_var * rng.sym()).clamp(0.0, 1.0) * PI;
    let (base, tn, perp, plen) = match parent {
        ParentRef::Ground => (ground_pos, Vec3::Y, vec3(roll.cos(), 0.0, roll.sin()), 0.0),
        ParentRef::Spine(i) => {
            let s = &spines[i];
            let (tn, n, b) = s.frame(t);
            let perp = n * roll.cos() + b * roll.sin();
            (s.point(t) + perp * s.radius(t) * 0.8, tn, perp, s.len)
        }
    };
    let mut out = (tn * angle.cos() + perp * angle.sin()).normalize();
    out = (out + Vec3::NEG_Y * p.droop).normalize_or_zero();
    if out.length_squared() < 0.5 {
        out = perp;
    }
    let side = tn.cross(perp).normalize_or_zero();
    let mut nrm = out.cross(side).normalize_or_zero();
    if nrm.length_squared() < 0.5 {
        nrm = any_perp(out);
    }
    if nrm.y < 0.0 {
        nrm = -nrm;
    }
    let up_o = (Vec3::Y - out * Vec3::Y.dot(out)).normalize_or_zero();
    nrm = (nrm * (1.0 - p.face_sky) + up_o * p.face_sky).normalize_or_zero();
    nrm = (nrm - out * nrm.dot(out)).normalize_or_zero();
    if nrm.length_squared() < 0.5 {
        nrm = any_perp(out);
    }
    if p.leaf_twist != 0.0 {
        let q = Quat::from_axis_angle(out, p.leaf_twist * PI * (0.5 + 0.5 * rng.next()));
        nrm = q * nrm;
    }
    let right = out.cross(nrm).normalize_or_zero();
    let size = ((p.leaf_size + p.leaf_size_pct * plen) * (1.0 + p.leaf_size_var * rng.sym()) * p.size_scalar).max(0.01);

    // outline in texture space
    let (outline, anchor, mscale, flip) = if p.leaf_mesh >= 1 && p.leaf_mesh <= ctx.meshes.len() {
        let m = &ctx.meshes[p.leaf_mesh - 1];
        let l = lod.min(m.lods.len().saturating_sub(1));
        (m.lods[l].clone(), m.anchor, m.scale, m.flip)
    } else {
        (vec![vec2(0.0, 0.0), vec2(0.5, 0.0), vec2(1.0, 0.0), vec2(1.0, 1.0), vec2(0.5, 1.0), vec2(0.0, 1.0)], vec2(0.5, 1.0), 1.0, false)
    };
    if outline.len() < 3 {
        return;
    }
    let tris = triangulate(&outline);
    // subdivide once so folding and curling bend smoothly
    let mut uvs: Vec<Vec2> = outline.clone();
    let mut faces: Vec<[usize; 3]> = vec![];
    let mut mid: HashMap<(usize, usize), usize> = HashMap::new();
    let mut midp = |a: usize, b: usize, uvs: &mut Vec<Vec2>| -> usize {
        let key = if a < b { (a, b) } else { (b, a) };
        if let Some(&i) = mid.get(&key) {
            return i;
        }
        let m = (uvs[a] + uvs[b]) * 0.5;
        uvs.push(m);
        mid.insert(key, uvs.len() - 1);
        uvs.len() - 1
    };
    for tr in &tris {
        let ab = midp(tr[0], tr[1], &mut uvs);
        let bc = midp(tr[1], tr[2], &mut uvs);
        let ca = midp(tr[2], tr[0], &mut uvs);
        faces.push([tr[0], ab, ca]);
        faces.push([ab, tr[1], bc]);
        faces.push([ca, bc, tr[2]]);
        faces.push([ab, bc, ca]);
    }
    let fold = p.fold * PI * 0.5;
    let lsize = size * mscale;
    let mut pos: Vec<Vec3> = Vec::with_capacity(uvs.len());
    for uv in &uvs {
        let mut x = (uv.x - anchor.x) * lsize * p.scale_x;
        if flip {
            x = -x;
        }
        let y = (anchor.y - uv.y) * lsize * p.scale_y;
        let xf = x * fold.cos();
        let mut z = x.abs() * fold.sin();
        let yn = y / lsize.max(0.001);
        z += p.curl * yn * yn * lsize * 0.6;
        pos.push(base + right * xf + out * y + nrm * z);
    }
    let mut ns = vec![Vec3::ZERO; uvs.len()];
    for f in &faces {
        let fnn = (pos[f[1]] - pos[f[0]]).cross(pos[f[2]] - pos[f[0]]);
        for &i in f {
            ns[i] += fnn;
        }
    }
    let mut avg = Vec3::ZERO;
    for n in &ns {
        avg += *n;
    }
    let flipn = avg.dot(nrm) < 0.0;
    // material variation colour
    let mat_idx = p.leaf_material;
    let mut c = col;
    if let Some(m) = ctx.materials.get(mat_idx) {
        if m.variation > 0.0 {
            let vc = m.var_colors[(rng.next() * 3.0) as usize % 3];
            let mx = vc[0].max(vc[1]).max(vc[2]).max(0.01);
            for k in 0..3 {
                let mult = 1.0 + (vc[k] / mx - 1.0) * m.variation * 0.6;
                c[k] = (c[k] as f32 * mult.clamp(0.0, 1.0)) as u8;
            }
        }
    }
    let mg = geo.mats.entry(mat_idx).or_default();
    let ch = mg.chunk_for(uvs.len());
    let start = ch.v.len();
    for (k, uv) in uvs.iter().enumerate() {
        let mut n = ns[k].normalize_or_zero();
        if flipn {
            n = -n;
        }
        ch.v.push(vtx(pos[k], *uv, c, n, 1.0));
    }
    for f in &faces {
        if flipn {
            ch.i.extend_from_slice(&[(start + f[0]) as u16, (start + f[2]) as u16, (start + f[1]) as u16]);
        } else {
            ch.i.extend_from_slice(&[(start + f[0]) as u16, (start + f[1]) as u16, (start + f[2]) as u16]);
        }
    }
    let ci = mg.chunks.len() - 1;
    leaf_ranges.push((mat_idx, ci, start));
    geo.tris += faces.len();
    geo.verts += uvs.len();
    for q in &pos {
        geo.grow(*q);
    }
}

//! 3D viewport: camera, lit material shader, grid, and GPU mesh upload.
use crate::gen::TreeGeo;
use crate::model::Material;
use macroquad::miniquad::{BlendFactor, BlendState, BlendValue, Comparison, Equation, PipelineParams, UniformType};
use macroquad::models::Vertex;
use macroquad::prelude::*;
use std::f32::consts::PI;

pub const VIEWS: [&str; 7] = ["Perspective", "Front", "Back", "Left", "Right", "Top", "Bottom"];

pub struct Cam {
    pub yaw: f32,
    pub pitch: f32,
    pub dist: f32,
    pub target: Vec3,
    pub ortho: bool,
    pub view: usize,
    pub fov: f32,
}

impl Cam {
    pub fn new() -> Self {
        Cam { yaw: 0.6, pitch: 0.18, dist: 70.0, target: vec3(0.0, 14.0, 0.0), ortho: false, view: 0, fov: 45.0 }
    }
    pub fn set_view(&mut self, v: usize) {
        self.view = v;
        match v {
            0 => {
                self.ortho = false;
                self.yaw = 0.6;
                self.pitch = 0.18;
            }
            1 => self.set_axis(0.0, 0.0),
            2 => self.set_axis(PI, 0.0),
            3 => self.set_axis(-PI * 0.5, 0.0),
            4 => self.set_axis(PI * 0.5, 0.0),
            5 => self.set_axis(0.0, PI * 0.5 - 0.001),
            _ => self.set_axis(0.0, -PI * 0.5 + 0.001),
        }
    }
    fn set_axis(&mut self, yaw: f32, pitch: f32) {
        self.ortho = true;
        self.yaw = yaw;
        self.pitch = pitch;
    }
    pub fn dir(&self) -> Vec3 {
        vec3(self.yaw.sin() * self.pitch.cos(), self.pitch.sin(), self.yaw.cos() * self.pitch.cos())
    }
    pub fn position(&self) -> Vec3 {
        self.target + self.dir() * if self.ortho { self.dist.max(1.0) * 20.0 } else { self.dist }
    }
    pub fn view_name(&self) -> String {
        if self.view == 0 {
            if self.ortho { "User (orthographic)".into() } else { "Perspective".into() }
        } else {
            VIEWS[self.view].to_string()
        }
    }
    pub fn orbit(&mut self, dx: f32, dy: f32) {
        self.yaw -= dx * 0.008;
        self.pitch = (self.pitch + dy * 0.008).clamp(-1.55, 1.55);
        if self.view != 0 {
            self.view = 0; // leaves the named view; projection kept
        }
    }
    pub fn pan(&mut self, dx: f32, dy: f32, vp_h: f32) {
        let d = self.dir();
        let right = Vec3::Y.cross(d).normalize_or_zero();
        let up = d.cross(right).normalize_or_zero();
        let s = self.view_height() / vp_h.max(1.0);
        self.target += (right * dx + up * dy) * s;
    }
    pub fn zoom(&mut self, steps: f32) {
        self.dist = (self.dist * 0.88f32.powf(steps)).clamp(1.0, 2000.0);
    }
    pub fn view_height(&self) -> f32 {
        2.0 * self.dist * (self.fov.to_radians() * 0.5).tan()
    }
    pub fn frame(&mut self, bmin: Vec3, bmax: Vec3) {
        self.target = (bmin + bmax) * 0.5;
        let r = ((bmax - bmin).length() * 0.5).max(1.0);
        self.dist = r / (self.fov.to_radians() * 0.5).sin() * 1.05;
    }
    pub fn camera3d(&self, viewport: Option<(i32, i32, i32, i32)>, aspect: f32, rt: Option<RenderTarget>) -> Camera3D {
        let pos = self.position();
        let up = if self.pitch.abs() > 1.5 { vec3(-self.yaw.sin(), 0.0, -self.yaw.cos()) * self.pitch.signum() } else { Vec3::Y };
        Camera3D {
            position: pos,
            target: self.target,
            up,
            fovy: if self.ortho { self.view_height() } else { self.fov.to_radians() },
            aspect: Some(aspect),
            projection: if self.ortho { Projection::Orthographics } else { Projection::Perspective },
            render_target: rt,
            viewport,
            z_near: if self.ortho { 1.0 } else { (self.dist * 0.01).max(0.05) },
            z_far: if self.ortho { self.dist.max(1.0) * 60.0 } else { self.dist * 40.0 + 500.0 },
        }
    }
}

const VS: &str = r#"#version 100
attribute vec3 position;
attribute vec2 texcoord;
attribute vec4 color0;
attribute vec4 normal;
varying lowp vec4 color;
varying mediump vec2 uv;
varying mediump vec3 vn;
varying mediump vec3 wp;
varying mediump float occ;
uniform mat4 Model;
uniform mat4 Projection;
void main() {
    vec4 w = Model * vec4(position, 1.0);
    gl_Position = Projection * w;
    wp = w.xyz;
    vn = normal.xyz;
    occ = normal.w;
    uv = texcoord;
    color = color0 / 255.0;
}"#;

const FS: &str = r#"#version 100
precision mediump float;
varying lowp vec4 color;
varying mediump vec2 uv;
varying mediump vec3 vn;
varying mediump vec3 wp;
varying mediump float occ;
uniform sampler2D Texture;
uniform vec4 Tint;
uniform vec3 LightDir;
uniform vec3 CamPos;
uniform float Cutoff;
uniform float Gloss;
uniform float Specular;
uniform float Metallic;
uniform vec4 SubColor;
uniform float AOAmount;
uniform float TwoSided;
uniform float Bump;
uniform float Unlit;
void main() {
    vec4 tex = texture2D(Texture, uv);
    if (tex.a < Cutoff) discard;
    vec3 n = normalize(vn);
    if (!gl_FrontFacing) {
        if (TwoSided < 0.5) { n = -n; } else { n = -n; }
    }
    if (Bump > 0.0) {
        float e = 1.0 / 256.0;
        float h0 = dot(tex.rgb, vec3(0.33));
        float hx = dot(texture2D(Texture, uv + vec2(e, 0.0)).rgb, vec3(0.33));
        float hy = dot(texture2D(Texture, uv + vec2(0.0, e)).rgb, vec3(0.33));
        vec3 t = abs(n.y) < 0.95 ? normalize(cross(n, vec3(0.0, 1.0, 0.0))) : normalize(cross(n, vec3(1.0, 0.0, 0.0)));
        vec3 b = cross(n, t);
        n = normalize(n - Bump * 6.0 * ((hx - h0) * t + (hy - h0) * b));
    }
    vec3 base = tex.rgb * Tint.rgb * color.rgb;
    if (Unlit > 0.5) { gl_FragColor = vec4(base, 1.0); return; }
    vec3 L = normalize(LightDir);
    float ndl = dot(n, L);
    float diff = max(ndl, 0.0);
    vec3 V = normalize(CamPos - wp);
    vec3 H = normalize(L + V);
    float sp = pow(max(dot(n, H), 0.0), mix(4.0, 96.0, Gloss)) * Specular * (0.4 + Gloss);
    float ao = mix(1.0, occ, AOAmount);
    vec3 sky = vec3(0.50, 0.55, 0.62) * (0.65 + 0.35 * n.y);
    vec3 amb = base * sky * 0.75;
    vec3 sun = vec3(1.0, 0.96, 0.88);
    vec3 dif = base * sun * diff * (1.0 - Metallic * 0.6);
    vec3 trans = base * SubColor.rgb * SubColor.a * max(-ndl, 0.0) * 1.4 * TwoSided;
    vec3 spec = sp * mix(vec3(1.0), base * 2.0, Metallic) * sun;
    vec3 c = (amb + dif + trans) * ao + spec * ao;
    c = pow(c, vec3(0.92));
    gl_FragColor = vec4(c, 1.0);
}"#;

pub fn make_material() -> Result<macroquad::material::Material, String> {
    let uniforms = vec![
        UniformDesc::new("Tint", UniformType::Float4),
        UniformDesc::new("LightDir", UniformType::Float3),
        UniformDesc::new("CamPos", UniformType::Float3),
        UniformDesc::new("Cutoff", UniformType::Float1),
        UniformDesc::new("Gloss", UniformType::Float1),
        UniformDesc::new("Specular", UniformType::Float1),
        UniformDesc::new("Metallic", UniformType::Float1),
        UniformDesc::new("SubColor", UniformType::Float4),
        UniformDesc::new("AOAmount", UniformType::Float1),
        UniformDesc::new("TwoSided", UniformType::Float1),
        UniformDesc::new("Bump", UniformType::Float1),
        UniformDesc::new("Unlit", UniformType::Float1),
    ];
    let _ = BlendState::new(Equation::Add, BlendFactor::Value(BlendValue::SourceAlpha), BlendFactor::OneMinusValue(BlendValue::SourceAlpha));
    load_material(
        ShaderSource::Glsl { vertex: VS, fragment: FS },
        MaterialParams {
            pipeline_params: PipelineParams {
                depth_test: Comparison::LessOrEqual,
                depth_write: true,
                ..Default::default()
            },
            uniforms,
            textures: vec![],
        },
    )
    .map_err(|e| format!("{:?}", e))
}

pub struct Lighting {
    pub azimuth: f32,
    pub elevation: f32,
    pub unlit: bool,
}

impl Lighting {
    pub fn dir(&self) -> Vec3 {
        let a = self.azimuth.to_radians();
        let e = self.elevation.to_radians();
        vec3(a.sin() * e.cos(), e.sin(), a.cos() * e.cos())
    }
}

pub fn apply_material(gm: &macroquad::material::Material, m: &Material, light: &Lighting, cam_pos: Vec3) {
    gm.set_uniform("Tint", vec4(m.color[0], m.color[1], m.color[2], 1.0));
    gm.set_uniform("LightDir", light.dir());
    gm.set_uniform("CamPos", cam_pos);
    gm.set_uniform("Cutoff", if m.opacity_from_alpha { m.cutoff.max(0.01) } else { 0.0 });
    gm.set_uniform("Gloss", m.gloss);
    gm.set_uniform("Specular", m.specular);
    gm.set_uniform("Metallic", m.metallic);
    gm.set_uniform("SubColor", vec4(m.sss_color[0], m.sss_color[1], m.sss_color[2], m.sss_amount));
    gm.set_uniform("AOAmount", m.ao);
    gm.set_uniform("TwoSided", if m.two_sided { 1.0f32 } else { 0.0f32 });
    gm.set_uniform("Bump", m.normal_strength);
    gm.set_uniform("Unlit", if light.unlit { 1.0f32 } else { 0.0f32 });
}

/// GPU-ready meshes per material, rebuilt whenever the tree changes.
pub struct GpuTree {
    pub parts: Vec<(usize, Vec<Mesh>)>,
}

pub fn upload(geo: &TreeGeo) -> GpuTree {
    let mut parts = vec![];
    let mut keys: Vec<usize> = geo.mats.keys().cloned().collect();
    keys.sort();
    for k in keys {
        let mg = &geo.mats[&k];
        let meshes = mg
            .chunks
            .iter()
            .filter(|c| !c.i.is_empty())
            .map(|c| Mesh { vertices: c.v.clone(), indices: c.i.clone(), texture: None })
            .collect();
        parts.push((k, meshes));
    }
    GpuTree { parts }
}

