//! The Properties panel: rows of labelled controls, grouped like the original's property editor.
use crate::app::{App, Sel};
use crate::model::*;
use crate::render::VIEWS;
use crate::textures;
use crate::ui::*;
use macroquad::prelude::*;

pub struct Rows<'a> {
    pub ui: &'a mut Ui,
    pub x: f32,
    pub y: f32,
    pub w: f32,
    pub changed: bool,
    pub prefix: String,
    pub closed: &'a mut std::collections::HashSet<String>,
    open: bool,
}

const RH: f32 = 24.0;

impl<'a> Rows<'a> {
    fn lw(&self) -> f32 {
        (self.w * 0.46).floor()
    }
    fn key(&self, k: &str) -> String {
        format!("{}.{}", self.prefix, k)
    }
    pub fn group(&mut self, title: &str) -> bool {
        let key = self.key(&format!("grp.{}", title));
        let r = Rect::new(self.x - 6.0, self.y + 4.0, self.w + 12.0, 24.0);
        self.ui.record(&format!("grp:{}", title), r);
        let open = !self.closed.contains(&key);
        let hot = self.ui.hover(r);
        draw_rectangle(r.x, r.y, r.w, r.h, if hot { Color::new(1.0, 1.0, 1.0, 0.08) } else { Color::new(1.0, 1.0, 1.0, 0.04) });
        let ax = r.x + 12.0;
        let ay = r.y + 12.0;
        if open {
            draw_triangle(vec2(ax - 4.0, ay - 2.0), vec2(ax + 4.0, ay - 2.0), vec2(ax, ay + 3.0), C_TEXT_DIM);
        } else {
            draw_triangle(vec2(ax - 2.0, ay - 4.0), vec2(ax - 2.0, ay + 4.0), vec2(ax + 3.0, ay), C_TEXT_DIM);
        }
        self.ui.text(title, r.x + 22.0, r.y + 5.0, 13.5, WHITE);
        if hot && self.ui.inp.l_pressed {
            if open {
                self.closed.insert(key);
            } else {
                self.closed.remove(&key);
            }
        }
        self.y += 32.0;
        self.open = open;
        open
    }
    fn label(&mut self, label: &str) -> Rect {
        let lw = self.lw();
        self.ui.text_fit(label, self.x + 6.0, self.y + 5.0, lw - 10.0, 12.5, C_TEXT_DIM);
        Rect::new(self.x + lw, self.y + 2.0, self.w - lw, RH - 4.0)
    }
    pub fn f(&mut self, k: &str, label: &str, v: &mut f32, min: f32, max: f32, dec: usize) {
        let r = self.label(label);
        let key = self.key(k);
        if self.ui.slider(&key, r, v, min, max, dec) {
            self.changed = true;
        }
        self.y += RH;
    }
    pub fn i(&mut self, k: &str, label: &str, v: &mut i32, min: i32, max: i32) {
        let r = self.label(label);
        let key = self.key(k);
        if self.ui.islider(&key, r, v, min, max) {
            self.changed = true;
        }
        self.y += RH;
    }
    pub fn b(&mut self, k: &str, label: &str, v: &mut bool) {
        let r = self.label(label);
        let key = self.key(k);
        if self.ui.checkbox(&key, r, v) {
            self.changed = true;
        }
        self.y += RH;
    }
    pub fn combo(&mut self, k: &str, label: &str, items: &[String], v: &mut usize) {
        let r = self.label(label);
        let key = self.key(k);
        if self.ui.combo(&key, r, items, v) {
            self.changed = true;
        }
        self.y += RH;
    }
    pub fn color(&mut self, k: &str, label: &str, c: &mut [f32; 3]) {
        let r = self.label(label);
        draw_rectangle(r.x, r.y, 26.0, r.h, Color::new(c[0], c[1], c[2], 1.0));
        draw_rectangle_lines(r.x, r.y, 26.0, r.h, 1.0, C_LINE);
        let sw = (r.w - 32.0) / 3.0;
        let names = ["r", "g", "b"];
        for i in 0..3 {
            let rr = Rect::new(r.x + 30.0 + i as f32 * (sw + 1.0), r.y, sw - 1.0, r.h);
            let key = self.key(&format!("{}.{}", k, names[i]));
            if self.ui.slider(&key, rr, &mut c[i], 0.0, 1.0, 2) {
                self.changed = true;
            }
        }
        self.y += RH;
    }
    pub fn button(&mut self, k: &str, label: &str) -> bool {
        let r = Rect::new(self.x + self.lw(), self.y + 2.0, self.w - self.lw(), RH - 4.0);
        let key = self.key(k);
        let c = self.ui.button(&key, r, label);
        self.y += RH;
        c
    }
    pub fn info(&mut self, label: &str, value: &str) {
        let r = self.label(label);
        self.ui.text_fit(value, r.x + 4.0, r.y + 3.0, r.w - 6.0, 12.5, C_TEXT);
        self.y += RH;
    }
    pub fn note(&mut self, text: &str) {
        self.ui.text_fit(text, self.x + 6.0, self.y + 4.0, self.w - 8.0, 12.0, C_TEXT_FAINT);
        self.y += 20.0;
    }
}

fn mode_rows(r: &mut Rows, p: &mut Params, on_ground: bool) {
    let modes: Vec<String> = GEN_MODES.iter().map(|s| s.to_string()).collect();
    r.combo("gen_mode", "Mode", &modes, &mut p.gen_mode);
    match p.gen_mode {
        MODE_ABSOLUTE => r.i("number", "Number", &mut p.number, 0, 60),
        MODE_INTERVAL => {
            if on_ground {
                r.i("number", "Number", &mut p.number, 0, 60);
            } else {
                r.f("interval", "Interval (spacing)", &mut p.interval, 0.1, 20.0, 2);
            }
        }
        MODE_PHYLLOTAXY => {
            if on_ground {
                r.i("number", "Number", &mut p.number, 0, 60);
            } else {
                r.f("interval", "Internode length", &mut p.interval, 0.1, 20.0, 2);
                r.i("per_node", "Children per node", &mut p.per_node, 1, 12);
            }
        }
        _ => r.f("frequency", "Frequency", &mut p.frequency, 0.0, 120.0, 1),
    }
    if !on_ground {
        r.f("first", "First", &mut p.first, 0.0, 1.0, 3);
        r.f("last", "Last", &mut p.last, 0.0, 1.0, 3);
        r.f("jumble", "Jumble", &mut p.jumble, 0.0, 1.0, 2);
    }
    r.f("spiral", "Spiral (roll step)", &mut p.spiral, 0.0, 360.0, 1);
    r.f("roll_var", "Roll variance", &mut p.roll_var, 0.0, 180.0, 1);
    r.f("size_scalar", "Size scalar", &mut p.size_scalar, 0.1, 3.0, 2);
}

fn seed_rows(r: &mut Rows, p: &mut Params) {
    r.i("seed", "Generation seed", &mut p.seed, 0, 9999);
    if r.button("rand", "Randomize") {
        p.seed = (macroquad::rand::gen_range(0, 9999)) as i32;
        r.changed = true;
    }
}

pub fn node_props(r: &mut Rows, n: &mut Node, on_ground: bool, mat_names: &[String], mesh_names: &[String], stats: (usize, usize, usize, usize), count: usize) {
    let kind = n.kind;
    let p = &mut n.p;
    match kind {
        Kind::Tree => {
            if r.group("Shape") {
                r.f("tree_radius", "Radius (trunk spread)", &mut p.tree_radius, 0.0, 60.0, 1);
            }
            if r.group("Level of Detail") {
                r.i("lod_preview", "Preview leaf LOD", &mut p.lod_preview, 0, 3);
            }
            if r.group("Statistics") {
                r.info("Triangles", &stats.0.to_string());
                r.info("Vertices", &stats.1.to_string());
                r.info("Branches", &stats.2.to_string());
                r.info("Leaves", &stats.3.to_string());
            }
        }
        Kind::Trunk | Kind::Branch => {
            if r.group("Generation") {
                mode_rows(r, p, on_ground);
                seed_rows(r, p);
                r.info("Instances", &count.to_string());
            }
            if r.group("Spine") {
                r.f("len_abs", "Length: absolute", &mut p.len_abs, 0.0, 100.0, 2);
                r.f("len_pct", "Length: + % of parent", &mut p.len_pct, 0.0, 1.5, 3);
                r.f("len_var", "Length variance", &mut p.len_var, 0.0, 1.0, 2);
                r.f("len_profile", "Shorter toward parent end", &mut p.len_profile, 0.0, 1.0, 2);
                r.f("start_angle", "Start angle", &mut p.start_angle, 0.0, 1.0, 3);
                r.f("angle_var", "Start angle variance", &mut p.angle_var, 0.0, 0.5, 3);
                r.f("angle_profile", "Angle change along parent", &mut p.angle_profile, -1.0, 1.0, 2);
                r.f("gravity", "Gravity", &mut p.gravity, -1.0, 1.0, 2);
                r.f("noise_amt", "Noise amount", &mut p.noise_amt, 0.0, 3.0, 2);
                r.f("noise_turb", "Noise turbulence", &mut p.noise_turb, 0.0, 1.0, 2);
                r.f("jink", "Jink", &mut p.jink, 0.0, 1.0, 2);
            }
            if r.group("Skin") {
                r.f("radius_abs", "Radius: absolute", &mut p.radius_abs, 0.0, 10.0, 3);
                r.f("radius_pct", "Radius: + % of parent", &mut p.radius_pct, 0.0, 1.5, 3);
                r.f("radius_var", "Radius variance", &mut p.radius_var, 0.0, 1.0, 2);
                r.f("taper", "Tip radius (taper)", &mut p.taper, 0.0, 1.0, 2);
                r.f("flare", "Base flare", &mut p.flare, 0.0, 3.0, 2);
                r.b("clamp", "Clamp to parent", &mut p.clamp_parent);
            }
            if r.group("Segments") {
                r.i("seg_len", "Length segments", &mut p.seg_len, 2, 64);
                r.i("seg_radial", "Radial segments", &mut p.seg_radial, 3, 32);
            }
            if r.group("Materials") {
                let mut m = p.material.min(mat_names.len().saturating_sub(1));
                r.combo("material", "Branch material", mat_names, &mut m);
                p.material = m;
                r.f("u_tile", "U tiling", &mut p.u_tile, 0.1, 8.0, 2);
                r.f("v_tile", "V tiling", &mut p.v_tile, 0.1, 8.0, 2);
            }
        }
        Kind::Leaf => {
            if r.group("Generation") {
                mode_rows(r, p, on_ground);
                seed_rows(r, p);
                r.info("Instances", &count.to_string());
            }
            if r.group("Leaves") {
                r.f("leaf_size", "Size", &mut p.leaf_size, 0.0, 10.0, 2);
                r.f("leaf_size_pct", "Size: + % of parent", &mut p.leaf_size_pct, 0.0, 0.5, 3);
                r.f("leaf_size_var", "Size variance", &mut p.leaf_size_var, 0.0, 1.0, 2);
                let mut mi = p.leaf_mesh.min(mesh_names.len().saturating_sub(1));
                r.combo("leaf_mesh", "Mesh", mesh_names, &mut mi);
                p.leaf_mesh = mi;
                let mut ma = p.leaf_material.min(mat_names.len().saturating_sub(1));
                r.combo("leaf_material", "Material", mat_names, &mut ma);
                p.leaf_material = ma;
            }
            if r.group("Local Orientation") {
                r.f("start_angle", "Angle from parent", &mut p.start_angle, 0.0, 1.0, 3);
                r.f("angle_var", "Angle variance", &mut p.angle_var, 0.0, 0.5, 3);
                r.f("face_sky", "Face sky", &mut p.face_sky, 0.0, 1.0, 2);
                r.f("droop", "Droop", &mut p.droop, -1.0, 1.0, 2);
                r.f("leaf_twist", "Twist", &mut p.leaf_twist, -1.0, 1.0, 2);
            }
            if r.group("Deformation") {
                r.f("fold", "Fold", &mut p.fold, -1.0, 1.0, 2);
                r.f("curl", "Curl", &mut p.curl, -1.0, 1.0, 2);
                r.f("scale_x", "Scale X (width)", &mut p.scale_x, 0.1, 3.0, 2);
                r.f("scale_y", "Scale Y (length)", &mut p.scale_y, 0.1, 3.0, 2);
            }
        }
    }
}

/// Material properties. Returns (tree needs rebuild, texture needs rebuild, base needs reload).
pub fn material_props(r: &mut Rows, m: &mut Material, mesh_names: &[String]) -> (bool, bool, bool) {
    let mut tex = false;
    let mut base = false;
    if r.group("General") {
        r.info("Name", &m.name.clone());
        r.b("two_sided", "Two sided", &mut m.two_sided);
    }
    if r.group("Color") {
        r.color("color", "Tint", &mut m.color);
        let src: Vec<String> = MAP_SOURCES.iter().map(|s| s.to_string()).collect();
        let before = r.changed;
        r.changed = false;
        r.combo("source", "Texture", &src, &mut m.source);
        if r.changed {
            base = true;
            if m.source == 4 && m.file.is_empty() {
                if let Some(f) = pick_image() {
                    m.file = f;
                }
            }
        }
        r.changed |= before;
        if m.source == 4 {
            let fname = std::path::Path::new(&m.file).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| "(none)".into());
            r.info("File", &fname);
            if r.button("load", "Load image...") {
                if let Some(f) = pick_image() {
                    m.file = f;
                    base = true;
                    r.changed = true;
                }
            }
        }
        let before = r.changed;
        r.changed = false;
        r.f("brightness", "Brightness", &mut m.brightness, -1.0, 1.0, 2);
        r.f("contrast", "Contrast", &mut m.contrast, -1.0, 1.0, 2);
        r.f("saturation", "Saturation", &mut m.saturation, -1.0, 1.0, 2);
        r.f("hue", "Hue shift", &mut m.hue, -0.5, 0.5, 2);
        if r.changed {
            tex = true;
        }
        r.changed |= before;
    }
    if r.group("Opacity") {
        let before = r.changed;
        r.changed = false;
        r.b("alpha", "Use texture alpha", &mut m.opacity_from_alpha);
        if r.changed {
            tex = true;
        }
        r.changed |= before;
        r.f("cutoff", "Alpha cutoff", &mut m.cutoff, 0.0, 1.0, 2);
    }
    if r.group("Normal") {
        r.f("bump", "Bump strength", &mut m.normal_strength, 0.0, 3.0, 2);
    }
    if r.group("Gloss / Specular") {
        r.f("gloss", "Gloss", &mut m.gloss, 0.0, 1.0, 2);
        r.f("specular", "Specular", &mut m.specular, 0.0, 1.0, 2);
        r.f("metallic", "Metallic", &mut m.metallic, 0.0, 1.0, 2);
    }
    if r.group("Subsurface") {
        r.color("sss_color", "Color", &mut m.sss_color);
        r.f("sss_amount", "Amount", &mut m.sss_amount, 0.0, 1.0, 2);
    }
    if r.group("AO") {
        r.f("ao", "Amount", &mut m.ao, 0.0, 1.0, 2);
    }
    if r.group("Variation") {
        r.f("variation", "Amount", &mut m.variation, 0.0, 1.0, 2);
        r.color("v1", "Color 1", &mut m.var_colors[0]);
        r.color("v2", "Color 2", &mut m.var_colors[1]);
        r.color("v3", "Color 3", &mut m.var_colors[2]);
    }
    if r.group("Cutout") {
        r.combo("cutout", "Cutout mesh", mesh_names, &mut m.cutout_mesh);
    }
    (r.changed, tex, base)
}

pub fn pick_image() -> Option<String> {
    rfd::FileDialog::new()
        .add_filter("Images", &["png", "jpg", "jpeg", "tga", "bmp"])
        .pick_file()
        .map(|p| p.to_string_lossy().to_string())
}

pub fn draw_panel(app: &mut App, ui: &mut Ui, panel: Rect) {
    // tab header like the original's "Properties" dock title
    draw_rectangle(panel.x, panel.y, panel.w, panel.h, C_PANEL);
    draw_rectangle(panel.x, panel.y, panel.w, 26.0, C_PANEL2);
    draw_rectangle(panel.x, panel.y, 84.0, 26.0, C_PANEL);
    ui.text("Properties", panel.x + 8.0, panel.y + 6.0, 13.0, C_TEXT);
    let x = panel.x + 12.0;
    let w = panel.w - 24.0;
    let mut y = panel.y + 36.0;

    // header row: what's selected + edit modes
    let (title, sub) = match app.sel {
        Sel::None => ("Nothing selected".to_string(), String::new()),
        Sel::Node(id) => match app.node(id) {
            Some(n) => (n.name.clone(), n.kind.type_label().to_string()),
            None => ("Nothing selected".into(), String::new()),
        },
        Sel::Material(i) => (app.materials.get(i).map(|m| m.name.clone()).unwrap_or_default(), "Material".into()),
        Sel::Mesh(i) => (app.meshes.get(i).map(|m| m.name.clone()).unwrap_or_default(), "Mesh".into()),
        Sel::Window => ("Window properties".into(), "Viewport and lighting".into()),
    };
    ui.text_fit(&title, x, y + 2.0, w * 0.5, 15.0, WHITE);
    ui.record(&format!("hdr:{}", title), Rect::new(x, y, w * 0.5, 20.0));
    if !sub.is_empty() {
        ui.text(&sub, x, y + 21.0, 11.5, C_TEXT_DIM);
    }
    let bx = x + w - 210.0;
    let bw = 70.0;
    let is_node = matches!(app.sel, Sel::Node(_));
    draw_rectangle(bx - 2.0, y - 2.0, bw * 3.0 + 4.0, 26.0, C_BG);
    ui.button_ex("mode.gen", Rect::new(bx, y, bw, 22.0), "Generator", is_node, true);
    ui.button_ex("mode.node", Rect::new(bx + bw, y, bw, 22.0), "Node", false, false);
    ui.button_ex("mode.free", Rect::new(bx + bw * 2.0, y, bw, 22.0), "Freehand", false, false);
    y += 44.0;
    draw_line(panel.x + 8.0, y - 6.0, panel.x + panel.w - 8.0, y - 6.0, 1.0, C_LINE);

    let body = Rect::new(panel.x, y, panel.w, panel.y + panel.h - y);
    if ui.hover_any(body) && ui.inp.wheel != 0.0 && ui.popup.is_none() {
        app.prop_scroll = (app.prop_scroll - ui.inp.wheel * 60.0).max(0.0);
    }
    ui.set_clip(Some(body));
    let start_y = y - app.prop_scroll;

    let mat_names: Vec<String> = app.materials.iter().map(|m| m.name.clone()).collect();
    let mnames = mesh_names(&app.meshes);
    let mut closed = std::mem::take(&mut app.closed_groups);
    let mut rows = Rows { ui, x, y: start_y, w, changed: false, prefix: String::new(), closed: &mut closed, open: true };
    match app.sel {
        Sel::None => {
            rows.note("");
            rows.y -= 20.0;
            let mut act = None;
            for (sec, items) in [
                ("Edit", vec![("Global properties", 1), ("Window properties", 2)]),
                ("Actions", vec![("Randomize", 3), ("Frame tree", 4)]),
                ("File", vec![("New tree", 5)]),
            ] {
                rows.ui.text(sec, x, rows.y + 4.0, 14.0, C_TEXT);
                rows.y += 28.0;
                let bw2 = (w - 8.0) / 2.0;
                for (k, (label, id)) in items.iter().enumerate() {
                    let r = Rect::new(x + 4.0 + (k % 2) as f32 * (bw2 + 6.0) - 4.0, rows.y + (k / 2) as f32 * 32.0, bw2 - 2.0, 27.0);
                    if rows.ui.button(&format!("home.{}", label), r, label) {
                        act = Some(*id);
                    }
                }
                rows.y += ((items.len() + 1) / 2) as f32 * 32.0 + 12.0;
            }
            rows.ui.text("Help", x, rows.y + 4.0, 14.0, C_TEXT);
            rows.y += 28.0;
            for line in [
                "Generation tab: Add a Trunk, Branch or Leaf to the",
                "selected node; click a node to edit it here.",
                "Shift+drag from one node onto another to re-link it.",
                "Viewport: left-drag orbit, middle/shift-drag pan,",
                "right-drag or wheel zoom, F frame the tree.",
                "Keys 0 perspective, 1 front, 3 right, 7 top, 5 ortho.",
            ] {
                rows.note(line);
            }
            match act {
                Some(1) => {
                    let root = app.root_id();
                    app.select(Sel::Node(root));
                }
                Some(2) => app.select(Sel::Window),
                Some(3) => app.randomize(None),
                Some(4) => app.frame_tree(),
                Some(5) => app.new_tree(),
                _ => {}
            }
        }
        Sel::Node(id) => {
            let on_ground = app.node(id).and_then(|n| n.parent).map(|p| app.node(p).map(|q| q.kind == Kind::Tree).unwrap_or(false)).unwrap_or(false);
            let stats = (app.geo_stats.0, app.geo_stats.1, app.geo_stats.2, app.geo_stats.3);
            let count = app.instance_count(id);
            if let Some(idx) = app.nodes.iter().position(|n| n.id == id) {
                rows.prefix = format!("n{}", id);
                let mut n = app.nodes[idx].clone();
                node_props(&mut rows, &mut n, on_ground, &mat_names, &mnames, stats, count);
                if rows.changed {
                    app.nodes[idx] = n;
                    app.dirty = true;
                }
            }
        }
        Sel::Material(i) => {
            if i < app.materials.len() {
                rows.prefix = format!("m{}", i);
                let mut m = app.materials[i].clone();
                let (ch, tex, base) = material_props(&mut rows, &mut m, &mnames);
                if ch || tex || base {
                    if base {
                        m.dirty_base = true;
                    }
                    if tex {
                        m.dirty_tex = true;
                    }
                    app.materials[i] = m;
                    textures::refresh_material(&mut app.materials[i]);
                    app.dirty = true;
                }
            }
        }
        Sel::Mesh(i) => {
            if i < app.meshes.len() {
                rows.prefix = format!("me{}", i);
                let mut m = app.meshes[i].clone();
                let mut act = 0;
                if rows.group("Mesh") {
                    rows.info("Name", &m.name.clone());
                    let mut rm = m.ref_material.min(mat_names.len().saturating_sub(1));
                    rows.combo("ref", "Reference material", &mat_names, &mut rm);
                    m.ref_material = rm;
                    rows.f("scale", "Scale", &mut m.scale, 0.1, 4.0, 2);
                    rows.b("flip", "Flip horizontally", &mut m.flip);
                }
                if rows.group("Cutout") {
                    rows.i("points", "Outline points", &mut m.auto_points, 3, 32);
                    rows.f("thr", "Alpha threshold", &mut m.threshold, 0.01, 0.99, 2);
                    rows.f("margin", "Margin", &mut m.margin, 0.0, 0.1, 3);
                    if rows.button("gen", "Generate from material") {
                        act = 1;
                    }
                    if rows.button("card", "Reset to card") {
                        act = 2;
                    }
                }
                if rows.group("Level of Detail") {
                    rows.info("LOD count", &m.lods.len().to_string());
                    let l = app.mesh_lod.min(m.lods.len() - 1);
                    rows.info("Editing", &format!("LOD{} ({} points)", l, m.lods[l].len()));
                    if rows.button("addlod", "Add LOD (fewer points)") {
                        act = 3;
                    }
                    if rows.button("remlod", "Remove last LOD") {
                        act = 4;
                    }
                }
                match act {
                    1 => {
                        if let Some(img) = app.materials.get(m.ref_material).and_then(|mm| mm.adjusted.clone()) {
                            let l = app.mesh_lod.min(m.lods.len() - 1);
                            m.lods[l] = textures::auto_cutout(&img, m.auto_points as usize, m.threshold, m.margin);
                        }
                        rows.changed = true;
                    }
                    2 => {
                        let l = app.mesh_lod.min(m.lods.len() - 1);
                        m.lods[l] = LeafMesh::card("").lods[0].clone();
                        rows.changed = true;
                    }
                    3 => {
                        let last = m.lods.last().unwrap().clone();
                        let n = (last.len() / 2).max(3);
                        m.lods.push(textures::reduce_outline(last, n));
                        app.mesh_lod = m.lods.len() - 1;
                        rows.changed = true;
                    }
                    4 => {
                        if m.lods.len() > 1 {
                            m.lods.pop();
                            app.mesh_lod = app.mesh_lod.min(m.lods.len() - 1);
                            rows.changed = true;
                        }
                    }
                    _ => {}
                }
                if rows.changed {
                    app.meshes[i] = m;
                    app.dirty = true;
                }
            }
        }
        Sel::Window => {
            rows.prefix = "win".into();
            if rows.group("Camera") {
                let views: Vec<String> = VIEWS.iter().map(|s| s.to_string()).collect();
                let mut v = app.cam.view;
                rows.combo("view", "View", &views, &mut v);
                if v != app.cam.view {
                    app.cam.set_view(v);
                }
                rows.b("ortho", "Orthographic", &mut app.cam.ortho);
                rows.f("fov", "Field of view", &mut app.cam.fov, 10.0, 100.0, 0);
            }
            if rows.group("Display") {
                rows.b("grid", "Show grid", &mut app.show_grid);
                let before = app.highlight;
                rows.b("hl", "Highlight selected generator", &mut app.highlight);
                if before != app.highlight {
                    app.dirty = true;
                }
                rows.b("unlit", "Unlit (texture colours only)", &mut app.light.unlit);
            }
            if rows.group("Lighting") {
                rows.f("az", "Sun direction", &mut app.light.azimuth, -180.0, 180.0, 0);
                rows.f("el", "Sun height", &mut app.light.elevation, 5.0, 90.0, 0);
            }
        }
    }
    let content_h = rows.y - start_y;
    drop(rows);
    app.closed_groups = closed;
    let max_scroll = (content_h - body.h + 20.0).max(0.0);
    app.prop_scroll = app.prop_scroll.min(max_scroll);
    ui.set_clip(None);
    if max_scroll > 0.0 {
        let frac = body.h / (content_h + 20.0);
        let th = (body.h * frac).max(24.0);
        let ty = body.y + (body.h - th) * (app.prop_scroll / max_scroll);
        draw_rectangle(panel.x + panel.w - 5.0, ty, 3.0, th, Color::new(1.0, 1.0, 1.0, 0.2));
    }
}

toolUseResult.content:
//! The Properties panel: rows of labelled controls, grouped like the original's property editor.
use crate::app::{App, Sel};
use crate::model::*;
use crate::render::VIEWS;
use crate::textures;
use crate::ui::*;
use macroquad::prelude::*;

pub struct Rows<'a> {
    pub ui: &'a mut Ui,
    pub x: f32,
    pub y: f32,
    pub w: f32,
    pub changed: bool,
    pub prefix: String,
    pub closed: &'a mut std::collections::HashSet<String>,
    open: bool,
}

const RH: f32 = 24.0;

impl<'a> Rows<'a> {
    fn lw(&self) -> f32 {
        (self.w * 0.46).floor()
    }
    fn key(&self, k: &str) -> String {
        format!("{}.{}", self.prefix, k)
    }
    pub fn group(&mut self, title: &str) -> bool {
        let key = self.key(&format!("grp.{}", title));
        let r = Rect::new(self.x - 6.0, self.y + 4.0, self.w + 12.0, 24.0);
        self.ui.record(&format!("grp:{}", title), r);
        let open = !self.closed.contains(&key);
        let hot = self.ui.hover(r);
        draw_rectangle(r.x, r.y, r.w, r.h, if hot { Color::new(1.0, 1.0, 1.0, 0.08) } else { Color::new(1.0, 1.0, 1.0, 0.04) });
        let ax = r.x + 12.0;
        let ay = r.y + 12.0;
        if open {
            draw_triangle(vec2(ax - 4.0, ay - 2.0), vec2(ax + 4.0, ay - 2.0), vec2(ax, ay + 3.0), C_TEXT_DIM);
        } else {
            draw_triangle(vec2(ax - 2.0, ay - 4.0), vec2(ax - 2.0, ay + 4.0), vec2(ax + 3.0, ay), C_TEXT_DIM);
        }
        self.ui.text(title, r.x + 22.0, r.y + 5.0, 13.5, WHITE);
        if hot && self.ui.inp.l_pressed {
            if open {
                self.closed.insert(key);
            } else {
                self.closed.remove(&key);
            }
        }
        self.y += 32.0;
        self.open = open;
        open
    }
    fn label(&mut self, label: &str) -> Rect {
        let lw = self.lw();
        self.ui.text_fit(label, self.x + 6.0, self.y + 5.0, lw - 10.0, 12.5, C_TEXT_DIM);
        Rect::new(self.x + lw, self.y + 2.0, self.w - lw, RH - 4.0)
    }
    pub fn f(&mut self, k: &str, label: &str, v: &mut f32, min: f32, max: f32, dec: usize) {
        let r = self.label(label);
        let key = self.key(k);
        if self.ui.slider(&key, r, v, min, max, dec) {
            self.changed = true;
        }
        self.y += RH;
    }
    pub fn i(&mut self, k: &str, label: &str, v: &mut i32, min: i32, max: i32) {
        let r = self.label(label);
        let key = self.key(k);
        if self.ui.islider(&key, r, v, min, max) {
            self.changed = true;
        }
        self.y += RH;
    }
    pub fn b(&mut self, k: &str, label: &str, v: &mut bool) {
        let r = self.label(label);
        let key = self.key(k);
        if self.ui.checkbox(&key, r, v) {
            self.changed = true;
        }
        self.y += RH;
    }
    pub fn combo(&mut self, k: &str, label: &str, items: &[String], v: &mut usize) {
        let r = self.label(label);
        let key = self.key(k);
        if self.ui.combo(&key, r, items, v) {
            self.changed = true;
        }
        self.y += RH;
    }
    pub fn color(&mut self, k: &str, label: &str, c: &mut [f32; 3]) {
        let r = self.label(label);
        draw_rectangle(r.x, r.y, 26.0, r.h, Color::new(c[0], c[1], c[2], 1.0));
        draw_rectangle_lines(r.x, r.y, 26.0, r.h, 1.0, C_LINE);
        let sw = (r.w - 32.0) / 3.0;
        let names = ["r", "g", "b"];
        for i in 0..3 {
            let rr = Rect::new(r.x + 30.0 + i as f32 * (sw + 1.0), r.y, sw - 1.0, r.h);
            let key = self.key(&format!("{}.{}", k, names[i]));
            if self.ui.slider(&key, rr, &mut c[i], 0.0, 1.0, 2) {
                self.changed = true;
            }
        }
        self.y += RH;
    }
    pub fn button(&mut self, k: &str, label: &str) -> bool {
        let r = Rect::new(self.x + self.lw(), self.y + 2.0, self.w - self.lw(), RH - 4.0);
        let key = self.key(k);
        let c = self.ui.button(&key, r, label);
        self.y += RH;
        c
    }
    pub fn info(&mut self, label: &str, value: &str) {
        let r = self.label(label);
        self.ui.text_fit(value, r.x + 4.0, r.y + 3.0, r.w - 6.0, 12.5, C_TEXT);
        self.y += RH;
    }
    pub fn note(&mut self, text: &str) {
        self.ui.text_fit(text, self.x + 6.0, self.y + 4.0, self.w - 8.0, 12.0, C_TEXT_FAINT);
        self.y += 20.0;
    }
}

fn mode_rows(r: &mut Rows, p: &mut Params, on_ground: bool) {
    let modes: Vec<String> = GEN_MODES.iter().map(|s| s.to_string()).collect();
    r.combo("gen_mode", "Mode", &modes, &mut p.gen_mode);
    match p.gen_mode {
        MODE_ABSOLUTE => r.i("number", "Number", &mut p.number, 0, 60),
        MODE_INTERVAL => {
            if on_ground {
                r.i("number", "Number", &mut p.number, 0, 60);
            } else {
                r.f("interval", "Interval (spacing)", &mut p.interval, 0.1, 20.0, 2);
            }
        }
        MODE_PHYLLOTAXY => {
            if on_ground {
                r.i("number", "Number", &mut p.number, 0, 60);
            } else {
                r.f("interval", "Internode length", &mut p.interval, 0.1, 20.0, 2);
                r.i("per_node", "Children per node", &mut p.per_node, 1, 12);
            }
        }
        _ => r.f("frequency", "Frequency", &mut p.frequency, 0.0, 120.0, 1),
    }
    if !on_ground {
        r.f("first", "First", &mut p.first, 0.0, 1.0, 3);
        r.f("last", "Last", &mut p.last, 0.0, 1.0, 3);
        r.f("jumble", "Jumble", &mut p.jumble, 0.0, 1.0, 2);
    }
    r.f("spiral", "Spiral (roll step)", &mut p.spiral, 0.0, 360.0, 1);
    r.f("roll_var", "Roll variance", &mut p.roll_var, 0.0, 180.0, 1);
    r.f("size_scalar", "Size scalar", &mut p.size_scalar, 0.1, 3.0, 2);
}

fn seed_rows(r: &mut Rows, p: &mut Params) {
    r.i("seed", "Generation seed", &mut p.seed, 0, 9999);
    if r.button("rand", "Randomize") {
        p.seed = (macroquad::rand::gen_range(0, 9999)) as i32;
        r.changed = true;
    }
}

pub fn node_props(r: &mut Rows, n: &mut Node, on_ground: bool, mat_names: &[String], mesh_names: &[String], stats: (usize, usize, usize, usize), count: usize) {
    let kind = n.kind;
    let p = &mut n.p;
    match kind {
        Kind::Tree => {
            if r.group("Shape") {
                r.f("tree_radius", "Radius (trunk spread)", &mut p.tree_radius, 0.0, 60.0, 1);
            }
            if r.group("Level of Detail") {
                r.i("lod_preview", "Preview leaf LOD", &mut p.lod_preview, 0, 3);
            }
            if r.group("Statistics") {
                r.info("Triangles", &stats.0.to_string());
                r.info("Vertices", &stats.1.to_string());
                r.info("Branches", &stats.2.to_string());
                r.info("Leaves", &stats.3.to_string());
            }
        }
        Kind::Trunk | Kind::Branch => {
            if r.group("Generation") {
                mode_rows(r, p, on_ground);
                seed_rows(r, p);
                r.info("Instances", &count.to_string());
            }
            if r.group("Spine") {
                r.f("len_abs", "Length: absolute", &mut p.len_abs, 0.0, 100.0, 2);
                r.f("len_pct", "Length: + % of parent", &mut p.len_pct, 0.0, 1.5, 3);
                r.f("len_var", "Length variance", &mut p.len_var, 0.0, 1.0, 2);
                r.f("len_profile", "Shorter toward parent end", &mut p.len_profile, 0.0, 1.0, 2);
                r.f("start_angle", "Start angle", &mut p.start_angle, 0.0, 1.0, 3);
                r.f("angle_var", "Start angle variance", &mut p.angle_var, 0.0, 0.5, 3);
                r.f("angle_profile", "Angle change along parent", &mut p.angle_profile, -1.0, 1.0, 2);
                r.f("gravity", "Gravity", &mut p.gravity, -1.0, 1.0, 2);
                r.f("noise_amt", "Noise amount", &mut p.noise_amt, 0.0, 3.0, 2);
                r.f("noise_turb", "Noise turbulence", &mut p.noise_turb, 0.0, 1.0, 2);
                r.f("jink", "Jink", &mut p.jink, 0.0, 1.0, 2);
            }
            if r.group("Skin") {
                r.f("radius_abs", "Radius: absolute", &mut p.radius_abs, 0.0, 10.0, 3);
                r.f("radius_pct", "Radius: + % of parent", &mut p.radius_pct, 0.0, 1.5, 3);
                r.f("radius_var", "Radius variance", &mut p.radius_var, 0.0, 1.0, 2);
                r.f("taper", "Tip radius (taper)", &mut p.taper, 0.0, 1.0, 2);
                r.f("flare", "Base flare", &mut p.flare, 0.0, 3.0, 2);
                r.b("clamp", "Clamp to parent", &mut p.clamp_parent);
            }
            if r.group("Segments") {
                r.i("seg_len", "Length segments", &mut p.seg_len, 2, 64);
                r.i("seg_radial", "Radial segments", &mut p.seg_radial, 3, 32);
            }
            if r.group("Materials") {
                let mut m = p.material.min(mat_names.len().saturating_sub(1));
                r.combo("material", "Branch material", mat_names, &mut m);
                p.material = m;
                r.f("u_tile", "U tiling", &mut p.u_tile, 0.1, 8.0, 2);
                r.f("v_tile", "V tiling", &mut p.v_tile, 0.1, 8.0, 2);
            }
        }
        Kind::Leaf => {
            if r.group("Generation") {
                mode_rows(r, p, on_ground);
                seed_rows(r, p);
                r.info("Instances", &count.to_string());
            }
            if r.group("Leaves") {
                r.f("leaf_size", "Size", &mut p.leaf_size, 0.0, 10.0, 2);
                r.f("leaf_size_pct", "Size: + % of parent", &mut p.leaf_size_pct, 0.0, 0.5, 3);
                r.f("leaf_size_var", "Size variance", &mut p.leaf_size_var, 0.0, 1.0, 2);
                let mut mi = p.leaf_mesh.min(mesh_names.len().saturating_sub(1));
                r.combo("leaf_mesh", "Mesh", mesh_names, &mut mi);
                p.leaf_mesh = mi;
                let mut ma = p.leaf_material.min(mat_names.len().saturating_sub(1));
                r.combo("leaf_material", "Material", mat_names, &mut ma);
                p.leaf_material = ma;
            }
            if r.group("Local Orientation") {
                r.f("start_angle", "Angle from parent", &mut p.start_angle, 0.0, 1.0, 3);
                r.f("angle_var", "Angle variance", &mut p.angle_var, 0.0, 0.5, 3);
                r.f("face_sky", "Face sky", &mut p.face_sky, 0.0, 1.0, 2);
                r.f("droop", "Droop", &mut p.droop, -1.0, 1.0, 2);
                r.f("leaf_twist", "Twist", &mut p.leaf_twist, -1.0, 1.0, 2);
            }
            if r.group("Deformation") {
                r.f("fold", "Fold", &mut p.fold, -1.0, 1.0, 2);
                r.f("curl", "Curl", &mut p.curl, -1.0, 1.0, 2);
                r.f("scale_x", "Scale X (width)", &mut p.scale_x, 0.1, 3.0, 2);
                r.f("scale_y", "Scale Y (length)", &mut p.scale_y, 0.1, 3.0, 2);
            }
        }
    }
}

/// Material properties. Returns (tree needs rebuild, texture needs rebuild, base needs reload).
pub fn material_props(r: &mut Rows, m: &mut Material, mesh_names: &[String]) -> (bool, bool, bool) {
    let mut tex = false;
    let mut base = false;
    if r.group("General") {
        r.info("Name", &m.name.clone());
        r.b("two_sided", "Two sided", &mut m.two_sided);
    }
    if r.group("Color") {
        r.color("color", "Tint", &mut m.color);
        let src: Vec<String> = MAP_SOURCES.iter().map(|s| s.to_string()).collect();
        let before = r.changed;
        r.changed = false;
        r.combo("source", "Texture", &src, &mut m.source);
        if r.changed {
            base = true;
            if m.source == 4 && m.file.is_empty() {
                if let Some(f) = pick_image() {
                    m.file = f;
                }
            }
        }
        r.changed |= before;
        if m.source == 4 {
            let fname = std::path::Path::new(&m.file).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| "(none)".into());
            r.info("File", &fname);
            if r.button("load", "Load image...") {
                if let Some(f) = pick_image() {
                    m.file = f;
                    base = true;
                    r.changed = true;
                }
            }
        }
        let before = r.changed;
        r.changed = false;
        r.f("brightness", "Brightness", &mut m.brightness, -1.0, 1.0, 2);
        r.f("contrast", "Contrast", &mut m.contrast, -1.0, 1.0, 2);
        r.f("saturation", "Saturation", &mut m.saturation, -1.0, 1.0, 2);
        r.f("hue", "Hue shift", &mut m.hue, -0.5, 0.5, 2);
        if r.changed {
            tex = true;
        }
        r.changed |= before;
    }
    if r.group("Opacity") {
        let before = r.changed;
        r.changed = false;
        r.b("alpha", "Use texture alpha", &mut m.opacity_from_alpha);
        if r.changed {
            tex = true;
        }
        r.changed |= before;
        r.f("cutoff", "Alpha cutoff", &mut m.cutoff, 0.0, 1.0, 2);
    }
    if r.group("Normal") {
        r.f("bump", "Bump strength", &mut m.normal_strength, 0.0, 3.0, 2);
    }
    if r.group("Gloss / Specular") {
        r.f("gloss", "Gloss", &mut m.gloss, 0.0, 1.0, 2);
        r.f("specular", "Specular", &mut m.specular, 0.0, 1.0, 2);
        r.f("metallic", "Metallic", &mut m.metallic, 0.0, 1.0, 2);
    }
    if r.group("Subsurface") {
        r.color("sss_color", "Color", &mut m.sss_color);
        r.f("sss_amount", "Amount", &mut m.sss_amount, 0.0, 1.0, 2);
    }
    if r.group("AO") {
        r.f("ao", "Amount", &mut m.ao, 0.0, 1.0, 2);
    }
    if r.group("Variation") {
        r.f("variation", "Amount", &mut m.variation, 0.0, 1.0, 2);
        r.color("v1", "Color 1", &mut m.var_colors[0]);
        r.color("v2", "Color 2", &mut m.var_colors[1]);
        r.color("v3", "Color 3", &mut m.var_colors[2]);
    }
    if r.group("Cutout") {
        r.combo("cutout", "Cutout mesh", mesh_names, &mut m.cutout_mesh);
    }
    (r.changed, tex, base)
}

pub fn pick_image() -> Option<String> {
    rfd::FileDialog::new()
        .add_filter("Images", &["png", "jpg", "jpeg", "tga", "bmp"])
        .pick_file()
        .map(|p| p.to_string_lossy().to_string())
}

pub fn draw_panel(app: &mut App, ui: &mut Ui, panel: Rect) {
    // tab header like the original's "Properties" dock title
    draw_rectangle(panel.x, panel.y, panel.w, panel.h, C_PANEL);
    draw_rectangle(panel.x, panel.y, panel.w, 26.0, C_PANEL2);
    draw_rectangle(panel.x, panel.y, 84.0, 26.0, C_PANEL);
    ui.text("Properties", panel.x + 8.0, panel.y + 6.0, 13.0, C_TEXT);
    let x = panel.x + 12.0;
    let w = panel.w - 24.0;
    let mut y = panel.y + 36.0;

    // header row: what's selected + edit modes
    let (title, sub) = match app.sel {
        Sel::None => ("Nothing selected".to_string(), String::new()),
        Sel::Node(id) => match app.node(id) {
            Some(n) => (n.name.clone(), n.kind.type_label().to_string()),
            None => ("Nothing selected".into(), String::new()),
        },
        Sel::Material(i) => (app.materials.get(i).map(|m| m.name.clone()).unwrap_or_default(), "Material".into()),
        Sel::Mesh(i) => (app.meshes.get(i).map(|m| m.name.clone()).unwrap_or_default(), "Mesh".into()),
        Sel::Window => ("Window properties".into(), "Viewport and lighting".into()),
    };
    ui.text_fit(&title, x, y + 2.0, w * 0.5, 15.0, WHITE);
    ui.record(&format!("hdr:{}", title), Rect::new(x, y, w * 0.5, 20.0));
    if !sub.is_empty() {
        ui.text(&sub, x, y + 21.0, 11.5, C_TEXT_DIM);
    }
    let bx = x + w - 210.0;
    let bw = 70.0;
    let is_node = matches!(app.sel, Sel::Node(_));
    draw_rectangle(bx - 2.0, y - 2.0, bw * 3.0 + 4.0, 26.0, C_BG);
    ui.button_ex("mode.gen", Rect::new(bx, y, bw, 22.0), "Generator", is_node, true);
    ui.button_ex("mode.node", Rect::new(bx + bw, y, bw, 22.0), "Node", false, false);
    ui.button_ex("mode.free", Rect::new(bx + bw * 2.0, y, bw, 22.0), "Freehand", false, false);
    y += 44.0;
    draw_line(panel.x + 8.0, y - 6.0, panel.x + panel.w - 8.0, y - 6.0, 1.0, C_LINE);

    let body = Rect::new(panel.x, y, panel.w, panel.y + panel.h - y);
    if ui.hover_any(body) && ui.inp.wheel != 0.0 && ui.popup.is_none() {
        app.prop_scroll = (app.prop_scroll - ui.inp.wheel * 60.0).max(0.0);
    }
    ui.set_clip(Some(body));
    let start_y = y - app.prop_scroll;

    let mat_names: Vec<String> = app.materials.iter().map(|m| m.name.clone()).collect();
    let mnames = mesh_names(&app.meshes);
    let mut closed = std::mem::take(&mut app.closed_groups);
    let mut rows = Rows { ui, x, y: start_y, w, changed: false, prefix: String::new(), closed: &mut closed, open: true };
    match app.sel {
        Sel::None => {
            rows.note("");
            rows.y -= 20.0;
            let mut act = None;
            for (sec, items) in [
                ("Edit", vec![("Global properties", 1), ("Window properties", 2)]),
                ("Actions", vec![("Randomize", 3), ("Frame tree", 4)]),
                ("File", vec![("New tree", 5)]),
            ] {
                rows.ui.text(sec, x, rows.y + 4.0, 14.0, C_TEXT);
                rows.y += 28.0;
                let bw2 = (w - 8.0) / 2.0;
                for (k, (label, id)) in items.iter().enumerate() {
                    let r = Rect::new(x + 4.0 + (k % 2) as f32 * (bw2 + 6.0) - 4.0, rows.y + (k / 2) as f32 * 32.0, bw2 - 2.0, 27.0);
                    if rows.ui.button(&format!("home.{}", label), r, label) {
                        act = Some(*id);
                    }
                }
                rows.y += ((items.len() + 1) / 2) as f32 * 32.0 + 12.0;
            }
            rows.ui.text("Help", x, rows.y + 4.0, 14.0, C_TEXT);
            rows.y += 28.0;
            for line in [
                "Generation tab: Add a Trunk, Branch or Leaf to the",
                "selected node; click a node to edit it here.",
                "Shift+drag from one node onto another to re-link it.",
                "Viewport: left-drag orbit, middle/shift-drag pan,",
                "right-drag or wheel zoom, F frame the tree.",
                "Keys 0 perspective, 1 front, 3 right, 7 top, 5 ortho.",
            ] {
                rows.note(line);
            }
            match act {
                Some(1) => {
                    let root = app.root_id();
                    app.select(Sel::Node(root));
                }
                Some(2) => app.select(Sel::Window),
                Some(3) => app.randomize(None),
                Some(4) => app.frame_tree(),
                Some(5) => app.new_tree(),
                _ => {}
            }
        }
        Sel::Node(id) => {
            let on_ground = app.node(id).and_then(|n| n.parent).map(|p| app.node(p).map(|q| q.kind == Kind::Tree).unwrap_or(false)).unwrap_or(false);
            let stats = (app.geo_stats.0, app.geo_stats.1, app.geo_stats.2, app.geo_stats.3);
            let count = app.instance_count(id);
            if let Some(idx) = app.nodes.iter().position(|n| n.id == id) {
                rows.prefix = format!("n{}", id);
                let mut n = app.nodes[idx].clone();
                node_props(&mut rows, &mut n, on_ground, &mat_names, &mnames, stats, count);
                if rows.changed {
                    app.nodes[idx] = n;
                    app.dirty = true;
                }
            }
        }
        Sel::Material(i) => {
            if i < app.materials.len() {
                rows.prefix = format!("m{}", i);
                let mut m = app.materials[i].clone();
                let (ch, tex, base) = material_props(&mut rows, &mut m, &mnames);
                if ch || tex || base {
                    if base {
                        m.dirty_base = true;
                    }
                    if tex {
                        m.dirty_tex = true;
                    }
                    app.materials[i] = m;
                    textures::refresh_material(&mut app.materials[i]);
                    app.dirty = true;
                }
            }
        }
        Sel::Mesh(i) => {
            if i < app.meshes.len() {
                rows.prefix = format!("me{}", i);
                let mut m = app.meshes[i].clone();
                let mut act = 0;
                if rows.group("Mesh") {
                    rows.info("Name", &m.name.clone());
                    let mut rm = m.ref_material.min(mat_names.len().saturating_sub(1));
                    rows.combo("ref", "Reference material", &mat_names, &mut rm);
                    m.ref_material = rm;
                    rows.f("scale", "Scale", &mut m.scale, 0.1, 4.0, 2);
                    rows.b("flip", "Flip horizontally", &mut m.flip);
                }
                if rows.group("Cutout") {
                    rows.i("points", "Outline points", &mut m.auto_points, 3, 32);
                    rows.f("thr", "Alpha threshold", &mut m.threshold, 0.01, 0.99, 2);
                    rows.f("margin", "Margin", &mut m.margin, 0.0, 0.1, 3);
                    if rows.button("gen", "Generate from material") {
                        act = 1;
                    }
                    if rows.button("card", "Reset to card") {
                        act = 2;
                    }
                }
                if rows.group("Level of Detail") {
                    rows.info("LOD count", &m.lods.len().to_string());
                    let l = app.mesh_lod.min(m.lods.len() - 1);
                    rows.info("Editing", &format!("LOD{} ({} points)", l, m.lods[l].len()));
                    if rows.button("addlod", "Add LOD (fewer points)") {
                        act = 3;
                    }
                    if rows.button("remlod", "Remove last LOD") {
                        act = 4;
                    }
                }
                match act {
                    1 => {
                        if let Some(img) = app.materials.get(m.ref_material).and_then(|mm| mm.adjusted.clone()) {
                            let l = app.mesh_lod.min(m.lods.len() - 1);
                            m.lods[l] = textures::auto_cutout(&img, m.auto_points as usize, m.threshold, m.margin);
                        }
                        rows.changed = true;
                    }
                    2 => {
                        let l = app.mesh_lod.min(m.lods.len() - 1);
                        m.lods[l] = LeafMesh::card("").lods[0].clone();
                        rows.changed = true;
                    }
                    3 => {
                        let last = m.lods.last().unwrap().clone();
                        let n = (last.len() / 2).max(3);
                        m.lods.push(textures::reduce_outline(last, n));
                        app.mesh_lod = m.lods.len() - 1;
                        rows.changed = true;
                    }
                    4 => {
                        if m.lods.len() > 1 {
                            m.lods.pop();
                            app.mesh_lod = app.mesh_lod.min(m.lods.len() - 1);
                            rows.changed = true;
                        }
                    }
                    _ => {}
                }
                if rows.changed {
                    app.meshes[i] = m;
                    app.dirty = true;
                }
            }
        }
        Sel::Window => {
            rows.prefix = "win".into();
            if rows.group("Camera") {
                let views: Vec<String> = VIEWS.iter().map(|s| s.to_string()).collect();
                let mut v = app.cam.view;
                rows.combo("view", "View", &views, &mut v);
                if v != app.cam.view {
                    app.cam.set_view(v);
                }
                rows.b("ortho", "Orthographic", &mut app.cam.ortho);
                rows.f("fov", "Field of view", &mut app.cam.fov, 10.0, 100.0, 0);
            }
            if rows.group("Display") {
                rows.b("grid", "Show grid", &mut app.show_grid);
                let before = app.highlight;
                rows.b("hl", "Highlight selected generator", &mut app.highlight);
                if before != app.highlight {
                    app.dirty = true;
                }
                rows.b("unlit", "Unlit (texture colours only)", &mut app.light.unlit);
            }
            if rows.group("Lighting") {
                rows.f("az", "Sun direction", &mut app.light.azimuth, -180.0, 180.0, 0);
                rows.f("el", "Sun height", &mut app.light.elevation, 5.0, 90.0, 0);
            }
        }
    }
    let content_h = rows.y - start_y;
    drop(rows);
    app.closed_groups = closed;
    let max_scroll = (content_h - body.h + 20.0).max(0.0);
    app.prop_scroll = app.prop_scroll.min(max_scroll);
    ui.set_clip(None);
    if max_scroll > 0.0 {
        let frac = body.h / (content_h + 20.0);
        let th = (body.h * frac).max(24.0);
        let ty = body.y + (body.h - th) * (app.prop_scroll / max_scroll);
        draw_rectangle(panel.x + panel.w - 5.0, ty, 3.0, th, Color::new(1.0, 1.0, 1.0, 0.2));
    }
}

input.content:
//! The Properties panel: rows of labelled controls, grouped like the original's property editor.
use crate::app::{App, Sel};
use crate::model::*;
use crate::render::VIEWS;
use crate::textures;
use crate::ui::*;
use macroquad::prelude::*;

pub struct Rows<'a> {
    pub ui: &'a mut Ui,
    pub x: f32,
    pub y: f32,
    pub w: f32,
    pub changed: bool,
    pub prefix: String,
    pub closed: &'a mut std::collections::HashSet<String>,
    open: bool,
}

const RH: f32 = 24.0;

impl<'a> Rows<'a> {
    fn lw(&self) -> f32 {
        (self.w * 0.46).floor()
    }
    fn key(&self, k: &str) -> String {
        format!("{}.{}", self.prefix, k)
    }
    pub fn group(&mut self, title: &str) -> bool {
        let key = self.key(&format!("grp.{}", title));
        let r = Rect::new(self.x - 6.0, self.y + 4.0, self.w + 12.0, 24.0);
        self.ui.record(&format!("grp:{}", title), r);
        let open = !self.closed.contains(&key);
        let hot = self.ui.hover(r);
        draw_rectangle(r.x, r.y, r.w, r.h, if hot { Color::new(1.0, 1.0, 1.0, 0.08) } else { Color::new(1.0, 1.0, 1.0, 0.04) });
        let ax = r.x + 12.0;
        let ay = r.y + 12.0;
        if open {
            draw_triangle(vec2(ax - 4.0, ay - 2.0), vec2(ax + 4.0, ay - 2.0), vec2(ax, ay + 3.0), C_TEXT_DIM);
        } else {
            draw_triangle(vec2(ax - 2.0, ay - 4.0), vec2(ax - 2.0, ay + 4.0), vec2(ax + 3.0, ay), C_TEXT_DIM);
        }
        self.ui.text(title, r.x + 22.0, r.y + 5.0, 13.5, WHITE);
        if hot && self.ui.inp.l_pressed {
            if open {
                self.closed.insert(key);
            } else {
                self.closed.remove(&key);
            }
        }
        self.y += 32.0;
        self.open = open;
        open
    }
    fn label(&mut self, label: &str) -> Rect {
        let lw = self.lw();
        self.ui.text_fit(label, self.x + 6.0, self.y + 5.0, lw - 10.0, 12.5, C_TEXT_DIM);
        Rect::new(self.x + lw, self.y + 2.0, self.w - lw, RH - 4.0)
    }
    pub fn f(&mut self, k: &str, label: &str, v: &mut f32, min: f32, max: f32, dec: usize) {
        let r = self.label(label);
        let key = self.key(k);
        if self.ui.slider(&key, r, v, min, max, dec) {
            self.changed = true;
        }
        self.y += RH;
    }
    pub fn i(&mut self, k: &str, label: &str, v: &mut i32, min: i32, max: i32) {
        let r = self.label(label);
        let key = self.key(k);
        if self.ui.islider(&key, r, v, min, max) {
            self.changed = true;
        }
        self.y += RH;
    }
    pub fn b(&mut self, k: &str, label: &str, v: &mut bool) {
        let r = self.label(label);
        let key = self.key(k);
        if self.ui.checkbox(&key, r, v) {
            self.changed = true;
        }
        self.y += RH;
    }
    pub fn combo(&mut self, k: &str, label: &str, items: &[String], v: &mut usize) {
        let r = self.label(label);
        let key = self.key(k);
        if self.ui.combo(&key, r, items, v) {
            self.changed = true;
        }
        self.y += RH;
    }
    pub fn color(&mut self, k: &str, label: &str, c: &mut [f32; 3]) {
        let r = self.label(label);
        draw_rectangle(r.x, r.y, 26.0, r.h, Color::new(c[0], c[1], c[2], 1.0));
        draw_rectangle_lines(r.x, r.y, 26.0, r.h, 1.0, C_LINE);
        let sw = (r.w - 32.0) / 3.0;
        let names = ["r", "g", "b"];
        for i in 0..3 {
            let rr = Rect::new(r.x + 30.0 + i as f32 * (sw + 1.0), r.y, sw - 1.0, r.h);
            let key = self.key(&format!("{}.{}", k, names[i]));
            if self.ui.slider(&key, rr, &mut c[i], 0.0, 1.0, 2) {
                self.changed = true;
            }
        }
        self.y += RH;
    }
    pub fn button(&mut self, k: &str, label: &str) -> bool {
        let r = Rect::new(self.x + self.lw(), self.y + 2.0, self.w - self.lw(), RH - 4.0);
        let key = self.key(k);
        let c = self.ui.button(&key, r, label);
        self.y += RH;
        c
    }
    pub fn info(&mut self, label: &str, value: &str) {
        let r = self.label(label);
        self.ui.text_fit(value, r.x + 4.0, r.y + 3.0, r.w - 6.0, 12.5, C_TEXT);
        self.y += RH;
    }
    pub fn note(&mut self, text: &str) {
        self.ui.text_fit(text, self.x + 6.0, self.y + 4.0, self.w - 8.0, 12.0, C_TEXT_FAINT);
        self.y += 20.0;
    }
}

fn mode_rows(r: &mut Rows, p: &mut Params, on_ground: bool) {
    let modes: Vec<String> = GEN_MODES.iter().map(|s| s.to_string()).collect();
    r.combo("gen_mode", "Mode", &modes, &mut p.gen_mode);
    match p.gen_mode {
        MODE_ABSOLUTE => r.i("number", "Number", &mut p.number, 0, 60),
        MODE_INTERVAL => {
            if on_ground {
                r.i("number", "Number", &mut p.number, 0, 60);
            } else {
                r.f("interval", "Interval (spacing)", &mut p.interval, 0.1, 20.0, 2);
            }
        }
        MODE_PHYLLOTAXY => {
            if on_ground {
                r.i("number", "Number", &mut p.number, 0, 60);
            } else {
                r.f("interval", "Internode length", &mut p.interval, 0.1, 20.0, 2);
                r.i("per_node", "Children per node", &mut p.per_node, 1, 12);
            }
        }
        _ => r.f("frequency", "Frequency", &mut p.frequency, 0.0, 120.0, 1),
    }
    if !on_ground {
        r.f("first", "First", &mut p.first, 0.0, 1.0, 3);
        r.f("last", "Last", &mut p.last, 0.0, 1.0, 3);
        r.f("jumble", "Jumble", &mut p.jumble, 0.0, 1.0, 2);
    }
    r.f("spiral", "Spiral (roll step)", &mut p.spiral, 0.0, 360.0, 1);
    r.f("roll_var", "Roll variance", &mut p.roll_var, 0.0, 180.0, 1);
    r.f("size_scalar", "Size scalar", &mut p.size_scalar, 0.1, 3.0, 2);
}

fn seed_rows(r: &mut Rows, p: &mut Params) {
    r.i("seed", "Generation seed", &mut p.seed, 0, 9999);
    if r.button("rand", "Randomize") {
        p.seed = (macroquad::rand::gen_range(0, 9999)) as i32;
        r.changed = true;
    }
}

pub fn node_props(r: &mut Rows, n: &mut Node, on_ground: bool, mat_names: &[String], mesh_names: &[String], stats: (usize, usize, usize, usize), count: usize) {
    let kind = n.kind;
    let p = &mut n.p;
    match kind {
        Kind::Tree => {
            if r.group("Shape") {
                r.f("tree_radius", "Radius (trunk spread)", &mut p.tree_radius, 0.0, 60.0, 1);
            }
            if r.group("Level of Detail") {
                r.i("lod_preview", "Preview leaf LOD", &mut p.lod_preview, 0, 3);
            }
            if r.group("Statistics") {
                r.info("Triangles", &stats.0.to_string());
                r.info("Vertices", &stats.1.to_string());
                r.info("Branches", &stats.2.to_string());
                r.info("Leaves", &stats.3.to_string());
            }
        }
        Kind::Trunk | Kind::Branch => {
            if r.group("Generation") {
                mode_rows(r, p, on_ground);
                seed_rows(r, p);
                r.info("Instances", &count.to_string());
            }
            if r.group("Spine") {
                r.f("len_abs", "Length: absolute", &mut p.len_abs, 0.0, 100.0, 2);
                r.f("len_pct", "Length: + % of parent", &mut p.len_pct, 0.0, 1.5, 3);
                r.f("len_var", "Length variance", &mut p.len_var, 0.0, 1.0, 2);
                r.f("len_profile", "Shorter toward parent end", &mut p.len_profile, 0.0, 1.0, 2);
                r.f("start_angle", "Start angle", &mut p.start_angle, 0.0, 1.0, 3);
                r.f("angle_var", "Start angle variance", &mut p.angle_var, 0.0, 0.5, 3);
                r.f("angle_profile", "Angle change along parent", &mut p.angle_profile, -1.0, 1.0, 2);
                r.f("gravity", "Gravity", &mut p.gravity, -1.0, 1.0, 2);
                r.f("noise_amt", "Noise amount", &mut p.noise_amt, 0.0, 3.0, 2);
                r.f("noise_turb", "Noise turbulence", &mut p.noise_turb, 0.0, 1.0, 2);
                r.f("jink", "Jink", &mut p.jink, 0.0, 1.0, 2);
            }
            if r.group("Skin") {
                r.f("radius_abs", "Radius: absolute", &mut p.radius_abs, 0.0, 10.0, 3);
                r.f("radius_pct", "Radius: + % of parent", &mut p.radius_pct, 0.0, 1.5, 3);
                r.f("radius_var", "Radius variance", &mut p.radius_var, 0.0, 1.0, 2);
                r.f("taper", "Tip radius (taper)", &mut p.taper, 0.0, 1.0, 2);
                r.f("flare", "Base flare", &mut p.flare, 0.0, 3.0, 2);
                r.b("clamp", "Clamp to parent", &mut p.clamp_parent);
            }
            if r.group("Segments") {
                r.i("seg_len", "Length segments", &mut p.seg_len, 2, 64);
                r.i("seg_radial", "Radial segments", &mut p.seg_radial, 3, 32);
            }
            if r.group("Materials") {
                let mut m = p.material.min(mat_names.len().saturating_sub(1));
                r.combo("material", "Branch material", mat_names, &mut m);
                p.material = m;
                r.f("u_tile", "U tiling", &mut p.u_tile, 0.1, 8.0, 2);
                r.f("v_tile", "V tiling", &mut p.v_tile, 0.1, 8.0, 2);
            }
        }
        Kind::Leaf => {
            if r.group("Generation") {
                mode_rows(r, p, on_ground);
                seed_rows(r, p);
                r.info("Instances", &count.to_string());
            }
            if r.group("Leaves") {
                r.f("leaf_size", "Size", &mut p.leaf_size, 0.0, 10.0, 2);
                r.f("leaf_size_pct", "Size: + % of parent", &mut p.leaf_size_pct, 0.0, 0.5, 3);
                r.f("leaf_size_var", "Size variance", &mut p.leaf_size_var, 0.0, 1.0, 2);
                let mut mi = p.leaf_mesh.min(mesh_names.len().saturating_sub(1));
                r.combo("leaf_mesh", "Mesh", mesh_names, &mut mi);
                p.leaf_mesh = mi;
                let mut ma = p.leaf_material.min(mat_names.len().saturating_sub(1));
                r.combo("leaf_material", "Material", mat_names, &mut ma);
                p.leaf_material = ma;
            }
            if r.group("Local Orientation") {
                r.f("start_angle", "Angle from parent", &mut p.start_angle, 0.0, 1.0, 3);
                r.f("angle_var", "Angle variance", &mut p.angle_var, 0.0, 0.5, 3);
                r.f("face_sky", "Face sky", &mut p.face_sky, 0.0, 1.0, 2);
                r.f("droop", "Droop", &mut p.droop, -1.0, 1.0, 2);
                r.f("leaf_twist", "Twist", &mut p.leaf_twist, -1.0, 1.0, 2);
            }
            if r.group("Deformation") {
                r.f("fold", "Fold", &mut p.fold, -1.0, 1.0, 2);
                r.f("curl", "Curl", &mut p.curl, -1.0, 1.0, 2);
                r.f("scale_x", "Scale X (width)", &mut p.scale_x, 0.1, 3.0, 2);
                r.f("scale_y", "Scale Y (length)", &mut p.scale_y, 0.1, 3.0, 2);
            }
        }
    }
}

/// Material properties. Returns (tree needs rebuild, texture needs rebuild, base needs reload).
pub fn material_props(r: &mut Rows, m: &mut Material, mesh_names: &[String]) -> (bool, bool, bool) {
    let mut tex = false;
    let mut base = false;
    if r.group("General") {
        r.info("Name", &m.name.clone());
        r.b("two_sided", "Two sided", &mut m.two_sided);
    }
    if r.group("Color") {
        r.color("color", "Tint", &mut m.color);
        let src: Vec<String> = MAP_SOURCES.iter().map(|s| s.to_string()).collect();
        let before = r.changed;
        r.changed = false;
        r.combo("source", "Texture", &src, &mut m.source);
        if r.changed {
            base = true;
            if m.source == 4 && m.file.is_empty() {
                if let Some(f) = pick_image() {
                    m.file = f;
                }
            }
        }
        r.changed |= before;
        if m.source == 4 {
            let fname = std::path::Path::new(&m.file).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| "(none)".into());
            r.info("File", &fname);
            if r.button("load", "Load image...") {
                if let Some(f) = pick_image() {
                    m.file = f;
                    base = true;
                    r.changed = true;
                }
            }
        }
        let before = r.changed;
        r.changed = false;
        r.f("brightness", "Brightness", &mut m.brightness, -1.0, 1.0, 2);
        r.f("contrast", "Contrast", &mut m.contrast, -1.0, 1.0, 2);
        r.f("saturation", "Saturation", &mut m.saturation, -1.0, 1.0, 2);
        r.f("hue", "Hue shift", &mut m.hue, -0.5, 0.5, 2);
        if r.changed {
            tex = true;
        }
        r.changed |= before;
    }
    if r.group("Opacity") {
        let before = r.changed;
        r.changed = false;
        r.b("alpha", "Use texture alpha", &mut m.opacity_from_alpha);
        if r.changed {
            tex = true;
        }
        r.changed |= before;
        r.f("cutoff", "Alpha cutoff", &mut m.cutoff, 0.0, 1.0, 2);
    }
    if r.group("Normal") {
        r.f("bump", "Bump strength", &mut m.normal_strength, 0.0, 3.0, 2);
    }
    if r.group("Gloss / Specular") {
        r.f("gloss", "Gloss", &mut m.gloss, 0.0, 1.0, 2);
        r.f("specular", "Specular", &mut m.specular, 0.0, 1.0, 2);
        r.f("metallic", "Metallic", &mut m.metallic, 0.0, 1.0, 2);
    }
    if r.group("Subsurface") {
        r.color("sss_color", "Color", &mut m.sss_color);
        r.f("sss_amount", "Amount", &mut m.sss_amount, 0.0, 1.0, 2);
    }
    if r.group("AO") {
        r.f("ao", "Amount", &mut m.ao, 0.0, 1.0, 2);
    }
    if r.group("Variation") {
        r.f("variation", "Amount", &mut m.variation, 0.0, 1.0, 2);
        r.color("v1", "Color 1", &mut m.var_colors[0]);
        r.color("v2", "Color 2", &mut m.var_colors[1]);
        r.color("v3", "Color 3", &mut m.var_colors[2]);
    }
    if r.group("Cutout") {
        r.combo("cutout", "Cutout mesh", mesh_names, &mut m.cutout_mesh);
    }
    (r.changed, tex, base)
}

pub fn pick_image() -> Option<String> {
    rfd::FileDialog::new()
        .add_filter("Images", &["png", "jpg", "jpeg", "tga", "bmp"])
        .pick_file()
        .map(|p| p.to_string_lossy().to_string())
}

pub fn draw_panel(app: &mut App, ui: &mut Ui, panel: Rect) {
    // tab header like the original's "Properties" dock title
    draw_rectangle(panel.x, panel.y, panel.w, panel.h, C_PANEL);
    draw_rectangle(panel.x, panel.y, panel.w, 26.0, C_PANEL2);
    draw_rectangle(panel.x, panel.y, 84.0, 26.0, C_PANEL);
    ui.text("Properties", panel.x + 8.0, panel.y + 6.0, 13.0, C_TEXT);
    let x = panel.x + 12.0;
    let w = panel.w - 24.0;
    let mut y = panel.y + 36.0;

    // header row: what's selected + edit modes
    let (title, sub) = match app.sel {
        Sel::None => ("Nothing selected".to_string(), String::new()),
        Sel::Node(id) => match app.node(id) {
            Some(n) => (n.name.clone(), n.kind.type_label().to_string()),
            None => ("Nothing selected".into(), String::new()),
        },
        Sel::Material(i) => (app.materials.get(i).map(|m| m.name.clone()).unwrap_or_default(), "Material".into()),
        Sel::Mesh(i) => (app.meshes.get(i).map(|m| m.name.clone()).unwrap_or_default(), "Mesh".into()),
        Sel::Window => ("Window properties".into(), "Viewport and lighting".into()),
    };
    ui.text_fit(&title, x, y + 2.0, w * 0.5, 15.0, WHITE);
    ui.record(&format!("hdr:{}", title), Rect::new(x, y, w * 0.5, 20.0));
    if !sub.is_empty() {
        ui.text(&sub, x, y + 21.0, 11.5, C_TEXT_DIM);
    }
    let bx = x + w - 210.0;
    let bw = 70.0;
    let is_node = matches!(app.sel, Sel::Node(_));
    draw_rectangle(bx - 2.0, y - 2.0, bw * 3.0 + 4.0, 26.0, C_BG);
    ui.button_ex("mode.gen", Rect::new(bx, y, bw, 22.0), "Generator", is_node, true);
    ui.button_ex("mode.node", Rect::new(bx + bw, y, bw, 22.0), "Node", false, false);
    ui.button_ex("mode.free", Rect::new(bx + bw * 2.0, y, bw, 22.0), "Freehand", false, false);
    y += 44.0;
    draw_line(panel.x + 8.0, y - 6.0, panel.x + panel.w - 8.0, y - 6.0, 1.0, C_LINE);

    let body = Rect::new(panel.x, y, panel.w, panel.y + panel.h - y);
    if ui.hover_any(body) && ui.inp.wheel != 0.0 && ui.popup.is_none() {
        app.prop_scroll = (app.prop_scroll - ui.inp.wheel * 60.0).max(0.0);
    }
    ui.set_clip(Some(body));
    let start_y = y - app.prop_scroll;

    let mat_names: Vec<String> = app.materials.iter().map(|m| m.name.clone()).collect();
    let mnames = mesh_names(&app.meshes);
    let mut closed = std::mem::take(&mut app.closed_groups);
    let mut rows = Rows { ui, x, y: start_y, w, changed: false, prefix: String::new(), closed: &mut closed, open: true };
    match app.sel {
        Sel::None => {
            rows.note("");
            rows.y -= 20.0;
            let mut act = None;
            for (sec, items) in [
                ("Edit", vec![("Global properties", 1), ("Window properties", 2)]),
                ("Actions", vec![("Randomize", 3), ("Frame tree", 4)]),
                ("File", vec![("New tree", 5)]),
            ] {
                rows.ui.text(sec, x, rows.y + 4.0, 14.0, C_TEXT);
                rows.y += 28.0;
                let bw2 = (w - 8.0) / 2.0;
                for (k, (label, id)) in items.iter().enumerate() {
                    let r = Rect::new(x + 4.0 + (k % 2) as f32 * (bw2 + 6.0) - 4.0, rows.y + (k / 2) as f32 * 32.0, bw2 - 2.0, 27.0);
                    if rows.ui.button(&format!("home.{}", label), r, label) {
                        act = Some(*id);
                    }
                }
                rows.y += ((items.len() + 1) / 2) as f32 * 32.0 + 12.0;
            }
            rows.ui.text("Help", x, rows.y + 4.0, 14.0, C_TEXT);
            rows.y += 28.0;
            for line in [
                "Generation tab: Add a Trunk, Branch or Leaf to the",
                "selected node; click a node to edit it here.",
                "Shift+drag from one node onto another to re-link it.",
                "Viewport: left-drag orbit, middle/shift-drag pan,",
                "right-drag or wheel zoom, F frame the tree.",
                "Keys 0 perspective, 1 front, 3 right, 7 top, 5 ortho.",
            ] {
                rows.note(line);
            }
            match act {
                Some(1) => {
                    let root = app.root_id();
                    app.select(Sel::Node(root));
                }
                Some(2) => app.select(Sel::Window),
                Some(3) => app.randomize(None),
                Some(4) => app.frame_tree(),
                Some(5) => app.new_tree(),
                _ => {}
            }
        }
        Sel::Node(id) => {
            let on_ground = app.node(id).and_then(|n| n.parent).map(|p| app.node(p).map(|q| q.kind == Kind::Tree).unwrap_or(false)).unwrap_or(false);
            let stats = (app.geo_stats.0, app.geo_stats.1, app.geo_stats.2, app.geo_stats.3);
            let count = app.instance_count(id);
            if let Some(idx) = app.nodes.iter().position(|n| n.id == id) {
                rows.prefix = format!("n{}", id);
                let mut n = app.nodes[idx].clone();
                node_props(&mut rows, &mut n, on_ground, &mat_names, &mnames, stats, count);
                if rows.changed {
                    app.nodes[idx] = n;
                    app.dirty = true;
                }
            }
        }
        Sel::Material(i) => {
            if i < app.materials.len() {
                rows.prefix = format!("m{}", i);
                let mut m = app.materials[i].clone();
                let (ch, tex, base) = material_props(&mut rows, &mut m, &mnames);
                if ch || tex || base {
                    if base {
                        m.dirty_base = true;
                    }
                    if tex {
                        m.dirty_tex = true;
                    }
                    app.materials[i] = m;
                    textures::refresh_material(&mut app.materials[i]);
                    app.dirty = true;
                }
            }
        }
        Sel::Mesh(i) => {
            if i < app.meshes.len() {
                rows.prefix = format!("me{}", i);
                let mut m = app.meshes[i].clone();
                let mut act = 0;
                if rows.group("Mesh") {
                    rows.info("Name", &m.name.clone());
                    let mut rm = m.ref_material.min(mat_names.len().saturating_sub(1));
                    rows.combo("ref", "Reference material", &mat_names, &mut rm);
                    m.ref_material = rm;
                    rows.f("scale", "Scale", &mut m.scale, 0.1, 4.0, 2);
                    rows.b("flip", "Flip horizontally", &mut m.flip);
                }
                if rows.group("Cutout") {
                    rows.i("points", "Outline points", &mut m.auto_points, 3, 32);
                    rows.f("thr", "Alpha threshold", &mut m.threshold, 0.01, 0.99, 2);
                    rows.f("margin", "Margin", &mut m.margin, 0.0, 0.1, 3);
                    if rows.button("gen", "Generate from material") {
                        act = 1;
                    }
                    if rows.button("card", "Reset to card") {
                        act = 2;
                    }
                }
                if rows.group("Level of Detail") {
                    rows.info("LOD count", &m.lods.len().to_string());
                    let l = app.mesh_lod.min(m.lods.len() - 1);
                    rows.info("Editing", &format!("LOD{} ({} points)", l, m.lods[l].len()));
                    if rows.button("addlod", "Add LOD (fewer points)") {
                        act = 3;
                    }
                    if rows.button("remlod", "Remove last LOD") {
                        act = 4;
                    }
                }
                match act {
                    1 => {
                        if let Some(img) = app.materials.get(m.ref_material).and_then(|mm| mm.adjusted.clone()) {
                            let l = app.mesh_lod.min(m.lods.len() - 1);
                            m.lods[l] = textures::auto_cutout(&img, m.auto_points as usize, m.threshold, m.margin);
                        }
                        rows.changed = true;
                    }
                    2 => {
                        let l = app.mesh_lod.min(m.lods.len() - 1);
                        m.lods[l] = LeafMesh::card("").lods[0].clone();
                        rows.changed = true;
                    }
                    3 => {
                        let last = m.lods.last().unwrap().clone();
                        let n = (last.len() / 2).max(3);
                        m.lods.push(textures::reduce_outline(last, n));
                        app.mesh_lod = m.lods.len() - 1;
                        rows.changed = true;
                    }
                    4 => {
                        if m.lods.len() > 1 {
                            m.lods.pop();
                            app.mesh_lod = app.mesh_lod.min(m.lods.len() - 1);
                            rows.changed = true;
                        }
                    }
                    _ => {}
                }
                if rows.changed {
                    app.meshes[i] = m;
                    app.dirty = true;
                }
            }
        }
        Sel::Window => {
            rows.prefix = "win".into();
            if rows.group("Camera") {
                let views: Vec<String> = VIEWS.iter().map(|s| s.to_string()).collect();
                let mut v = app.cam.view;
                rows.combo("view", "View", &views, &mut v);
                if v != app.cam.view {
                    app.cam.set_view(v);
                }
                rows.b("ortho", "Orthographic", &mut app.cam.ortho);
                rows.f("fov", "Field of view", &mut app.cam.fov, 10.0, 100.0, 0);
            }
            if rows.group("Display") {
                rows.b("grid", "Show grid", &mut app.show_grid);
                let before = app.highlight;
                rows.b("hl", "Highlight selected generator", &mut app.highlight);
                if before != app.highlight {
                    app.dirty = true;
                }
                rows.b("unlit", "Unlit (texture colours only)", &mut app.light.unlit);
            }
            if rows.group("Lighting") {
                rows.f("az", "Sun direction", &mut app.light.azimuth, -180.0, 180.0, 0);
                rows.f("el", "Sun height", &mut app.light.elevation, 5.0, 90.0, 0);
            }
        }
    }
    let content_h = rows.y - start_y;
    drop(rows);
    app.closed_groups = closed;
    let max_scroll = (content_h - body.h + 20.0).max(0.0);
    app.prop_scroll = app.prop_scroll.min(max_scroll);
    ui.set_clip(None);
    if max_scroll > 0.0 {
        let frac = body.h / (content_h + 20.0);
        let th = (body.h * frac).max(24.0);
        let ty = body.y + (body.h - th) * (app.prop_scroll / max_scroll);
        draw_rectangle(panel.x + panel.w - 5.0, ty, 3.0, th, Color::new(1.0, 1.0, 1.0, 0.2));
    }
}

//! Application state and the dock panels (Generation graph, Materials, Meshes) and viewport.
use crate::gen::{self, GenCtx};
use crate::model::*;
use crate::render::{self, Cam, GpuTree, Lighting, VIEWS};
use crate::textures;
use crate::ui::*;
use macroquad::prelude::*;
use std::collections::{HashMap, HashSet};

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Sel {
    None,
    Node(u32),
    Material(usize),
    Mesh(usize),
    Window,
}

pub const TABS: [&str; 3] = ["Generation", "Materials", "Meshes"];

pub struct Icons {
    pub tree: Texture2D,
    pub branch: Texture2D,
    pub leaf: Texture2D,
    pub ring: Texture2D,
}

impl Icons {
    pub fn load() -> Self {
        let l = |b: &[u8]| {
            let t = Texture2D::from_file_with_format(b, Some(ImageFormat::Png));
            t.set_filter(FilterMode::Linear);
            t
        };
        Icons {
            tree: l(include_bytes!("../assets/icons/generator_tree.png")),
            branch: l(include_bytes!("../assets/icons/generator_branch.png")),
            leaf: l(include_bytes!("../assets/icons/generator_leaf.png")),
            ring: l(include_bytes!("../assets/icons/generator_border.png")),
        }
    }
    fn for_kind(&self, k: Kind) -> &Texture2D {
        match k {
            Kind::Tree => &self.tree,
            Kind::Trunk | Kind::Branch => &self.branch,
            Kind::Leaf => &self.leaf,
        }
    }
}

#[derive(Clone, Copy, PartialEq)]
enum GraphDrag {
    None,
    Node { id: u32, start: Vec2, moved: bool },
    Link { from: u32 },
    Pan,
}

#[derive(Clone, Copy, PartialEq)]
enum VpDrag {
    None,
    Orbit,
    Pan,
    Zoom,
}

pub struct App {
    pub nodes: Vec<Node>,
    pub next_id: u32,
    pub materials: Vec<Material>,
    pub meshes: Vec<LeafMesh>,
    pub sel: Sel,
    pub tab: usize,
    pub cam: Cam,
    pub light: Lighting,
    pub show_grid: bool,
    pub highlight: bool,
    pub dirty: bool,
    pub gpu: Option<GpuTree>,
    pub geo_stats: (usize, usize, usize, usize),
    pub per_node: HashMap<u32, usize>,
    pub bounds: (Vec3, Vec3),
    pub prop_scroll: f32,
    pub closed_groups: HashSet<String>,
    pub graph_off: Vec2,
    pub graph_zoom: f32,
    graph_drag: GraphDrag,
    vp_drag: VpDrag,
    last_mouse: Vec2,
    pub mesh_cur: usize,
    pub mesh_lod: usize,
    mesh_drag: Option<i32>,
    pub mat_cur: usize,
    pub preview_sphere: bool,
    pub preview_rt: Option<RenderTarget>,
    pub status: String,
    pub status_t: f64,
    pub gm: Option<macroquad::material::Material>,
    pub icons: Icons,
    pub viewport: Rect,
    pub regen_count: usize,
    sphere: Vec<Mesh>,
    card: Vec<Mesh>,
}

impl App {
    pub fn new() -> Self {
        let gm = match render::make_material() {
            Ok(m) => Some(m),
            Err(e) => {
                eprintln!("shader error: {}", e);
                None
            }
        };
        let mk = |v: Vec<(Vec<macroquad::models::Vertex>, Vec<u16>)>| v.into_iter().map(|(a, b)| Mesh { vertices: a, indices: b, texture: None }).collect::<Vec<_>>();
        let mut app = App {
            nodes: vec![],
            next_id: 1,
            materials: vec![],
            meshes: vec![],
            sel: Sel::None,
            tab: 0,
            cam: Cam::new(),
            light: Lighting { azimuth: 35.0, elevation: 50.0, unlit: false },
            show_grid: true,
            highlight: true,
            dirty: true,
            gpu: None,
            geo_stats: (0, 0, 0, 0),
            per_node: HashMap::new(),
            bounds: (Vec3::ZERO, Vec3::ONE),
            prop_scroll: 0.0,
            closed_groups: HashSet::new(),
            graph_off: Vec2::ZERO,
            graph_zoom: 1.0,
            graph_drag: GraphDrag::None,
            vp_drag: VpDrag::None,
            last_mouse: Vec2::ZERO,
            mesh_cur: 0,
            mesh_lod: 0,
            mesh_drag: None,
            mat_cur: 0,
            preview_sphere: true,
            preview_rt: None,
            status: String::new(),
            status_t: 0.0,
            gm,
            icons: Icons::load(),
            viewport: Rect::new(0.0, 0.0, 1.0, 1.0),
            regen_count: 0,
            sphere: mk(render::sphere_mesh(1.0)),
            card: mk(render::card_mesh(1.0)),
        };
        app.reset_library();
        app.new_tree();
        // starting graph: one of each building block, all on their default settings
        let root = app.root_id();
        let trunk = app.add_node(Kind::Trunk, root);
        let br = app.add_node(Kind::Branch, trunk);
        app.add_node(Kind::Leaf, br);
        app.select(Sel::None);
        app.regenerate();
        app.frame_tree();
        app
    }

    fn reset_library(&mut self) {
        self.materials = vec![Material::bark(), Material::leaf()];
        for m in &mut self.materials {
            textures::refresh_material(m);
        }
        let mut cut = LeafMesh::card("Leaf cutout");
        if let Some(img) = &self.materials[1].adjusted {
            cut.lods[0] = textures::auto_cutout(img, cut.auto_points as usize, cut.threshold, cut.margin);
            let l1 = textures::reduce_outline(cut.lods[0].clone(), 5);
            cut.lods.push(l1);
        }
        self.meshes = vec![cut];
    }

    pub fn set_status(&mut self, s: &str) {
        self.status = s.to_string();
        self.status_t = get_time();
    }

    pub fn node(&self, id: u32) -> Option<&Node> {
        self.nodes.iter().find(|n| n.id == id)
    }
    pub fn root_id(&self) -> u32 {
        self.nodes.iter().find(|n| n.kind == Kind::Tree).map(|n| n.id).unwrap_or(0)
    }
    pub fn instance_count(&self, id: u32) -> usize {
        *self.per_node.get(&id).unwrap_or(&0)
    }

    pub fn new_tree(&mut self) {
        self.nodes.clear();
        self.next_id = 1;
        let id = self.next_id;
        self.next_id += 1;
        self.nodes.push(Node { id, kind: Kind::Tree, name: "Tree".into(), parent: None, pos: vec2(0.0, 0.0), p: Params::new(Kind::Tree), hidden: false });
        self.sel = Sel::None;
        self.dirty = true;
        self.graph_off = Vec2::ZERO;
    }

    pub fn select(&mut self, s: Sel) {
        if self.sel != s {
            self.sel = s;
            self.prop_scroll = 0.0;
            self.dirty = true;
        }
        if let Sel::Material(i) = s {
            self.mat_cur = i;
        }
        if let Sel::Mesh(i) = s {
            self.mesh_cur = i;
        }
    }

    pub fn add_node(&mut self, kind: Kind, parent: u32) -> u32 {
        let parent = match self.node(parent) {
            Some(p) if p.kind.can_parent() && !(kind == Kind::Trunk && p.kind == Kind::Leaf) => parent,
            _ => self.root_id(),
        };
        let pp = self.node(parent).map(|n| n.pos).unwrap_or(Vec2::ZERO);
        let siblings = self.nodes.iter().filter(|n| n.parent == Some(parent)).count();
        let id = self.next_id;
        self.next_id += 1;
        let same = self.nodes.iter().filter(|n| n.kind == kind).count();
        let name = if same == 0 { kind.label().to_string() } else { format!("{} {}", kind.label(), same + 1) };
        let mut p = Params::new(kind);
        p.seed += id as i32 * 13;
        let x = pp.x + if siblings == 0 { 0.0 } else { (siblings as f32 + 1.0) / 2.0 * 90.0 * if siblings % 2 == 1 { 1.0 } else { -1.0 } };
        self.nodes.push(Node { id, kind, name, parent: Some(parent), pos: vec2(x, pp.y - 100.0), p, hidden: false });
        self.select(Sel::Node(id));
        self.dirty = true;
        id
    }

    fn descendants(&self, id: u32) -> Vec<u32> {
        let mut out = vec![id];
        let mut i = 0;
        while i < out.len() {
            let cur = out[i];
            for n in &self.nodes {
                if n.parent == Some(cur) {
                    out.push(n.id);
                }
            }
            i += 1;
        }
        out
    }

    pub fn delete_node(&mut self, id: u32) {
        if self.node(id).map(|n| n.kind == Kind::Tree).unwrap_or(true) {
            self.set_status("The Tree node can't be deleted");
            return;
        }
        let gone = self.descendants(id);
        self.nodes.retain(|n| !gone.contains(&n.id));
        self.select(Sel::None);
        self.dirty = true;
    }

    pub fn duplicate_node(&mut self, id: u32) {
        let src = match self.node(id) {
            Some(n) if n.kind != Kind::Tree => n.clone(),
            _ => return,
        };
        let nid = self.next_id;
        self.next_id += 1;
        let mut n = src.clone();
        n.id = nid;
        n.name = format!("{} copy", src.name);
        n.pos += vec2(80.0, 0.0);
        n.p.seed += 97;
        self.nodes.push(n);
        self.select(Sel::Node(nid));
        self.dirty = true;
    }

    pub fn randomize(&mut self, id: Option<u32>) {
        for n in &mut self.nodes {
            if id.map(|i| i == n.id).unwrap_or(true) {
                n.p.seed = macroquad::rand::gen_range(0, 9999);
            }
        }
        self.dirty = true;
    }

    pub fn arrange(&mut self) {
        let root = self.root_id();
        let mut x_cursor = 0.0f32;
        fn place(app: &mut App, id: u32, depth: i32, x: &mut f32) -> f32 {
            let kids: Vec<u32> = app.nodes.iter().filter(|n| n.parent == Some(id)).map(|n| n.id).collect();
            let px = if kids.is_empty() {
                let v = *x;
                *x += 90.0;
                v
            } else {
                let xs: Vec<f32> = kids.iter().map(|k| place(app, *k, depth + 1, x)).collect();
                (xs[0] + xs[xs.len() - 1]) * 0.5
            };
            if let Some(n) = app.nodes.iter_mut().find(|n| n.id == id) {
                n.pos = vec2(px, -(depth as f32) * 100.0);
            }
            px
        }
        let rx = place(self, root, 0, &mut x_cursor);
        for n in &mut self.nodes {
            n.pos.x -= rx;
        }
        self.graph_off = Vec2::ZERO;
    }

    fn reparent(&mut self, child: u32, parent: u32) {
        if child == parent {
            return;
        }
        let ok_parent = self.node(parent).map(|p| p.kind.can_parent()).unwrap_or(false);
        let ck = self.node(child).map(|c| c.kind);
        if !ok_parent || ck == Some(Kind::Tree) || self.descendants(child).contains(&parent) {
            self.set_status("Can't link those two nodes");
            return;
        }
        if let Some(c) = self.nodes.iter_mut().find(|n| n.id == child) {
            c.parent = Some(parent);
        }
        self.dirty = true;
        self.set_status("Linked");
    }

    pub fn regenerate(&mut self) {
        for m in &mut self.materials {
            textures::refresh_material(m);
        }
        let selected = if let Sel::Node(id) = self.sel { Some(id) } else { None };
        let ctx = GenCtx { nodes: &self.nodes, materials: &self.materials, meshes: &self.meshes, selected, highlight: self.highlight };
        let geo = gen::generate(&ctx);
        self.geo_stats = (geo.tris, geo.verts, geo.spines, geo.leaves);
        self.per_node = geo.per_node.clone();
        self.bounds = (geo.bmin, geo.bmax);
        self.gpu = Some(render::upload(&geo));
        self.dirty = false;
        self.regen_count += 1;
    }

    pub fn frame_tree(&mut self) {
        let (a, b) = self.bounds;
        let b2 = vec3(b.x, b.y.max(a.y + 1.0), b.z);
        self.cam.frame(vec3(a.x, a.y.min(0.0), a.z), b2);
    }

    // ------------------------------------------------------------------ viewport
    pub fn viewport_input(&mut self, ui: &mut Ui, r: Rect) {
        let m = ui.mouse();
        let over = r.contains(m) && !ui.blocked && ui.popup.is_none();
        let inp = ui.inp.clone();
        if over && inp.wheel != 0.0 {
            self.cam.zoom(inp.wheel);
        }
        if over && ui.active == 0 && self.vp_drag == VpDrag::None {
            if inp.l_pressed {
                self.vp_drag = if inp.shift || inp.alt && inp.ctrl { VpDrag::Pan } else { VpDrag::Orbit };
                self.last_mouse = m;
                ui.active = hid("viewport");
            } else if inp.m_pressed {
                self.vp_drag = VpDrag::Pan;
                self.last_mouse = m;
            } else if inp.r_pressed {
                self.vp_drag = VpDrag::Zoom;
                self.last_mouse = m;
            }
        }
        let d = m - self.last_mouse;
        match self.vp_drag {
            VpDrag::Orbit => {
                if inp.l_down {
                    self.cam.orbit(d.x, d.y);
                } else {
                    self.vp_drag = VpDrag::None;
                }
            }
            VpDrag::Pan => {
                if inp.l_down || inp.m_down {
                    self.cam.pan(-d.x, d.y, r.h);
                } else {
                    self.vp_drag = VpDrag::None;
                }
            }
            VpDrag::Zoom => {
                if inp.r_down {
                    self.cam.zoom(-d.y * 0.03);
                } else {
                    self.vp_drag = VpDrag::None;
                }
            }
            VpDrag::None => {}
        }
        self.last_mouse = m;
    }

    pub fn draw_viewport_3d(&mut self, r: Rect, scale: f32) {
        // background gradient
        let top = Color::new(0.26, 0.27, 0.29, 1.0);
        let bot = Color::new(0.14, 0.14, 0.15, 1.0);
        let steps = 24;
        for i in 0..steps {
            let t = i as f32 / steps as f32;
            let c = Color::new(top.r + (bot.r - top.r) * t, top.g + (bot.g - top.g) * t, top.b + (bot.b - top.b) * t, 1.0);
            draw_rectangle(r.x, r.y + r.h * t, r.w, r.h / steps as f32 + 1.0, c);
        }
        let sh = screen_height();
        let vp = ((r.x * scale) as i32, (sh - (r.y + r.h) * scale) as i32, (r.w * scale) as i32, (r.h * scale) as i32);
        let cam3 = self.cam.camera3d(Some(vp), r.w / r.h.max(1.0), None);
        set_camera(&cam3);
        if self.show_grid {
            render::draw_grid(50.0, 2.5);
        }
        if let (Some(gpu), Some(gm)) = (&mut self.gpu, &self.gm) {
            for (mi, meshes) in &mut gpu.parts {
                if let Some(m) = self.materials.get(*mi) {
                    for mesh in meshes.iter_mut() {
                        mesh.texture = m.tex.clone();
                    }
                }
            }
            draw_gpu(gpu, &self.materials, gm, &self.light, self.cam.position());
        }
        set_default_camera();
    }

