//! Application state and the dock panels (Generation graph, Materials, Meshes) and viewport.
use crate::gen::{self, GenCtx};
use crate::model::*;
use crate::render::{self, Cam, GpuTree, Lighting, VIEWS};
use crate::textures;
use crate::ui::*;
use macroquad::prelude::*;
use std::collections::{HashMap, HashSet};

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Sel {
    None,
    Node(u32),
    Material(usize),
    Mesh(usize),
    Window,
}

pub const TABS: [&str; 3] = ["Generation", "Materials", "Meshes"];

pub struct Icons {
    pub tree: Texture2D,
    pub branch: Texture2D,
    pub leaf: Texture2D,
    pub ring: Texture2D,
}

impl Icons {
    pub fn load() -> Self {
        let l = |b: &[u8]| {
            let t = Texture2D::from_file_with_format(b, Some(ImageFormat::Png));
            t.set_filter(FilterMode::Linear);
            t
        };
        Icons {
            tree: l(include_bytes!("../assets/icons/generator_tree.png")),
            branch: l(include_bytes!("../assets/icons/generator_branch.png")),
            leaf: l(include_bytes!("../assets/icons/generator_leaf.png")),
            ring: l(include_bytes!("../assets/icons/generator_border.png")),
        }
    }
    fn for_kind(&self, k: Kind) -> &Texture2D {
        match k {
            Kind::Tree => &self.tree,
            Kind::Trunk | Kind::Branch => &self.branch,
            Kind::Leaf => &self.leaf,
        }
    }
}

#[derive(Clone, Copy, PartialEq)]
enum GraphDrag {
    None,
    Node { id: u32, start: Vec2, moved: bool },
    Link { from: u32 },
    Pan,
}

#[derive(Clone, Copy, PartialEq)]
enum VpDrag {
    None,
    Orbit,
    Pan,
    Zoom,
}

pub struct App {
    pub nodes: Vec<Node>,
    pub next_id: u32,
    pub materials: Vec<Material>,
    pub meshes: Vec<LeafMesh>,
    pub sel: Sel,
    pub tab: usize,
    pub cam: Cam,
    pub light: Lighting,
    pub show_grid: bool,
    pub highlight: bool,
    pub dirty: bool,
    pub gpu: Option<GpuTree>,
    pub geo_stats: (usize, usize, usize, usize),
    pub per_node: HashMap<u32, usize>,
    pub bounds: (Vec3, Vec3),
    pub prop_scroll: f32,
    pub closed_groups: HashSet<String>,
    pub graph_off: Vec2,
    pub graph_zoom: f32,
    graph_drag: GraphDrag,
    vp_drag: VpDrag,
    last_mouse: Vec2,
    pub mesh_cur: usize,
    pub mesh_lod: usize,
    mesh_drag: Option<i32>,
    pub mat_cur: usize,
    pub preview_sphere: bool,
    pub preview_rt: Option<RenderTarget>,
    pub status: String,
    pub status_t: f64,
    pub gm: Option<macroquad::material::Material>,
    pub icons: Icons,
    pub viewport: Rect,
    pub regen_count: usize,
    sphere: Vec<Mesh>,
    card: Vec<Mesh>,
}

impl App {
    pub fn new() -> Self {
        let gm = match render::make_material() {
            Ok(m) => Some(m),
            Err(e) => {
                eprintln!("shader error: {}", e);
                None
            }
        };
        let mk = |v: Vec<(Vec<macroquad::models::Vertex>, Vec<u16>)>| v.into_iter().map(|(a, b)| Mesh { vertices: a, indices: b, texture: None }).collect::<Vec<_>>();
        let mut app = App {
            nodes: vec![],
            next_id: 1,
            materials: vec![],
            meshes: vec![],
            sel: Sel::None,
            tab: 0,
            cam: Cam::new(),
            light: Lighting { azimuth: 35.0, elevation: 50.0, unlit: false },
            show_grid: true,
            highlight: true,
            dirty: true,
            gpu: None,
            geo_stats: (0, 0, 0, 0),
            per_node: HashMap::new(),
            bounds: (Vec3::ZERO, Vec3::ONE),
            prop_scroll: 0.0,
            closed_groups: HashSet::new(),
            graph_off: Vec2::ZERO,
            graph_zoom: 1.0,
            graph_drag: GraphDrag::None,
            vp_drag: VpDrag::None,
            last_mouse: Vec2::ZERO,
            mesh_cur: 0,
            mesh_lod: 0,
            mesh_drag: None,
            mat_cur: 0,
            preview_sphere: true,
            preview_rt: None,
            status: String::new(),
            status_t: 0.0,
            gm,
            icons: Icons::load(),
            viewport: Rect::new(0.0, 0.0, 1.0, 1.0),
            regen_count: 0,
            sphere: mk(render::sphere_mesh(1.0)),
            card: mk(render::card_mesh(1.0)),
        };
        app.reset_library();
        app.new_tree();
        // starting graph: one of each building block, all on their default settings
        let root = app.root_id();
        let trunk = app.add_node(Kind::Trunk, root);
        let br = app.add_node(Kind::Branch, trunk);
        app.add_node(Kind::Leaf, br);
        app.select(Sel::None);
        app.regenerate();
        app.frame_tree();
        app
    }

    fn reset_library(&mut self) {
        self.materials = vec![Material::bark(), Material::leaf()];
        for m in &mut self.materials {
            textures::refresh_material(m);
        }
        let mut cut = LeafMesh::card("Leaf cutout");
        if let Some(img) = &self.materials[1].adjusted {
            cut.lods[0] = textures::auto_cutout(img, cut.auto_points as usize, cut.threshold, cut.margin);
            let l1 = textures::reduce_outline(cut.lods[0].clone(), 5);
            cut.lods.push(l1);
        }
        self.meshes = vec![cut];
    }

    pub fn set_status(&mut self, s: &str) {
        self.status = s.to_string();
        self.status_t = get_time();
    }

    pub fn node(&self, id: u32) -> Option<&Node> {
        self.nodes.iter().find(|n| n.id == id)
    }
    pub fn root_id(&self) -> u32 {
        self.nodes.iter().find(|n| n.kind == Kind::Tree).map(|n| n.id).unwrap_or(0)
    }
    pub fn instance_count(&self, id: u32) -> usize {
        *self.per_node.get(&id).unwrap_or(&0)
    }

    pub fn new_tree(&mut self) {
        self.nodes.clear();
        self.next_id = 1;
        let id = self.next_id;
        self.next_id += 1;
        self.nodes.push(Node { id, kind: Kind::Tree, name: "Tree".into(), parent: None, pos: vec2(0.0, 0.0), p: Params::new(Kind::Tree), hidden: false });
        self.sel = Sel::None;
        self.dirty = true;
        self.graph_off = Vec2::ZERO;
    }

    pub fn select(&mut self, s: Sel) {
        if self.sel != s {
            self.sel = s;
            self.prop_scroll = 0.0;
            self.dirty = true;
        }
        if let Sel::Material(i) = s {
            self.mat_cur = i;
        }
        if let Sel::Mesh(i) = s {
            self.mesh_cur = i;
        }
    }

    pub fn add_node(&mut self, kind: Kind, parent: u32) -> u32 {
        let parent = match self.node(parent) {
            Some(p) if p.kind.can_parent() && !(kind == Kind::Trunk && p.kind == Kind::Leaf) => parent,
            _ => self.root_id(),
        };
        let pp = self.node(parent).map(|n| n.pos).unwrap_or(Vec2::ZERO);
        let siblings = self.nodes.iter().filter(|n| n.parent == Some(parent)).count();
        let id = self.next_id;
        self.next_id += 1;
        let same = self.nodes.iter().filter(|n| n.kind == kind).count();
        let name = if same == 0 { kind.label().to_string() } else { format!("{} {}", kind.label(), same + 1) };
        let mut p = Params::new(kind);
        p.seed += id as i32 * 13;
        let x = pp.x + if siblings == 0 { 0.0 } else { (siblings as f32 + 1.0) / 2.0 * 90.0 * if siblings % 2 == 1 { 1.0 } else { -1.0 } };
        self.nodes.push(Node { id, kind, name, parent: Some(parent), pos: vec2(x, pp.y - 100.0), p, hidden: false });
        self.select(Sel::Node(id));
        self.dirty = true;
        id
    }

    fn descendants(&self, id: u32) -> Vec<u32> {
        let mut out = vec![id];
        let mut i = 0;
        while i < out.len() {
            let cur = out[i];
            for n in &self.nodes {
                if n.parent == Some(cur) {
                    out.push(n.id);
                }
            }
            i += 1;
        }
        out
    }

    pub fn delete_node(&mut self, id: u32) {
        if self.node(id).map(|n| n.kind == Kind::Tree).unwrap_or(true) {
            self.set_status("The Tree node can't be deleted");
            return;
        }
        let gone = self.descendants(id);
        self.nodes.retain(|n| !gone.contains(&n.id));
        self.select(Sel::None);
        self.dirty = true;
    }

    pub fn duplicate_node(&mut self, id: u32) {
        let src = match self.node(id) {
            Some(n) if n.kind != Kind::Tree => n.clone(),
            _ => return,
        };
        let nid = self.next_id;
        self.next_id += 1;
        let mut n = src.clone();
        n.id = nid;
        n.name = format!("{} copy", src.name);
        n.pos += vec2(80.0, 0.0);
        n.p.seed += 97;
        self.nodes.push(n);
        self.select(Sel::Node(nid));
        self.dirty = true;
    }

    pub fn randomize(&mut self, id: Option<u32>) {
        for n in &mut self.nodes {
            if id.map(|i| i == n.id).unwrap_or(true) {
                n.p.seed = macroquad::rand::gen_range(0, 9999);
            }
        }
        self.dirty = true;
    }

    pub fn arrange(&mut self) {
        let root = self.root_id();
        let mut x_cursor = 0.0f32;
        fn place(app: &mut App, id: u32, depth: i32, x: &mut f32) -> f32 {
            let kids: Vec<u32> = app.nodes.iter().filter(|n| n.parent == Some(id)).map(|n| n.id).collect();
            let px = if kids.is_empty() {
                let v = *x;
                *x += 90.0;
                v
            } else {
                let xs: Vec<f32> = kids.iter().map(|k| place(app, *k, depth + 1, x)).collect();
                (xs[0] + xs[xs.len() - 1]) * 0.5
            };
            if let Some(n) = app.nodes.iter_mut().find(|n| n.id == id) {
                n.pos = vec2(px, -(depth as f32) * 100.0);
            }
            px
        }
        let rx = place(self, root, 0, &mut x_cursor);
        for n in &mut self.nodes {
            n.pos.x -= rx;
        }
        self.graph_off = Vec2::ZERO;
    }

    fn reparent(&mut self, child: u32, parent: u32) {
        if child == parent {
            return;
        }
        let ok_parent = self.node(parent).map(|p| p.kind.can_parent()).unwrap_or(false);
        let ck = self.node(child).map(|c| c.kind);
        if !ok_parent || ck == Some(Kind::Tree) || self.descendants(child).contains(&parent) {
            self.set_status("Can't link those two nodes");
            return;
        }
        if let Some(c) = self.nodes.iter_mut().find(|n| n.id == child) {
            c.parent = Some(parent);
        }
        self.dirty = true;
        self.set_status("Linked");
    }

    pub fn regenerate(&mut self) {
        for m in &mut self.materials {
            textures::refresh_material(m);
        }
        let selected = if let Sel::Node(id) = self.sel { Some(id) } else { None };
        let ctx = GenCtx { nodes: &self.nodes, materials: &self.materials, meshes: &self.meshes, selected, highlight: self.highlight };
        let geo = gen::generate(&ctx);
        self.geo_stats = (geo.tris, geo.verts, geo.spines, geo.leaves);
        self.per_node = geo.per_node.clone();
        self.bounds = (geo.bmin, geo.bmax);
        self.gpu = Some(render::upload(&geo));
        self.dirty = false;
        self.regen_count += 1;
    }

    pub fn frame_tree(&mut self) {
        let (a, b) = self.bounds;
        let b2 = vec3(b.x, b.y.max(a.y + 1.0), b.z);
        self.cam.frame(vec3(a.x, a.y.min(0.0), a.z), b2);
    }

    // ------------------------------------------------------------------ viewport
    pub fn viewport_input(&mut self, ui: &mut Ui, r: Rect) {
        let m = ui.mouse();
        let over = r.contains(m) && !ui.blocked && ui.popup.is_none();
        let inp = ui.inp.clone();
        if over && inp.wheel != 0.0 {
            self.cam.zoom(inp.wheel);
        }
        if over && ui.active == 0 && self.vp_drag == VpDrag::None {
            if inp.l_pressed {
                self.vp_drag = if inp.shift || inp.alt && inp.ctrl { VpDrag::Pan } else { VpDrag::Orbit };
                self.last_mouse = m;
                ui.active = hid("viewport");
            } else if inp.m_pressed {
                self.vp_drag = VpDrag::Pan;
                self.last_mouse = m;
            } else if inp.r_pressed {
                self.vp_drag = VpDrag::Zoom;
                self.last_mouse = m;
            }
        }
        let d = m - self.last_mouse;
        match self.vp_drag {
            VpDrag::Orbit => {
                if inp.l_down {
                    self.cam.orbit(d.x, d.y);
                } else {
                    self.vp_drag = VpDrag::None;
                }
            }
            VpDrag::Pan => {
                if inp.l_down || inp.m_down {
                    self.cam.pan(-d.x, d.y, r.h);
                } else {
                    self.vp_drag = VpDrag::None;
                }
            }
            VpDrag::Zoom => {
                if inp.r_down {
                    self.cam.zoom(-d.y * 0.03);
                } else {
                    self.vp_drag = VpDrag::None;
                }
            }
            VpDrag::None => {}
        }
        self.last_mouse = m;
    }

    pub fn draw_viewport_3d(&mut self, r: Rect, scale: f32) {
        // background gradient
        let top = Color::new(0.26, 0.27, 0.29, 1.0);
        let bot = Color::new(0.14, 0.14, 0.15, 1.0);
        let steps = 24;
        for i in 0..steps {
            let t = i as f32 / steps as f32;
            let c = Color::new(top.r + (bot.r - top.r) * t, top.g + (bot.g - top.g) * t, top.b + (bot.b - top.b) * t, 1.0);
            draw_rectangle(r.x, r.y + r.h * t, r.w, r.h / steps as f32 + 1.0, c);
        }
        let sh = screen_height();
        let vp = ((r.x * scale) as i32, (sh - (r.y + r.h) * scale) as i32, (r.w * scale) as i32, (r.h * scale) as i32);
        let cam3 = self.cam.camera3d(Some(vp), r.w / r.h.max(1.0), None);
        set_camera(&cam3);
        if self.show_grid {
            render::draw_grid(50.0, 2.5);
        }
        if let (Some(gpu), Some(gm)) = (&mut self.gpu, &self.gm) {
            for (mi, meshes) in &mut gpu.parts {
                if let Some(m) = self.materials.get(*mi) {
                    for mesh in meshes.iter_mut() {
                        mesh.texture = m.tex.clone();
                    }
                }
            }
            draw_gpu(gpu, &self.materials, gm, &self.light, self.cam.position());
        }
        set_default_camera();
    }

    pub fn draw_viewport_overlay(&mut self, ui: &mut Ui, r: Rect) {
        let views: Vec<String> = VIEWS.iter().map(|s| s.to_string()).collect();
        let mut v = self.cam.view;
        if ui.combo("vp.view", Rect::new(r.x + 8.0, r.y + 8.0, 120.0, 22.0), &views, &mut v) {
            self.cam.set_view(v);
        }
        let ob = Rect::new(r.x + 132.0, r.y + 8.0, 92.0, 22.0);
        if ui.button_ex("vp.ortho", ob, if self.cam.ortho { "Orthographic" } else { "Perspective" }, self.cam.ortho, true) {
            self.cam.ortho = !self.cam.ortho;
        }
        if ui.button("vp.frame", Rect::new(r.x + 228.0, r.y + 8.0, 54.0, 22.0), "Frame") {
            self.frame_tree();
        }
        if ui.button_ex("vp.grid", Rect::new(r.x + 286.0, r.y + 8.0, 44.0, 22.0), "Grid", self.show_grid, true) {
            self.show_grid = !self.show_grid;
        }
        if ui.button("vp.light", Rect::new(r.x + 334.0, r.y + 8.0, 70.0, 22.0), "Lighting...") {
            self.select(Sel::Window);
        }
        let name = self.cam.view_name();
        ui.text(&name, r.x + 10.0, r.y + 36.0, 12.0, C_TEXT_DIM);
        let s = format!(
            "Triangles: {}   Vertices: {}   Branches: {}   Leaves: {}",
            self.geo_stats.0, self.geo_stats.1, self.geo_stats.2, self.geo_stats.3
        );
        ui.record("stat", Rect::new(r.x + 10.0, r.y + r.h - 22.0, 300.0, 16.0));
        ui.text(&s, r.x + 10.0, r.y + r.h - 22.0, 12.0, C_TEXT_DIM);
        if !self.status.is_empty() && get_time() - self.status_t < 4.0 {
            let w = ui.text_w(&self.status, 12.5) + 20.0;
            let br = Rect::new(r.x + (r.w - w) * 0.5, r.y + r.h - 46.0, w, 24.0);
            draw_rectangle(br.x, br.y, br.w, br.h, Color::new(0.0, 0.0, 0.0, 0.55));
            let st = self.status.clone();
            ui.text_center(&st, br, 12.5, WHITE);
        }
        // axis gizmo
        let c = vec2(r.x + r.w - 40.0, r.y + r.h - 40.0);
        let d = self.cam.dir();
        let right = Vec3::Y.cross(d).normalize_or_zero();
        let up = d.cross(right).normalize_or_zero();
        for (ax, col, l) in [(Vec3::X, Color::new(0.9, 0.35, 0.35, 1.0), "X"), (Vec3::Y, Color::new(0.4, 0.85, 0.4, 1.0), "Y"), (Vec3::Z, Color::new(0.4, 0.55, 1.0, 1.0), "Z")] {
            let p = vec2(-ax.dot(right), -ax.dot(up)) * 22.0;
            let p = vec2(-p.x, p.y);
            draw_line(c.x, c.y, c.x + p.x, c.y + p.y, 2.0, col);
            ui.text(l, c.x + p.x * 1.25 - 3.0, c.y + p.y * 1.25 - 6.0, 11.0, col);
        }
    }

    // ------------------------------------------------------------------ dock
    pub fn draw_dock(&mut self, ui: &mut Ui, r: Rect) {
        draw_rectangle(r.x, r.y, r.w, r.h, C_PANEL);
        draw_rectangle(r.x, r.y, r.w, 26.0, C_PANEL2);
        let mut x = r.x;
        for (i, t) in TABS.iter().enumerate() {
            let w = ui.text_w(t, 13.0) + 20.0;
            let tr = Rect::new(x, r.y, w, 26.0);
            ui.record(&format!("tab:{}", t), tr);
            if i == self.tab {
                draw_rectangle(tr.x, tr.y, tr.w, tr.h, C_PANEL);
            }
            let hot = ui.hover(tr);
            ui.text_center(t, tr, 13.0, if i == self.tab || hot { WHITE } else { C_TEXT_DIM });
            if hot && ui.inp.l_pressed {
                self.tab = i;
            }
            x += w;
        }
        let tb = Rect::new(r.x, r.y + 26.0, r.w, 30.0);
        let body = Rect::new(r.x, r.y + 56.0, r.w, r.h - 56.0);
        match self.tab {
            0 => self.draw_generation(ui, tb, body),
            1 => self.draw_materials(ui, tb, body),
            _ => self.draw_meshes(ui, tb, body),
        }
    }

    fn toolbar(&mut self, ui: &mut Ui, tb: Rect, key: &str, add_items: &[&str], act_items: &[&str], randomize: bool) -> (Option<usize>, Option<usize>, bool) {
        let addk = format!("{}.add", key);
        let actk = format!("{}.actions", key);
        let ar = Rect::new(tb.x + 6.0, tb.y + 4.0, 52.0, 22.0);
        if ui.tool_button(&addk, ar, "+ Add", ui.popup_open_for(&addk)) {
            ui.open_popup(hid(&addk), ar, add_items.iter().map(|s| s.to_string()).collect(), None);
        }
        let cr = Rect::new(tb.x + 62.0, tb.y + 4.0, 68.0, 22.0);
        if ui.tool_button(&actk, cr, "Actions", ui.popup_open_for(&actk)) {
            ui.open_popup(hid(&actk), cr, act_items.iter().map(|s| s.to_string()).collect(), None);
        }
        let mut rnd = false;
        if randomize {
            rnd = ui.tool_button(&format!("{}.rand", key), Rect::new(tb.x + 134.0, tb.y + 4.0, 80.0, 22.0), "Randomize", false);
        }
        draw_line(tb.x, tb.y + tb.h, tb.x + tb.w, tb.y + tb.h, 1.0, C_LINE);
        (ui.take_popup_result(&addk), ui.take_popup_result(&actk), rnd)
    }

    fn graph_to_screen(&self, body: Rect, p: Vec2) -> Vec2 {
        let origin = vec2(body.x + body.w * 0.5, body.y + body.h - 70.0);
        origin + (p + self.graph_off) * self.graph_zoom
    }

    fn draw_generation(&mut self, ui: &mut Ui, tb: Rect, body: Rect) {
        let sel_node = if let Sel::Node(id) = self.sel { Some(id) } else { None };
        let (add, act, rnd) = self.toolbar(ui, tb, "gen", &["Trunk", "Branch", "Leaf"], &["Duplicate", "Delete", "Hide / show", "Arrange nodes", "Frame graph"], true);
        if let Some(i) = add {
            let kind = [Kind::Trunk, Kind::Branch, Kind::Leaf][i];
            let parent = sel_node.unwrap_or_else(|| {
                // default parent: Tree for trunks, newest branch-type node otherwise
                if kind == Kind::Trunk {
                    self.root_id()
                } else {
                    self.nodes.iter().rev().find(|n| n.kind.makes_spines()).map(|n| n.id).unwrap_or(self.root_id())
                }
            });
            self.add_node(kind, parent);
        }
        if let Some(i) = act {
            match (i, sel_node) {
                (0, Some(id)) => self.duplicate_node(id),
                (1, Some(id)) => self.delete_node(id),
                (2, Some(id)) => {
                    if let Some(n) = self.nodes.iter_mut().find(|n| n.id == id) {
                        n.hidden = !n.hidden;
                    }
                    self.dirty = true;
                }
                (3, _) => self.arrange(),
                (4, _) => {
                    self.graph_off = Vec2::ZERO;
                    self.graph_zoom = 1.0;
                }
                _ => self.set_status("Select a node first"),
            }
        }
        if rnd {
            self.randomize(sel_node);
        }
        // context menu result
        if let Some(i) = ui.take_popup_result("gen.ctx") {
            if let Some(id) = sel_node {
                match i {
                    0 => {
                        self.add_node(Kind::Branch, id);
                    }
                    1 => {
                        self.add_node(Kind::Leaf, id);
                    }
                    2 => self.duplicate_node(id),
                    3 => {
                        if let Some(n) = self.nodes.iter_mut().find(|n| n.id == id) {
                            n.hidden = !n.hidden;
                        }
                        self.dirty = true;
                    }
                    _ => self.delete_node(id),
                }
            }
        }

        ui.set_clip(Some(body));
        // background grid dots
        let step = 40.0 * self.graph_zoom;
        let o = self.graph_to_screen(body, Vec2::ZERO);
        let mut gx = body.x + (o.x - body.x).rem_euclid(step);
        while gx < body.x + body.w {
            let mut gy = body.y + (o.y - body.y).rem_euclid(step);
            while gy < body.y + body.h {
                draw_rectangle(gx, gy, 1.5, 1.5, Color::new(1.0, 1.0, 1.0, 0.07));
                gy += step;
            }
            gx += step;
        }
        let rad = 26.0 * self.graph_zoom;
        // links
        for n in &self.nodes {
            if let Some(pid) = n.parent {
                if let Some(p) = self.node(pid) {
                    let a = self.graph_to_screen(body, p.pos) - vec2(0.0, rad);
                    let b = self.graph_to_screen(body, n.pos) + vec2(0.0, rad);
                    let c = if sel_node == Some(n.id) { C_ORANGE } else { Color::new(1.0, 1.0, 1.0, 0.35) };
                    draw_line(a.x, a.y, b.x, b.y, 2.0, c);
                    draw_circle(a.x, a.y, 3.0, c);
                }
            }
        }
        let m = ui.mouse();
        let mut hover_node = None;
        for n in self.nodes.iter() {
            let c = self.graph_to_screen(body, n.pos);
            if c.distance(m) <= rad && body.contains(m) && !ui.blocked {
                hover_node = Some(n.id);
            }
        }
        // nodes
        let nodes = self.nodes.clone();
        for n in &nodes {
            let c = self.graph_to_screen(body, n.pos);
            let alpha = if n.hidden { 0.35 } else { 1.0 };
            let tex = self.icons.for_kind(n.kind);
            let tint = if n.kind == Kind::Trunk { Color::new(0.85, 0.75, 0.7, alpha) } else { Color::new(1.0, 1.0, 1.0, alpha) };
            draw_circle(c.x + 2.0, c.y + 3.0, rad, Color::new(0.0, 0.0, 0.0, 0.3));
            draw_texture_ex(tex, c.x - rad, c.y - rad, tint, DrawTextureParams { dest_size: Some(vec2(rad * 2.0, rad * 2.0)), ..Default::default() });
            let selected = sel_node == Some(n.id);
            if selected || hover_node == Some(n.id) {
                let rr = rad * 1.18;
                let col = if selected { C_ORANGE } else { Color::new(1.0, 1.0, 1.0, 0.45) };
                draw_texture_ex(&self.icons.ring, c.x - rr, c.y - rr, col, DrawTextureParams { dest_size: Some(vec2(rr * 2.0, rr * 2.0)), ..Default::default() });
            }
            let fs = (12.0 * self.graph_zoom.sqrt()).clamp(9.0, 15.0);
            let w = ui.text_w(&n.name, fs);
            ui.text(&n.name, c.x - w * 0.5, c.y + rad + 4.0, fs, if selected { WHITE } else { C_TEXT });
            if n.kind != Kind::Tree {
                let cnt = self.instance_count(n.id).to_string();
                let cw = ui.text_w(&cnt, 10.5) + 8.0;
                let br = Rect::new(c.x + rad * 0.55, c.y - rad * 1.05, cw, 15.0);
                draw_rectangle(br.x, br.y, br.w, br.h, Color::new(0.1, 0.1, 0.1, 0.85));
                ui.text_center(&cnt, br, 10.5, C_TEXT_DIM);
            }
            ui.record(&format!("node:{}", n.name), Rect::new(c.x - rad, c.y - rad, rad * 2.0, rad * 2.0));
        }

        // interaction
        let inp = ui.inp.clone();
        let in_body = body.contains(m) && !ui.blocked && ui.popup.is_none();
        if in_body && inp.wheel != 0.0 {
            let before = (m - self.graph_to_screen(body, Vec2::ZERO)) / self.graph_zoom;
            self.graph_zoom = (self.graph_zoom * 1.1f32.powf(inp.wheel)).clamp(0.4, 2.5);
            let after = (m - self.graph_to_screen(body, Vec2::ZERO)) / self.graph_zoom;
            self.graph_off += after - before;
        }
        if in_body && ui.active == 0 && self.graph_drag == GraphDrag::None {
            if inp.l_pressed {
                if let Some(id) = hover_node {
                    self.select(Sel::Node(id));
                    self.graph_drag = if inp.shift { GraphDrag::Link { from: id } } else { GraphDrag::Node { id, start: m, moved: false } };
                    ui.active = hid("graph");
                } else {
                    self.select(Sel::None);
                    self.graph_drag = GraphDrag::Pan;
                    ui.active = hid("graph");
                }
            } else if inp.r_pressed {
                if let Some(id) = hover_node {
                    self.select(Sel::Node(id));
                    ui.open_popup(hid("gen.ctx"), Rect::new(m.x, m.y, 10.0, 0.0), vec!["Add branch".into(), "Add leaf".into(), "Duplicate".into(), "Hide / show".into(), "Delete".into()], None);
                } else {
                    self.graph_drag = GraphDrag::Pan;
                }
            } else if inp.m_pressed {
                self.graph_drag = GraphDrag::Pan;
            }
        }
        let d = m - self.last_graph_mouse();
        match self.graph_drag {
            GraphDrag::Node { id, start, moved } => {
                if inp.l_down {
                    let mv = moved || start.distance(m) > 4.0;
                    if mv {
                        if let Some(n) = self.nodes.iter_mut().find(|n| n.id == id) {
                            n.pos += d / self.graph_zoom;
                        }
                    }
                    self.graph_drag = GraphDrag::Node { id, start, moved: mv };
                } else {
                    self.graph_drag = GraphDrag::None;
                }
            }
            GraphDrag::Link { from } => {
                if let Some(f) = self.node(from) {
                    let a = self.graph_to_screen(body, f.pos);
                    draw_line(a.x, a.y, m.x, m.y, 2.0, C_ACCENT2);
                }
                if !inp.l_down {
                    if let Some(to) = hover_node {
                        // dragging from child onto the new parent
                        self.reparent(from, to);
                    }
                    self.graph_drag = GraphDrag::None;
                }
            }
            GraphDrag::Pan => {
                if inp.l_down || inp.r_down || inp.m_down {
                    self.graph_off += d / self.graph_zoom;
                } else {
                    self.graph_drag = GraphDrag::None;
                }
            }
            GraphDrag::None => {}
        }
        self.graph_mouse = m;
        if self.nodes.len() == 1 {
            let t = "Use + Add to grow a trunk from the Tree node";
            let w = ui.text_w(t, 12.5);
            ui.text(t, body.x + (body.w - w) * 0.5, body.y + 30.0, 12.5, C_TEXT_FAINT);
        }
        ui.set_clip(None);
        let hint = "Shift+drag a node onto another to link it  •  right-click a node for more";
        ui.text_fit(hint, body.x + 8.0, body.y + body.h - 18.0, body.w - 16.0, 11.0, C_TEXT_FAINT);
    }

    fn last_graph_mouse(&self) -> Vec2 {
        self.graph_mouse
    }

    // ------------------------------------------------------------------ materials
    fn draw_materials(&mut self, ui: &mut Ui, tb: Rect, body: Rect) {
        let (add, act, _) = self.toolbar(ui, tb, "mat", &["Material (blank)", "Bark (procedural)", "Leaf (procedural)", "From image file..."], &["Duplicate", "Delete"], false);
        if let Some(i) = add {
            let mut m = match i {
                1 => Material::bark(),
                2 => Material::leaf(),
                3 => {
                    let mut m = Material::new("Image", 4);
                    m.two_sided = true;
                    if let Some(f) = crate::props::pick_image() {
                        m.name = std::path::Path::new(&f).file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or("Image".into());
                        m.file = f;
                    }
                    m
                }
                _ => Material::new("Material", 0),
            };
            m.name = format!("{} {}", m.name, self.materials.len() + 1);
            textures::refresh_material(&mut m);
            self.materials.push(m);
            self.select(Sel::Material(self.materials.len() - 1));
        }
        if let Some(i) = act {
            let cur = self.mat_cur.min(self.materials.len().saturating_sub(1));
            if i == 0 {
                let mut m = self.materials[cur].clone();
                m.name = format!("{} copy", m.name);
                self.materials.push(m);
                self.select(Sel::Material(self.materials.len() - 1));
            } else if self.materials.len() > 1 {
                self.materials.remove(cur);
                for n in &mut self.nodes {
                    if n.p.material >= cur && n.p.material > 0 {
                        n.p.material -= 1;
                    }
                    if n.p.leaf_material >= cur && n.p.leaf_material > 0 {
                        n.p.leaf_material -= 1;
                    }
                }
                self.select(Sel::None);
                self.mat_cur = 0;
                self.dirty = true;
            } else {
                self.set_status("Keep at least one material");
            }
        }
        // thumbnails
        let tile = 92.0;
        let cols = ((body.w - 12.0) / (tile + 8.0)).floor().max(1.0) as usize;
        let grid_h = ((self.materials.len() + cols - 1) / cols) as f32 * (tile + 26.0) + 10.0;
        for (i, m) in self.materials.iter().enumerate() {
            let x = body.x + 10.0 + (i % cols) as f32 * (tile + 8.0);
            let y = body.y + 10.0 + (i / cols) as f32 * (tile + 26.0);
            let r = Rect::new(x, y, tile, tile);
            checker(r, 8.0);
            if let Some(t) = &m.tex {
                draw_texture_ex(t, r.x, r.y, Color::new(m.color[0], m.color[1], m.color[2], 1.0), DrawTextureParams { dest_size: Some(vec2(tile, tile)), ..Default::default() });
            }
            let selected = self.sel == Sel::Material(i);
            draw_rectangle_lines(r.x - 1.0, r.y - 1.0, r.w + 2.0, r.h + 2.0, if selected { 2.0 } else { 1.0 }, if selected { C_ORANGE } else { C_LINE });
            let name = m.name.clone();
            ui.text_fit(&name, x, y + tile + 4.0, tile, 12.0, if selected { WHITE } else { C_TEXT_DIM });
            let hit = Rect::new(x, y, tile, tile + 20.0);
            ui.record(&format!("mat:{}", m.name), hit);
            if ui.clicked(hit) {
                self.sel = Sel::Material(i);
                self.mat_cur = i;
                self.prop_scroll = 0.0;
                self.dirty = true;
            }
        }
        // preview
        let py = body.y + grid_h + 6.0;
        let ph = (body.y + body.h - py - 10.0).max(60.0);
        let side = ph.min(body.w - 20.0);
        let pr = Rect::new(body.x + (body.w - side) * 0.5, py + 28.0, side, side - 28.0);
        let cur = self.mat_cur.min(self.materials.len().saturating_sub(1));
        let title = format!("Preview: {}", self.materials.get(cur).map(|m| m.name.clone()).unwrap_or_default());
        ui.text(&title, body.x + 10.0, py + 4.0, 13.0, C_TEXT);
        if ui.button_ex("mat.sphere", Rect::new(body.x + body.w - 130.0, py, 58.0, 22.0), "Sphere", self.preview_sphere, true) {
            self.preview_sphere = true;
        }
        if ui.button_ex("mat.card", Rect::new(body.x + body.w - 68.0, py, 58.0, 22.0), "Card", !self.preview_sphere, true) {
            self.preview_sphere = false;
        }
        ui.record("matpreview", pr);
        if pr.h > 40.0 {
            checker(pr, 12.0);
            if let Some(rt) = &self.preview_rt {
                draw_texture_ex(&rt.texture, pr.x, pr.y, WHITE, DrawTextureParams { dest_size: Some(vec2(pr.w, pr.h)), flip_y: true, ..Default::default() });
            }
            draw_rectangle_lines(pr.x, pr.y, pr.w, pr.h, 1.0, C_LINE);
        }
        self.preview_aspect = pr.w / pr.h.max(1.0);
    }

    /// Render the material preview (sphere or card) into its picture. Call before the UI pass.
    pub fn render_preview(&mut self) {
        if self.tab != 1 {
            return;
        }
        let gm = match &self.gm {
            Some(g) => g,
            None => return,
        };
        let rt = self.preview_rt.get_or_insert_with(|| {
            let r = render_target_ex(512, 512, RenderTargetParams { depth: true, ..Default::default() });
            r.texture.set_filter(FilterMode::Linear);
            r
        });
        let cur = self.mat_cur.min(self.materials.len().saturating_sub(1));
        let m = match self.materials.get(cur) {
            Some(m) => m,
            None => return,
        };
        let t = get_time() as f32 * 0.4;
        let cam = Cam { yaw: t, pitch: 0.25, dist: 3.6, target: Vec3::ZERO, ortho: false, view: 0, fov: 40.0 };
        let mut c3 = cam.camera3d(None, self.preview_aspect.max(0.2), Some(rt.clone()));
        c3.viewport = None;
        set_camera(&c3);
        clear_background(Color::new(0.0, 0.0, 0.0, 0.0));
        gl_use_material(gm);
        render::apply_material(gm, m, &self.light, cam.position());
        let src = if self.preview_sphere { &self.sphere } else { &self.card };
        for mesh in src {
            let tmp = Mesh { vertices: mesh.vertices.clone(), indices: mesh.indices.clone(), texture: m.tex.clone() };
            draw_mesh(&tmp);
        }
        unsafe { get_internal_gl() }.flush();
        gl_use_default_material();
        set_default_camera();
    }

    // ------------------------------------------------------------------ meshes
    fn draw_meshes(&mut self, ui: &mut Ui, tb: Rect, body: Rect) {
        let (add, act, _) = self.toolbar(ui, tb, "mesh", &["Card mesh", "Cutout from reference material"], &["Duplicate", "Delete"], false);
        if let Some(i) = add {
            let mut m = LeafMesh::card(&format!("Mesh {}", self.meshes.len() + 1));
            m.ref_material = self.mat_cur.min(self.materials.len().saturating_sub(1));
            if i == 1 {
                if let Some(img) = self.materials.get(m.ref_material).and_then(|x| x.adjusted.clone()) {
                    m.lods[0] = textures::auto_cutout(&img, m.auto_points as usize, m.threshold, m.margin);
                }
            }
            self.meshes.push(m);
            self.mesh_lod = 0;
            self.select(Sel::Mesh(self.meshes.len() - 1));
        }
        if let Some(i) = act {
            if !self.meshes.is_empty() {
                let cur = self.mesh_cur.min(self.meshes.len() - 1);
                if i == 0 {
                    let mut m = self.meshes[cur].clone();
                    m.name = format!("{} copy", m.name);
                    self.meshes.push(m);
                    self.select(Sel::Mesh(self.meshes.len() - 1));
                } else {
                    self.meshes.remove(cur);
                    for n in &mut self.nodes {
                        if n.p.leaf_mesh == cur + 1 {
                            n.p.leaf_mesh = 0;
                        } else if n.p.leaf_mesh > cur + 1 {
                            n.p.leaf_mesh -= 1;
                        }
                    }
                    self.mesh_cur = 0;
                    self.select(Sel::None);
                    self.dirty = true;
                }
            }
        }
        // mesh list
        let tile = 64.0;
        let mut x = body.x + 10.0;
        let y = body.y + 8.0;
        for i in 0..self.meshes.len() {
            let r = Rect::new(x, y, tile, tile);
            checker(r, 8.0);
            let m = &self.meshes[i];
            if let Some(t) = self.materials.get(m.ref_material).and_then(|mm| mm.tex.as_ref()) {
                draw_texture_ex(t, r.x, r.y, WHITE, DrawTextureParams { dest_size: Some(vec2(tile, tile)), ..Default::default() });
            }
            let pts: Vec<Vec2> = m.lods[0].iter().map(|p| vec2(r.x + p.x * tile, r.y + p.y * tile)).collect();
            for k in 0..pts.len() {
                let a = pts[k];
                let b = pts[(k + 1) % pts.len()];
                draw_line(a.x, a.y, b.x, b.y, 1.0, C_ORANGE);
            }
            let selected = self.mesh_cur == i;
            draw_rectangle_lines(r.x - 1.0, r.y - 1.0, r.w + 2.0, r.h + 2.0, if selected { 2.0 } else { 1.0 }, if selected { C_ORANGE } else { C_LINE });
            let name = m.name.clone();
            ui.text_fit(&name, x, y + tile + 3.0, tile + 20.0, 11.5, if selected { WHITE } else { C_TEXT_DIM });
            let hit = Rect::new(x, y, tile, tile + 18.0);
            ui.record(&format!("mesh:{}", name), hit);
            if ui.clicked(hit) {
                self.mesh_lod = 0;
                self.select(Sel::Mesh(i));
            }
            x += tile + 26.0;
        }
        if self.meshes.is_empty() {
            ui.text("No meshes. Use + Add to make one.", body.x + 12.0, body.y + 30.0, 12.5, C_TEXT_FAINT);
            return;
        }
        let cur = self.mesh_cur.min(self.meshes.len() - 1);
        self.mesh_cur = cur;
        // LOD buttons
        let ly = y + tile + 26.0;
        ui.text("Cutout editor", body.x + 10.0, ly + 3.0, 13.0, C_TEXT);
        let nl = self.meshes[cur].lods.len();
        self.mesh_lod = self.mesh_lod.min(nl - 1);
        for l in 0..nl {
            let br = Rect::new(body.x + body.w - 10.0 - (nl - l) as f32 * 50.0, ly, 46.0, 22.0);
            if ui.button_ex(&format!("mesh.lod{}", l), br, &format!("LOD{}", l), self.mesh_lod == l, true) {
                self.mesh_lod = l;
            }
        }
        // canvas
        let top = ly + 30.0;
        let avail = Rect::new(body.x + 10.0, top, body.w - 20.0, body.y + body.h - top - 40.0);
        let side = avail.w.min(avail.h).max(40.0);
        let cv = Rect::new(avail.x + (avail.w - side) * 0.5, avail.y, side, side);
        ui.record("meshcanvas", cv);
        draw_rectangle(cv.x - 1.0, cv.y - 1.0, cv.w + 2.0, cv.h + 2.0, C_BG);
        checker(cv, 16.0);
        let refm = self.meshes[cur].ref_material;
        if let Some(t) = self.materials.get(refm).and_then(|m| m.tex.as_ref()) {
            draw_texture_ex(t, cv.x, cv.y, WHITE, DrawTextureParams { dest_size: Some(vec2(cv.w, cv.h)), ..Default::default() });
        }
        let to_s = |p: Vec2| vec2(cv.x + p.x * cv.w, cv.y + p.y * cv.h);
        let to_uv = |s: Vec2| vec2((s.x - cv.x) / cv.w, (s.y - cv.y) / cv.h);
        let lod = self.mesh_lod;
        let poly = self.meshes[cur].lods[lod].clone();
        // triangulation preview
        for tri in textures::triangulate(&poly) {
            let a = to_s(poly[tri[0]]);
            let b = to_s(poly[tri[1]]);
            let c = to_s(poly[tri[2]]);
            draw_triangle(a, b, c, Color::new(0.85, 0.59, 0.28, 0.10));
            draw_line(a.x, a.y, b.x, b.y, 1.0, Color::new(1.0, 1.0, 1.0, 0.15));
            draw_line(b.x, b.y, c.x, c.y, 1.0, Color::new(1.0, 1.0, 1.0, 0.15));
        }
        for k in 0..poly.len() {
            let a = to_s(poly[k]);
            let b = to_s(poly[(k + 1) % poly.len()]);
            draw_line(a.x, a.y, b.x, b.y, 2.0, C_ORANGE);
        }
        let m = ui.mouse();
        let mut hover_pt: Option<i32> = None;
        let anc = to_s(self.meshes[cur].anchor);
        if anc.distance(m) < 9.0 {
            hover_pt = Some(-1);
        }
        for (k, p) in poly.iter().enumerate() {
            let s = to_s(*p);
            if s.distance(m) < 7.0 {
                hover_pt = Some(k as i32);
            }
        }
        for (k, p) in poly.iter().enumerate() {
            let s = to_s(*p);
            let hot = hover_pt == Some(k as i32) || self.mesh_drag == Some(k as i32);
            draw_rectangle(s.x - 4.0, s.y - 4.0, 8.0, 8.0, if hot { WHITE } else { C_ORANGE });
            draw_rectangle_lines(s.x - 4.0, s.y - 4.0, 8.0, 8.0, 1.0, Color::new(0.0, 0.0, 0.0, 0.6));
        }
        // anchor (attachment point)
        draw_circle_lines(anc.x, anc.y, 7.0, 2.0, Color::new(0.3, 0.95, 0.4, 1.0));
        draw_line(anc.x - 11.0, anc.y, anc.x + 11.0, anc.y, 1.0, Color::new(0.3, 0.95, 0.4, 1.0));
        draw_line(anc.x, anc.y - 11.0, anc.x, anc.y + 11.0, 1.0, Color::new(0.3, 0.95, 0.4, 1.0));
        ui.text("anchor", anc.x + 9.0, anc.y + 4.0, 10.5, Color::new(0.3, 0.95, 0.4, 1.0));

        let inp = ui.inp.clone();
        let over = cv.contains(m) && !ui.blocked && ui.popup.is_none();
        let mut changed = false;
        if over && ui.active == 0 {
            if inp.l_double && hover_pt.is_none() {
                // insert a point on the nearest edge
                let uv = to_uv(m);
                let mut best = (f32::MAX, 0usize);
                for k in 0..poly.len() {
                    let a = poly[k];
                    let b = poly[(k + 1) % poly.len()];
                    let ab = b - a;
                    let t = ((uv - a).dot(ab) / ab.length_squared().max(1e-9)).clamp(0.0, 1.0);
                    let d = (a + ab * t).distance(uv);
                    if d < best.0 {
                        best = (d, k);
                    }
                }
                self.meshes[cur].lods[lod].insert(best.1 + 1, uv);
                changed = true;
            } else if inp.l_pressed {
                if let Some(h) = hover_pt {
                    self.mesh_drag = Some(h);
                    ui.active = hid("meshcanvas");
                }
            } else if inp.r_pressed {
                if let Some(h) = hover_pt {
                    if h >= 0 && poly.len() > 3 {
                        self.meshes[cur].lods[lod].remove(h as usize);
                        changed = true;
                    }
                }
            }
        }
        if let Some(h) = self.mesh_drag {
            if inp.l_down {
                let uv = to_uv(m);
                let uv = vec2(uv.x.clamp(-0.1, 1.1), uv.y.clamp(-0.1, 1.1));
                if h < 0 {
                    self.meshes[cur].anchor = vec2(uv.x.clamp(0.0, 1.0), uv.y.clamp(0.0, 1.0));
                } else if (h as usize) < self.meshes[cur].lods[lod].len() {
                    self.meshes[cur].lods[lod][h as usize] = uv;
                }
                changed = true;
            } else {
                self.mesh_drag = None;
            }
        }
        if changed {
            self.dirty = true;
            if self.sel != Sel::Mesh(cur) {
                self.sel = Sel::Mesh(cur);
            }
        }
        let tris = textures::triangulate(&self.meshes[cur].lods[lod]).len();
        let info = format!("{} points, {} triangles", self.meshes[cur].lods[lod].len(), tris);
        ui.text(&info, cv.x, cv.y + cv.h + 6.0, 11.5, C_TEXT_DIM);
        ui.text_fit("Drag points or the green anchor • double-click an edge to add • right-click a point to remove", body.x + 10.0, body.y + body.h - 18.0, body.w - 20.0, 11.0, C_TEXT_FAINT);
    }
}

fn draw_gpu(gpu: &GpuTree, mats: &[Material], gm: &macroquad::material::Material, light: &Lighting, cam_pos: Vec3) {
    gl_use_material(gm);
    for (mi, meshes) in &gpu.parts {
        let fallback = Material::new("?", 0);
        let m = mats.get(*mi).unwrap_or(&fallback);
        render::apply_material(gm, m, light, cam_pos);
        for mesh in meshes {
            draw_mesh(mesh);
        }
        unsafe { get_internal_gl() }.flush();
    }
    gl_use_default_material();
}

toolUseResult.content:
//! Application state and the dock panels (Generation graph, Materials, Meshes) and viewport.
use crate::gen::{self, GenCtx};
use crate::model::*;
use crate::render::{self, Cam, GpuTree, Lighting, VIEWS};
use crate::textures;
use crate::ui::*;
use macroquad::prelude::*;
use std::collections::{HashMap, HashSet};

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Sel {
    None,
    Node(u32),
    Material(usize),
    Mesh(usize),
    Window,
}

pub const TABS: [&str; 3] = ["Generation", "Materials", "Meshes"];

pub struct Icons {
    pub tree: Texture2D,
    pub branch: Texture2D,
    pub leaf: Texture2D,
    pub ring: Texture2D,
}

impl Icons {
    pub fn load() -> Self {
        let l = |b: &[u8]| {
            let t = Texture2D::from_file_with_format(b, Some(ImageFormat::Png));
            t.set_filter(FilterMode::Linear);
            t
        };
        Icons {
            tree: l(include_bytes!("../assets/icons/generator_tree.png")),
            branch: l(include_bytes!("../assets/icons/generator_branch.png")),
            leaf: l(include_bytes!("../assets/icons/generator_leaf.png")),
            ring: l(include_bytes!("../assets/icons/generator_border.png")),
        }
    }
    fn for_kind(&self, k: Kind) -> &Texture2D {
        match k {
            Kind::Tree => &self.tree,
            Kind::Trunk | Kind::Branch => &self.branch,
            Kind::Leaf => &self.leaf,
        }
    }
}

#[derive(Clone, Copy, PartialEq)]
enum GraphDrag {
    None,
    Node { id: u32, start: Vec2, moved: bool },
    Link { from: u32 },
    Pan,
}

#[derive(Clone, Copy, PartialEq)]
enum VpDrag {
    None,
    Orbit,
    Pan,
    Zoom,
}

pub struct App {
    pub nodes: Vec<Node>,
    pub next_id: u32,
    pub materials: Vec<Material>,
    pub meshes: Vec<LeafMesh>,
    pub sel: Sel,
    pub tab: usize,
    pub cam: Cam,
    pub light: Lighting,
    pub show_grid: bool,
    pub highlight: bool,
    pub dirty: bool,
    pub gpu: Option<GpuTree>,
    pub geo_stats: (usize, usize, usize, usize),
    pub per_node: HashMap<u32, usize>,
    pub bounds: (Vec3, Vec3),
    pub prop_scroll: f32,
    pub closed_groups: HashSet<String>,
    pub graph_off: Vec2,
    pub graph_zoom: f32,
    graph_drag: GraphDrag,
    vp_drag: VpDrag,
    last_mouse: Vec2,
    pub mesh_cur: usize,
    pub mesh_lod: usize,
    mesh_drag: Option<i32>,
    pub mat_cur: usize,
    pub preview_sphere: bool,
    pub preview_rt: Option<RenderTarget>,
    pub status: String,
    pub status_t: f64,
    pub gm: Option<macroquad::material::Material>,
    pub icons: Icons,
    pub viewport: Rect,
    pub regen_count: usize,
    sphere: Vec<Mesh>,
    card: Vec<Mesh>,
}

impl App {
    pub fn new() -> Self {
        let gm = match render::make_material() {
            Ok(m) => Some(m),
            Err(e) => {
                eprintln!("shader error: {}", e);
                None
            }
        };
        let mk = |v: Vec<(Vec<macroquad::models::Vertex>, Vec<u16>)>| v.into_iter().map(|(a, b)| Mesh { vertices: a, indices: b, texture: None }).collect::<Vec<_>>();
        let mut app = App {
            nodes: vec![],
            next_id: 1,
            materials: vec![],
            meshes: vec![],
            sel: Sel::None,
            tab: 0,
            cam: Cam::new(),
            light: Lighting { azimuth: 35.0, elevation: 50.0, unlit: false },
            show_grid: true,
            highlight: true,
            dirty: true,
            gpu: None,
            geo_stats: (0, 0, 0, 0),
            per_node: HashMap::new(),
            bounds: (Vec3::ZERO, Vec3::ONE),
            prop_scroll: 0.0,
            closed_groups: HashSet::new(),
            graph_off: Vec2::ZERO,
            graph_zoom: 1.0,
            graph_drag: GraphDrag::None,
            vp_drag: VpDrag::None,
            last_mouse: Vec2::ZERO,
            mesh_cur: 0,
            mesh_lod: 0,
            mesh_drag: None,
            mat_cur: 0,
            preview_sphere: true,
            preview_rt: None,
            status: String::new(),
            status_t: 0.0,
            gm,
            icons: Icons::load(),
            viewport: Rect::new(0.0, 0.0, 1.0, 1.0),
            regen_count: 0,
            sphere: mk(render::sphere_mesh(1.0)),
            card: mk(render::card_mesh(1.0)),
        };
        app.reset_library();
        app.new_tree();
        // starting graph: one of each building block, all on their default settings
        let root = app.root_id();
        let trunk = app.add_node(Kind::Trunk, root);
        let br = app.add_node(Kind::Branch, trunk);
        app.add_node(Kind::Leaf, br);
        app.select(Sel::None);
        app.regenerate();
        app.frame_tree();
        app
    }

    fn reset_library(&mut self) {
        self.materials = vec![Material::bark(), Material::leaf()];
        for m in &mut self.materials {
            textures::refresh_material(m);
        }
        let mut cut = LeafMesh::card("Leaf cutout");
        if let Some(img) = &self.materials[1].adjusted {
            cut.lods[0] = textures::auto_cutout(img, cut.auto_points as usize, cut.threshold, cut.margin);
            let l1 = textures::reduce_outline(cut.lods[0].clone(), 5);
            cut.lods.push(l1);
        }
        self.meshes = vec![cut];
    }

    pub fn set_status(&mut self, s: &str) {
        self.status = s.to_string();
        self.status_t = get_time();
    }

    pub fn node(&self, id: u32) -> Option<&Node> {
        self.nodes.iter().find(|n| n.id == id)
    }
    pub fn root_id(&self) -> u32 {
        self.nodes.iter().find(|n| n.kind == Kind::Tree).map(|n| n.id).unwrap_or(0)
    }
    pub fn instance_count(&self, id: u32) -> usize {
        *self.per_node.get(&id).unwrap_or(&0)
    }

    pub fn new_tree(&mut self) {
        self.nodes.clear();
        self.next_id = 1;
        let id = self.next_id;
        self.next_id += 1;
        self.nodes.push(Node { id, kind: Kind::Tree, name: "Tree".into(), parent: None, pos: vec2(0.0, 0.0), p: Params::new(Kind::Tree), hidden: false });
        self.sel = Sel::None;
        self.dirty = true;
        self.graph_off = Vec2::ZERO;
    }

    pub fn select(&mut self, s: Sel) {
        if self.sel != s {
            self.sel = s;
            self.prop_scroll = 0.0;
            self.dirty = true;
        }
        if let Sel::Material(i) = s {
            self.mat_cur = i;
        }
        if let Sel::Mesh(i) = s {
            self.mesh_cur = i;
        }
    }

    pub fn add_node(&mut self, kind: Kind, parent: u32) -> u32 {
        let parent = match self.node(parent) {
            Some(p) if p.kind.can_parent() && !(kind == Kind::Trunk && p.kind == Kind::Leaf) => parent,
            _ => self.root_id(),
        };
        let pp = self.node(parent).map(|n| n.pos).unwrap_or(Vec2::ZERO);
        let siblings = self.nodes.iter().filter(|n| n.parent == Some(parent)).count();
        let id = self.next_id;
        self.next_id += 1;
        let same = self.nodes.iter().filter(|n| n.kind == kind).count();
        let name = if same == 0 { kind.label().to_string() } else { format!("{} {}", kind.label(), same + 1) };
        let mut p = Params::new(kind);
        p.seed += id as i32 * 13;
        let x = pp.x + if siblings == 0 { 0.0 } else { (siblings as f32 + 1.0) / 2.0 * 90.0 * if siblings % 2 == 1 { 1.0 } else { -1.0 } };
        self.nodes.push(Node { id, kind, name, parent: Some(parent), pos: vec2(x, pp.y - 100.0), p, hidden: false });
        self.select(Sel::Node(id));
        self.dirty = true;
        id
    }

    fn descendants(&self, id: u32) -> Vec<u32> {
        let mut out = vec![id];
        let mut i = 0;
        while i < out.len() {
            let cur = out[i];
            for n in &self.nodes {
                if n.parent == Some(cur) {
                    out.push(n.id);
                }
            }
            i += 1;
        }
        out
    }

    pub fn delete_node(&mut self, id: u32) {
        if self.node(id).map(|n| n.kind == Kind::Tree).unwrap_or(true) {
            self.set_status("The Tree node can't be deleted");
            return;
        }
        let gone = self.descendants(id);
        self.nodes.retain(|n| !gone.contains(&n.id));
        self.select(Sel::None);
        self.dirty = true;
    }

    pub fn duplicate_node(&mut self, id: u32) {
        let src = match self.node(id) {
            Some(n) if n.kind != Kind::Tree => n.clone(),
            _ => return,
        };
        let nid = self.next_id;
        self.next_id += 1;
        let mut n = src.clone();
        n.id = nid;
        n.name = format!("{} copy", src.name);
        n.pos += vec2(80.0, 0.0);
        n.p.seed += 97;
        self.nodes.push(n);
        self.select(Sel::Node(nid));
        self.dirty = true;
    }

    pub fn randomize(&mut self, id: Option<u32>) {
        for n in &mut self.nodes {
            if id.map(|i| i == n.id).unwrap_or(true) {
                n.p.seed = macroquad::rand::gen_range(0, 9999);
            }
        }
        self.dirty = true;
    }

    pub fn arrange(&mut self) {
        let root = self.root_id();
        let mut x_cursor = 0.0f32;
        fn place(app: &mut App, id: u32, depth: i32, x: &mut f32) -> f32 {
            let kids: Vec<u32> = app.nodes.iter().filter(|n| n.parent == Some(id)).map(|n| n.id).collect();
            let px = if kids.is_empty() {
                let v = *x;
                *x += 90.0;
                v
            } else {
                let xs: Vec<f32> = kids.iter().map(|k| place(app, *k, depth + 1, x)).collect();
                (xs[0] + xs[xs.len() - 1]) * 0.5
            };
            if let Some(n) = app.nodes.iter_mut().find(|n| n.id == id) {
                n.pos = vec2(px, -(depth as f32) * 100.0);
            }
            px
        }
        let rx = place(self, root, 0, &mut x_cursor);
        for n in &mut self.nodes {
            n.pos.x -= rx;
        }
        self.graph_off = Vec2::ZERO;
    }

    fn reparent(&mut self, child: u32, parent: u32) {
        if child == parent {
            return;
        }
        let ok_parent = self.node(parent).map(|p| p.kind.can_parent()).unwrap_or(false);
        let ck = self.node(child).map(|c| c.kind);
        if !ok_parent || ck == Some(Kind::Tree) || self.descendants(child).contains(&parent) {
            self.set_status("Can't link those two nodes");
            return;
        }
        if let Some(c) = self.nodes.iter_mut().find(|n| n.id == child) {
            c.parent = Some(parent);
        }
        self.dirty = true;
        self.set_status("Linked");
    }

    pub fn regenerate(&mut self) {
        for m in &mut self.materials {
            textures::refresh_material(m);
        }
        let selected = if let Sel::Node(id) = self.sel { Some(id) } else { None };
        let ctx = GenCtx { nodes: &self.nodes, materials: &self.materials, meshes: &self.meshes, selected, highlight: self.highlight };
        let geo = gen::generate(&ctx);
        self.geo_stats = (geo.tris, geo.verts, geo.spines, geo.leaves);
        self.per_node = geo.per_node.clone();
        self.bounds = (geo.bmin, geo.bmax);
        self.gpu = Some(render::upload(&geo));
        self.dirty = false;
        self.regen_count += 1;
    }

    pub fn frame_tree(&mut self) {
        let (a, b) = self.bounds;
        let b2 = vec3(b.x, b.y.max(a.y + 1.0), b.z);
        self.cam.frame(vec3(a.x, a.y.min(0.0), a.z), b2);
    }

    // ------------------------------------------------------------------ viewport
    pub fn viewport_input(&mut self, ui: &mut Ui, r: Rect) {
        let m = ui.mouse();
        let over = r.contains(m) && !ui.blocked && ui.popup.is_none();
        let inp = ui.inp.clone();
        if over && inp.wheel != 0.0 {
            self.cam.zoom(inp.wheel);
        }
        if over && ui.active == 0 && self.vp_drag == VpDrag::None {
            if inp.l_pressed {
                self.vp_drag = if inp.shift || inp.alt && inp.ctrl { VpDrag::Pan } else { VpDrag::Orbit };
                self.last_mouse = m;
                ui.active = hid("viewport");
            } else if inp.m_pressed {
                self.vp_drag = VpDrag::Pan;
                self.last_mouse = m;
            } else if inp.r_pressed {
                self.vp_drag = VpDrag::Zoom;
                self.last_mouse = m;
            }
        }
        let d = m - self.last_mouse;
        match self.vp_drag {
            VpDrag::Orbit => {
                if inp.l_down {
                    self.cam.orbit(d.x, d.y);
                } else {
                    self.vp_drag = VpDrag::None;
                }
            }
            VpDrag::Pan => {
                if inp.l_down || inp.m_down {
                    self.cam.pan(-d.x, d.y, r.h);
                } else {
                    self.vp_drag = VpDrag::None;
                }
            }
            VpDrag::Zoom => {
                if inp.r_down {
                    self.cam.zoom(-d.y * 0.03);
                } else {
                    self.vp_drag = VpDrag::None;
                }
            }
            VpDrag::None => {}
        }
        self.last_mouse = m;
    }

    pub fn draw_viewport_3d(&mut self, r: Rect, scale: f32) {
        // background gradient
        let top = Color::new(0.26, 0.27, 0.29, 1.0);
        let bot = Color::new(0.14, 0.14, 0.15, 1.0);
        let steps = 24;
        for i in 0..steps {
            let t = i as f32 / steps as f32;
            let c = Color::new(top.r + (bot.r - top.r) * t, top.g + (bot.g - top.g) * t, top.b + (bot.b - top.b) * t, 1.0);
            draw_rectangle(r.x, r.y + r.h * t, r.w, r.h / steps as f32 + 1.0, c);
        }
        let sh = screen_height();
        let vp = ((r.x * scale) as i32, (sh - (r.y + r.h) * scale) as i32, (r.w * scale) as i32, (r.h * scale) as i32);
        let cam3 = self.cam.camera3d(Some(vp), r.w / r.h.max(1.0), None);
        set_camera(&cam3);
        if self.show_grid {
            render::draw_grid(50.0, 2.5);
        }
        if let (Some(gpu), Some(gm)) = (&mut self.gpu, &self.gm) {
            for (mi, meshes) in &mut gpu.parts {
                if let Some(m) = self.materials.get(*mi) {
                    for mesh in meshes.iter_mut() {
                        mesh.texture = m.tex.clone();
                    }
                }
            }
            draw_gpu(gpu, &self.materials, gm, &self.light, self.cam.position());
        }
        set_default_camera();
    }

    pub fn draw_viewport_overlay(&mut self, ui: &mut Ui, r: Rect) {
        let views: Vec<String> = VIEWS.iter().map(|s| s.to_string()).collect();
        let mut v = self.cam.view;
        if ui.combo("vp.view", Rect::new(r.x + 8.0, r.y + 8.0, 120.0, 22.0), &views, &mut v) {
            self.cam.set_view(v);
        }
        let ob = Rect::new(r.x + 132.0, r.y + 8.0, 92.0, 22.0);
        if ui.button_ex("vp.ortho", ob, if self.cam.ortho { "Orthographic" } else { "Perspective" }, self.cam.ortho, true) {
            self.cam.ortho = !self.cam.ortho;
        }
        if ui.button("vp.frame", Rect::new(r.x + 228.0, r.y + 8.0, 54.0, 22.0), "Frame") {
            self.frame_tree();
        }
        if ui.button_ex("vp.grid", Rect::new(r.x + 286.0, r.y + 8.0, 44.0, 22.0), "Grid", self.show_grid, true) {
            self.show_grid = !self.show_grid;
        }
        if ui.button("vp.light", Rect::new(r.x + 334.0, r.y + 8.0, 70.0, 22.0), "Lighting...") {
            self.select(Sel::Window);
        }
        let name = self.cam.view_name();
        ui.text(&name, r.x + 10.0, r.y + 36.0, 12.0, C_TEXT_DIM);
        let s = format!(
            "Triangles: {}   Vertices: {}   Branches: {}   Leaves: {}",
            self.geo_stats.0, self.geo_stats.1, self.geo_stats.2, self.geo_stats.3
        );
        ui.record("stat", Rect::new(r.x + 10.0, r.y + r.h - 22.0, 300.0, 16.0));
        ui.text(&s, r.x + 10.0, r.y + r.h - 22.0, 12.0, C_TEXT_DIM);
        if !self.status.is_empty() && get_time() - self.status_t < 4.0 {
            let w = ui.text_w(&self.status, 12.5) + 20.0;
            let br = Rect::new(r.x + (r.w - w) * 0.5, r.y + r.h - 46.0, w, 24.0);
            draw_rectangle(br.x, br.y, br.w, br.h, Color::new(0.0, 0.0, 0.0, 0.55));
            let st = self.status.clone();
            ui.text_center(&st, br, 12.5, WHITE);
        }
        // axis gizmo
        let c = vec2(r.x + r.w - 40.0, r.y + r.h - 40.0);
        let d = self.cam.dir();
        let right = Vec3::Y.cross(d).normalize_or_zero();
        let up = d.cross(right).normalize_or_zero();
        for (ax, col, l) in [(Vec3::X, Color::new(0.9, 0.35, 0.35, 1.0), "X"), (Vec3::Y, Color::new(0.4, 0.85, 0.4, 1.0), "Y"), (Vec3::Z, Color::new(0.4, 0.55, 1.0, 1.0), "Z")] {
            let p = vec2(-ax.dot(right), -ax.dot(up)) * 22.0;
            let p = vec2(-p.x, p.y);
            draw_line(c.x, c.y, c.x + p.x, c.y + p.y, 2.0, col);
            ui.text(l, c.x + p.x * 1.25 - 3.0, c.y + p.y * 1.25 - 6.0, 11.0, col);
        }
    }

    // ------------------------------------------------------------------ dock
    pub fn draw_dock(&mut self, ui: &mut Ui, r: Rect) {
        draw_rectangle(r.x, r.y, r.w, r.h, C_PANEL);
        draw_rectangle(r.x, r.y, r.w, 26.0, C_PANEL2);
        let mut x = r.x;
        for (i, t) in TABS.iter().enumerate() {
            let w = ui.text_w(t, 13.0) + 20.0;
            let tr = Rect::new(x, r.y, w, 26.0);
            ui.record(&format!("tab:{}", t), tr);
            if i == self.tab {
                draw_rectangle(tr.x, tr.y, tr.w, tr.h, C_PANEL);
            }
            let hot = ui.hover(tr);
            ui.text_center(t, tr, 13.0, if i == self.tab || hot { WHITE } else { C_TEXT_DIM });
            if hot && ui.inp.l_pressed {
                self.tab = i;
            }
            x += w;
        }
        let tb = Rect::new(r.x, r.y + 26.0, r.w, 30.0);
        let body = Rect::new(r.x, r.y + 56.0, r.w, r.h - 56.0);
        match self.tab {
            0 => self.draw_generation(ui, tb, body),
            1 => self.draw_materials(ui, tb, body),
            _ => self.draw_meshes(ui, tb, body),
        }
    }

    fn toolbar(&mut self, ui: &mut Ui, tb: Rect, key: &str, add_items: &[&str], act_items: &[&str], randomize: bool) -> (Option<usize>, Option<usize>, bool) {
        let addk = format!("{}.add", key);
        let actk = format!("{}.actions", key);
        let ar = Rect::new(tb.x + 6.0, tb.y + 4.0, 52.0, 22.0);
        if ui.tool_button(&addk, ar, "+ Add", ui.popup_open_for(&addk)) {
            ui.open_popup(hid(&addk), ar, add_items.iter().map(|s| s.to_string()).collect(), None);
        }
        let cr = Rect::new(tb.x + 62.0, tb.y + 4.0, 68.0, 22.0);
        if ui.tool_button(&actk, cr, "Actions", ui.popup_open_for(&actk)) {
            ui.open_popup(hid(&actk), cr, act_items.iter().map(|s| s.to_string()).collect(), None);
        }
        let mut rnd = false;
        if randomize {
            rnd = ui.tool_button(&format!("{}.rand", key), Rect::new(tb.x + 134.0, tb.y + 4.0, 80.0, 22.0), "Randomize", false);
        }
        draw_line(tb.x, tb.y + tb.h, tb.x + tb.w, tb.y + tb.h, 1.0, C_LINE);
        (ui.take_popup_result(&addk), ui.take_popup_result(&actk), rnd)
    }

    fn graph_to_screen(&self, body: Rect, p: Vec2) -> Vec2 {
        let origin = vec2(body.x + body.w * 0.5, body.y + body.h - 70.0);
        origin + (p + self.graph_off) * self.graph_zoom
    }

    fn draw_generation(&mut self, ui: &mut Ui, tb: Rect, body: Rect) {
        let sel_node = if let Sel::Node(id) = self.sel { Some(id) } else { None };
        let (add, act, rnd) = self.toolbar(ui, tb, "gen", &["Trunk", "Branch", "Leaf"], &["Duplicate", "Delete", "Hide / show", "Arrange nodes", "Frame graph"], true);
        if let Some(i) = add {
            let kind = [Kind::Trunk, Kind::Branch, Kind::Leaf][i];
            let parent = sel_node.unwrap_or_else(|| {
                // default parent: Tree for trunks, newest branch-type node otherwise
                if kind == Kind::Trunk {
                    self.root_id()
                } else {
                    self.nodes.iter().rev().find(|n| n.kind.makes_spines()).map(|n| n.id).unwrap_or(self.root_id())
                }
            });
            self.add_node(kind, parent);
        }
        if let Some(i) = act {
            match (i, sel_node) {
                (0, Some(id)) => self.duplicate_node(id),
                (1, Some(id)) => self.delete_node(id),
                (2, Some(id)) => {
                    if let Some(n) = self.nodes.iter_mut().find(|n| n.id == id) {
                        n.hidden = !n.hidden;
                    }
                    self.dirty = true;
                }
                (3, _) => self.arrange(),
                (4, _) => {
                    self.graph_off = Vec2::ZERO;
                    self.graph_zoom = 1.0;
                }
                _ => self.set_status("Select a node first"),
            }
        }
        if rnd {
            self.randomize(sel_node);
        }
        // context menu result
        if let Some(i) = ui.take_popup_result("gen.ctx") {
            if let Some(id) = sel_node {
                match i {
                    0 => {
                        self.add_node(Kind::Branch, id);
                    }
                    1 => {
                        self.add_node(Kind::Leaf, id);
                    }
                    2 => self.duplicate_node(id),
                    3 => {
                        if let Some(n) = self.nodes.iter_mut().find(|n| n.id == id) {
                            n.hidden = !n.hidden;
                        }
                        self.dirty = true;
                    }
                    _ => self.delete_node(id),
                }
            }
        }

        ui.set_clip(Some(body));
        // background grid dots
        let step = 40.0 * self.graph_zoom;
        let o = self.graph_to_screen(body, Vec2::ZERO);
        let mut gx = body.x + (o.x - body.x).rem_euclid(step);
        while gx < body.x + body.w {
            let mut gy = body.y + (o.y - body.y).rem_euclid(step);
            while gy < body.y + body.h {
                draw_rectangle(gx, gy, 1.5, 1.5, Color::new(1.0, 1.0, 1.0, 0.07));
                gy += step;
            }
            gx += step;
        }
        let rad = 26.0 * self.graph_zoom;
        // links
        for n in &self.nodes {
            if let Some(pid) = n.parent {
                if let Some(p) = self.node(pid) {
                    let a = self.graph_to_screen(body, p.pos) - vec2(0.0, rad);
                    let b = self.graph_to_screen(body, n.pos) + vec2(0.0, rad);
                    let c = if sel_node == Some(n.id) { C_ORANGE } else { Color::new(1.0, 1.0, 1.0, 0.35) };
                    draw_line(a.x, a.y, b.x, b.y, 2.0, c);
                    draw_circle(a.x, a.y, 3.0, c);
                }
            }
        }
        let m = ui.mouse();
        let mut hover_node = None;
        for n in self.nodes.iter() {
            let c = self.graph_to_screen(body, n.pos);
            if c.distance(m) <= rad && body.contains(m) && !ui.blocked {
                hover_node = Some(n.id);
            }
        }
        // nodes
        let nodes = self.nodes.clone();
        for n in &nodes {
            let c = self.graph_to_screen(body, n.pos);
            let alpha = if n.hidden { 0.35 } else { 1.0 };
            let tex = self.icons.for_kind(n.kind);
            let tint = if n.kind == Kind::Trunk { Color::new(0.85, 0.75, 0.7, alpha) } else { Color::new(1.0, 1.0, 1.0, alpha) };
            draw_circle(c.x + 2.0, c.y + 3.0, rad, Color::new(0.0, 0.0, 0.0, 0.3));
            draw_texture_ex(tex, c.x - rad, c.y - rad, tint, DrawTextureParams { dest_size: Some(vec2(rad * 2.0, rad * 2.0)), ..Default::default() });
            let selected = sel_node == Some(n.id);
            if selected || hover_node == Some(n.id) {
                let rr = rad * 1.18;
                let col = if selected { C_ORANGE } else { Color::new(1.0, 1.0, 1.0, 0.45) };
                draw_texture_ex(&self.icons.ring, c.x - rr, c.y - rr, col, DrawTextureParams { dest_size: Some(vec2(rr * 2.0, rr * 2.0)), ..Default::default() });
            }
            let fs = (12.0 * self.graph_zoom.sqrt()).clamp(9.0, 15.0);
            let w = ui.text_w(&n.name, fs);
            ui.text(&n.name, c.x - w * 0.5, c.y + rad + 4.0, fs, if selected { WHITE } else { C_TEXT });
            if n.kind != Kind::Tree {
                let cnt = self.instance_count(n.id).to_string();
                let cw = ui.text_w(&cnt, 10.5) + 8.0;
                let br = Rect::new(c.x + rad * 0.55, c.y - rad * 1.05, cw, 15.0);
                draw_rectangle(br.x, br.y, br.w, br.h, Color::new(0.1, 0.1, 0.1, 0.85));
                ui.text_center(&cnt, br, 10.5, C_TEXT_DIM);
            }
            ui.record(&format!("node:{}", n.name), Rect::new(c.x - rad, c.y - rad, rad * 2.0, rad * 2.0));
        }

        // interaction
        let inp = ui.inp.clone();
        let in_body = body.contains(m) && !ui.blocked && ui.popup.is_none();
        if in_body && inp.wheel != 0.0 {
            let before = (m - self.graph_to_screen(body, Vec2::ZERO)) / self.graph_zoom;
            self.graph_zoom = (self.graph_zoom * 1.1f32.powf(inp.wheel)).clamp(0.4, 2.5);
            let after = (m - self.graph_to_screen(body, Vec2::ZERO)) / self.graph_zoom;
            self.graph_off += after - before;
        }
        if in_body && ui.active == 0 && self.graph_drag == GraphDrag::None {
            if inp.l_pressed {
                if let Some(id) = hover_node {
                    self.select(Sel::Node(id));
                    self.graph_drag = if inp.shift { GraphDrag::Link { from: id } } else { GraphDrag::Node { id, start: m, moved: false } };
                    ui.active = hid("graph");
                } else {
                    self.select(Sel::None);
                    self.graph_drag = GraphDrag::Pan;
                    ui.active = hid("graph");
                }
            } else if inp.r_pressed {
                if let Some(id) = hover_node {
                    self.select(Sel::Node(id));
                    ui.open_popup(hid("gen.ctx"), Rect::new(m.x, m.y, 10.0, 0.0), vec!["Add branch".into(), "Add leaf".into(), "Duplicate".into(), "Hide / show".into(), "Delete".into()], None);
                } else {
                    self.graph_drag = GraphDrag::Pan;
                }
            } else if inp.m_pressed {
                self.graph_drag = GraphDrag::Pan;
            }
        }
        let d = m - self.last_graph_mouse();
        match self.graph_drag {
            GraphDrag::Node { id, start, moved } => {
                if inp.l_down {
                    let mv = moved || start.distance(m) > 4.0;
                    if mv {
                        if let Some(n) = self.nodes.iter_mut().find(|n| n.id == id) {
                            n.pos += d / self.graph_zoom;
                        }
                    }
                    self.graph_drag = GraphDrag::Node { id, start, moved: mv };
                } else {
                    self.graph_drag = GraphDrag::None;
                }
            }
            GraphDrag::Link { from } => {
                if let Some(f) = self.node(from) {
                    let a = self.graph_to_screen(body, f.pos);
                    draw_line(a.x, a.y, m.x, m.y, 2.0, C_ACCENT2);
                }
                if !inp.l_down {
                    if let Some(to) = hover_node {
                        // dragging from child onto the new parent
                        self.reparent(from, to);
                    }
                    self.graph_drag = GraphDrag::None;
                }
            }
            GraphDrag::Pan => {
                if inp.l_down || inp.r_down || inp.m_down {
                    self.graph_off += d / self.graph_zoom;
                } else {
                    self.graph_drag = GraphDrag::None;
                }
            }
            GraphDrag::None => {}
        }
        self.graph_mouse = m;
        if self.nodes.len() == 1 {
            let t = "Use + Add to grow a trunk from the Tree node";
            let w = ui.text_w(t, 12.5);
            ui.text(t, body.x + (body.w - w) * 0.5, body.y + 30.0, 12.5, C_TEXT_FAINT);
        }
        ui.set_clip(None);
        let hint = "Shift+drag a node onto another to link it  •  right-click a node for more";
        ui.text_fit(hint, body.x + 8.0, body.y + body.h - 18.0, body.w - 16.0, 11.0, C_TEXT_FAINT);
    }

    fn last_graph_mouse(&self) -> Vec2 {
        self.graph_mouse
    }

    // ------------------------------------------------------------------ materials
    fn draw_materials(&mut self, ui: &mut Ui, tb: Rect, body: Rect) {
        let (add, act, _) = self.toolbar(ui, tb, "mat", &["Material (blank)", "Bark (procedural)", "Leaf (procedural)", "From image file..."], &["Duplicate", "Delete"], false);
        if let Some(i) = add {
            let mut m = match i {
                1 => Material::bark(),
                2 => Material::leaf(),
                3 => {
                    let mut m = Material::new("Image", 4);
                    m.two_sided = true;
                    if let Some(f) = crate::props::pick_image() {
                        m.name = std::path::Path::new(&f).file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or("Image".into());
                        m.file = f;
                    }
                    m
                }
                _ => Material::new("Material", 0),
            };
            m.name = format!("{} {}", m.name, self.materials.len() + 1);
            textures::refresh_material(&mut m);
            self.materials.push(m);
            self.select(Sel::Material(self.materials.len() - 1));
        }
        if let Some(i) = act {
            let cur = self.mat_cur.min(self.materials.len().saturating_sub(1));
            if i == 0 {
                let mut m = self.materials[cur].clone();
                m.name = format!("{} copy", m.name);
                self.materials.push(m);
                self.select(Sel::Material(self.materials.len() - 1));
            } else if self.materials.len() > 1 {
                self.materials.remove(cur);
                for n in &mut self.nodes {
                    if n.p.material >= cur && n.p.material > 0 {
                        n.p.material -= 1;
                    }
                    if n.p.leaf_material >= cur && n.p.leaf_material > 0 {
                        n.p.leaf_material -= 1;
                    }
                }
                self.select(Sel::None);
                self.mat_cur = 0;
                self.dirty = true;
            } else {
                self.set_status("Keep at least one material");
            }
        }
        // thumbnails
        let tile = 92.0;
        let cols = ((body.w - 12.0) / (tile + 8.0)).floor().max(1.0) as usize;
        let grid_h = ((self.materials.len() + cols - 1) / cols) as f32 * (tile + 26.0) + 10.0;
        for (i, m) in self.materials.iter().enumerate() {
            let x = body.x + 10.0 + (i % cols) as f32 * (tile + 8.0);
            let y = body.y + 10.0 + (i / cols) as f32 * (tile + 26.0);
            let r = Rect::new(x, y, tile, tile);
            checker(r, 8.0);
            if let Some(t) = &m.tex {
                draw_texture_ex(t, r.x, r.y, Color::new(m.color[0], m.color[1], m.color[2], 1.0), DrawTextureParams { dest_size: Some(vec2(tile, tile)), ..Default::default() });
            }
            let selected = self.sel == Sel::Material(i);
            draw_rectangle_lines(r.x - 1.0, r.y - 1.0, r.w + 2.0, r.h + 2.0, if selected { 2.0 } else { 1.0 }, if selected { C_ORANGE } else { C_LINE });
            let name = m.name.clone();
            ui.text_fit(&name, x, y + tile + 4.0, tile, 12.0, if selected { WHITE } else { C_TEXT_DIM });
            let hit = Rect::new(x, y, tile, tile + 20.0);
            ui.record(&format!("mat:{}", m.name), hit);
            if ui.clicked(hit) {
                self.sel = Sel::Material(i);
                self.mat_cur = i;
                self.prop_scroll = 0.0;
                self.dirty = true;
            }
        }
        // preview
        let py = body.y + grid_h + 6.0;
        let ph = (body.y + body.h - py - 10.0).max(60.0);
        let side = ph.min(body.w - 20.0);
        let pr = Rect::new(body.x + (body.w - side) * 0.5, py + 28.0, side, side - 28.0);
        let cur = self.mat_cur.min(self.materials.len().saturating_sub(1));
        let title = format!("Preview: {}", self.materials.get(cur).map(|m| m.name.clone()).unwrap_or_default());
        ui.text(&title, body.x + 10.0, py + 4.0, 13.0, C_TEXT);
        if ui.button_ex("mat.sphere", Rect::new(body.x + body.w - 130.0, py, 58.0, 22.0), "Sphere", self.preview_sphere, true) {
            self.preview_sphere = true;
        }
        if ui.button_ex("mat.card", Rect::new(body.x + body.w - 68.0, py, 58.0, 22.0), "Card", !self.preview_sphere, true) {
            self.preview_sphere = false;
        }
        ui.record("matpreview", pr);
        if pr.h > 40.0 {
            checker(pr, 12.0);
            if let Some(rt) = &self.preview_rt {
                draw_texture_ex(&rt.texture, pr.x, pr.y, WHITE, DrawTextureParams { dest_size: Some(vec2(pr.w, pr.h)), flip_y: true, ..Default::default() });
            }
            draw_rectangle_lines(pr.x, pr.y, pr.w, pr.h, 1.0, C_LINE);
        }
        self.preview_aspect = pr.w / pr.h.max(1.0);
    }

    /// Render the material preview (sphere or card) into its picture. Call before the UI pass.
    pub fn render_preview(&mut self) {
        if self.tab != 1 {
            return;
        }
        let gm = match &self.gm {
            Some(g) => g,
            None => return,
        };
        let rt = self.preview_rt.get_or_insert_with(|| {
            let r = render_target_ex(512, 512, RenderTargetParams { depth: true, ..Default::default() });
            r.texture.set_filter(FilterMode::Linear);
            r
        });
        let cur = self.mat_cur.min(self.materials.len().saturating_sub(1));
        let m = match self.materials.get(cur) {
            Some(m) => m,
            None => return,
        };
        let t = get_time() as f32 * 0.4;
        let cam = Cam { yaw: t, pitch: 0.25, dist: 3.6, target: Vec3::ZERO, ortho: false, view: 0, fov: 40.0 };
        let mut c3 = cam.camera3d(None, self.preview_aspect.max(0.2), Some(rt.clone()));
        c3.viewport = None;
        set_camera(&c3);
        clear_background(Color::new(0.0, 0.0, 0.0, 0.0));
        gl_use_material(gm);
        render::apply_material(gm, m, &self.light, cam.position());
        let src = if self.preview_sphere { &self.sphere } else { &self.card };
        for mesh in src {
            let tmp = Mesh { vertices: mesh.vertices.clone(), indices: mesh.indices.clone(), texture: m.tex.clone() };
            draw_mesh(&tmp);
        }
        unsafe { get_internal_gl() }.flush();
        gl_use_default_material();
        set_default_camera();
    }

    // ------------------------------------------------------------------ meshes
    fn draw_meshes(&mut self, ui: &mut Ui, tb: Rect, body: Rect) {
        let (add, act, _) = self.toolbar(ui, tb, "mesh", &["Card mesh", "Cutout from reference material"], &["Duplicate", "Delete"], false);
        if let Some(i) = add {
            let mut m = LeafMesh::card(&format!("Mesh {}", self.meshes.len() + 1));
            m.ref_material = self.mat_cur.min(self.materials.len().saturating_sub(1));
            if i == 1 {
                if let Some(img) = self.materials.get(m.ref_material).and_then(|x| x.adjusted.clone()) {
                    m.lods[0] = textures::auto_cutout(&img, m.auto_points as usize, m.threshold, m.margin);
                }
            }
            self.meshes.push(m);
            self.mesh_lod = 0;
            self.select(Sel::Mesh(self.meshes.len() - 1));
        }
        if let Some(i) = act {
            if !self.meshes.is_empty() {
                let cur = self.mesh_cur.min(self.meshes.len() - 1);
                if i == 0 {
                    let mut m = self.meshes[cur].clone();
                    m.name = format!("{} copy", m.name);
                    self.meshes.push(m);
                    self.select(Sel::Mesh(self.meshes.len() - 1));
                } else {
                    self.meshes.remove(cur);
                    for n in &mut self.nodes {
                        if n.p.leaf_mesh == cur + 1 {
                            n.p.leaf_mesh = 0;
                        } else if n.p.leaf_mesh > cur + 1 {
                            n.p.leaf_mesh -= 1;
                        }
                    }
                    self.mesh_cur = 0;
                    self.select(Sel::None);
                    self.dirty = true;
                }
            }
        }
        // mesh list
        let tile = 64.0;
        let mut x = body.x + 10.0;
        let y = body.y + 8.0;
        for i in 0..self.meshes.len() {
            let r = Rect::new(x, y, tile, tile);
            checker(r, 8.0);
            let m = &self.meshes[i];
            if let Some(t) = self.materials.get(m.ref_material).and_then(|mm| mm.tex.as_ref()) {
                draw_texture_ex(t, r.x, r.y, WHITE, DrawTextureParams { dest_size: Some(vec2(tile, tile)), ..Default::default() });
            }
            let pts: Vec<Vec2> = m.lods[0].iter().map(|p| vec2(r.x + p.x * tile, r.y + p.y * tile)).collect();
            for k in 0..pts.len() {
                let a = pts[k];
                let b = pts[(k + 1) % pts.len()];
                draw_line(a.x, a.y, b.x, b.y, 1.0, C_ORANGE);
            }
            let selected = self.mesh_cur == i;
            draw_rectangle_lines(r.x - 1.0, r.y - 1.0, r.w + 2.0, r.h + 2.0, if selected { 2.0 } else { 1.0 }, if selected { C_ORANGE } else { C_LINE });
            let name = m.name.clone();
            ui.text_fit(&name, x, y + tile + 3.0, tile + 20.0, 11.5, if selected { WHITE } else { C_TEXT_DIM });
            let hit = Rect::new(x, y, tile, tile + 18.0);
            ui.record(&format!("mesh:{}", name), hit);
            if ui.clicked(hit) {
                self.mesh_lod = 0;
                self.select(Sel::Mesh(i));
            }
            x += tile + 26.0;
        }
        if self.meshes.is_empty() {
            ui.text("No meshes. Use + Add to make one.", body.x + 12.0, body.y + 30.0, 12.5, C_TEXT_FAINT);
            return;
        }
        let cur = self.mesh_cur.min(self.meshes.len() - 1);
        self.mesh_cur = cur;
        // LOD buttons
        let ly = y + tile + 26.0;
        ui.text("Cutout editor", body.x + 10.0, ly + 3.0, 13.0, C_TEXT);
        let nl = self.meshes[cur].lods.len();
        self.mesh_lod = self.mesh_lod.min(nl - 1);
        for l in 0..nl {
            let br = Rect::new(body.x + body.w - 10.0 - (nl - l) as f32 * 50.0, ly, 46.0, 22.0);
            if ui.button_ex(&format!("mesh.lod{}", l), br, &format!("LOD{}", l), self.mesh_lod == l, true) {
                self.mesh_lod = l;
            }
        }
        // canvas
        let top = ly + 30.0;
        let avail = Rect::new(body.x + 10.0, top, body.w - 20.0, body.y + body.h - top - 40.0);
        let side = avail.w.min(avail.h).max(40.0);
        let cv = Rect::new(avail.x + (avail.w - side) * 0.5, avail.y, side, side);
        ui.record("meshcanvas", cv);
        draw_rectangle(cv.x - 1.0, cv.y - 1.0, cv.w + 2.0, cv.h + 2.0, C_BG);
        checker(cv, 16.0);
        let refm = self.meshes[cur].ref_material;
        if let Some(t) = self.materials.get(refm).and_then(|m| m.tex.as_ref()) {
            draw_texture_ex(t, cv.x, cv.y, WHITE, DrawTextureParams { dest_size: Some(vec2(cv.w, cv.h)), ..Default::default() });
        }
        let to_s = |p: Vec2| vec2(cv.x + p.x * cv.w, cv.y + p.y * cv.h);
        let to_uv = |s: Vec2| vec2((s.x - cv.x) / cv.w, (s.y - cv.y) / cv.h);
        let lod = self.mesh_lod;
        let poly = self.meshes[cur].lods[lod].clone();
        // triangulation preview
        for tri in textures::triangulate(&poly) {
            let a = to_s(poly[tri[0]]);
            let b = to_s(poly[tri[1]]);
            let c = to_s(poly[tri[2]]);
            draw_triangle(a, b, c, Color::new(0.85, 0.59, 0.28, 0.10));
            draw_line(a.x, a.y, b.x, b.y, 1.0, Color::new(1.0, 1.0, 1.0, 0.15));
            draw_line(b.x, b.y, c.x, c.y, 1.0, Color::new(1.0, 1.0, 1.0, 0.15));
        }
        for k in 0..poly.len() {
            let a = to_s(poly[k]);
            let b = to_s(poly[(k + 1) % poly.len()]);
            draw_line(a.x, a.y, b.x, b.y, 2.0, C_ORANGE);
        }
        let m = ui.mouse();
        let mut hover_pt: Option<i32> = None;
        let anc = to_s(self.meshes[cur].anchor);
        if anc.distance(m) < 9.0 {
            hover_pt = Some(-1);
        }
        for (k, p) in poly.iter().enumerate() {
            let s = to_s(*p);
            if s.distance(m) < 7.0 {
                hover_pt = Some(k as i32);
            }
        }
        for (k, p) in poly.iter().enumerate() {
            let s = to_s(*p);
            let hot = hover_pt == Some(k as i32) || self.mesh_drag == Some(k as i32);
            draw_rectangle(s.x - 4.0, s.y - 4.0, 8.0, 8.0, if hot { WHITE } else { C_ORANGE });
            draw_rectangle_lines(s.x - 4.0, s.y - 4.0, 8.0, 8.0, 1.0, Color::new(0.0, 0.0, 0.0, 0.6));
        }
        // anchor (attachment point)
        draw_circle_lines(anc.x, anc.y, 7.0, 2.0, Color::new(0.3, 0.95, 0.4, 1.0));
        draw_line(anc.x - 11.0, anc.y, anc.x + 11.0, anc.y, 1.0, Color::new(0.3, 0.95, 0.4, 1.0));
        draw_line(anc.x, anc.y - 11.0, anc.x, anc.y + 11.0, 1.0, Color::new(0.3, 0.95, 0.4, 1.0));
        ui.text("anchor", anc.x + 9.0, anc.y + 4.0, 10.5, Color::new(0.3, 0.95, 0.4, 1.0));

        let inp = ui.inp.clone();
        let over = cv.contains(m) && !ui.blocked && ui.popup.is_none();
        let mut changed = false;
        if over && ui.active == 0 {
            if inp.l_double && hover_pt.is_none() {
                // insert a point on the nearest edge
                let uv = to_uv(m);
                let mut best = (f32::MAX, 0usize);
                for k in 0..poly.len() {
                    let a = poly[k];
                    let b = poly[(k + 1) % poly.len()];
                    let ab = b - a;
                    let t = ((uv - a).dot(ab) / ab.length_squared().max(1e-9)).clamp(0.0, 1.0);
                    let d = (a + ab * t).distance(uv);
                    if d < best.0 {
                        best = (d, k);
                    }
                }
                self.meshes[cur].lods[lod].insert(best.1 + 1, uv);
                changed = true;
            } else if inp.l_pressed {
                if let Some(h) = hover_pt {
                    self.mesh_drag = Some(h);
                    ui.active = hid("meshcanvas");
                }
            } else if inp.r_pressed {
                if let Some(h) = hover_pt {
                    if h >= 0 && poly.len() > 3 {
                        self.meshes[cur].lods[lod].remove(h as usize);
                        changed = true;
                    }
                }
            }
        }
        if let Some(h) = self.mesh_drag {
            if inp.l_down {
                let uv = to_uv(m);
                let uv = vec2(uv.x.clamp(-0.1, 1.1), uv.y.clamp(-0.1, 1.1));
                if h < 0 {
                    self.meshes[cur].anchor = vec2(uv.x.clamp(0.0, 1.0), uv.y.clamp(0.0, 1.0));
                } else if (h as usize) < self.meshes[cur].lods[lod].len() {
                    self.meshes[cur].lods[lod][h as usize] = uv;
                }
                changed = true;
            } else {
                self.mesh_drag = None;
            }
        }
        if changed {
            self.dirty = true;
            if self.sel != Sel::Mesh(cur) {
                self.sel = Sel::Mesh(cur);
            }
        }
        let tris = textures::triangulate(&self.meshes[cur].lods[lod]).len();
        let info = format!("{} points, {} triangles", self.meshes[cur].lods[lod].len(), tris);
        ui.text(&info, cv.x, cv.y + cv.h + 6.0, 11.5, C_TEXT_DIM);
        ui.text_fit("Drag points or the green anchor • double-click an edge to add • right-click a point to remove", body.x + 10.0, body.y + body.h - 18.0, body.w - 20.0, 11.0, C_TEXT_FAINT);
    }
}

fn draw_gpu(gpu: &GpuTree, mats: &[Material], gm: &macroquad::material::Material, light: &Lighting, cam_pos: Vec3) {
    gl_use_material(gm);
    for (mi, meshes) in &gpu.parts {
        let fallback = Material::new("?", 0);
        let m = mats.get(*mi).unwrap_or(&fallback);
        render::apply_material(gm, m, light, cam_pos);
        for mesh in meshes {
            draw_mesh(mesh);
        }
        unsafe { get_internal_gl() }.flush();
    }
    gl_use_default_material();
}

