/// One frame of the whole app. Returns false to quit.
fn frame(app: &mut App, ui: &mut Ui, inp: Inp) -> bool {
    let scale = ui_scale();
    ui.scale = scale;
    let w = screen_width() / scale;
    let h = screen_height() / scale;
    ui.begin(inp);
    let lay = layout(w, h);
    app.viewport = lay.view;

    if app.dirty {
        app.regenerate();
    }
