// ---------------- leaf meshes ----------------

#[derive(Clone)]
pub struct LeafMesh {
    pub name: String,
    /// Each LOD is a closed outline in texture space (u right, v down, 0..1).
    pub lods: Vec<Vec<Vec2>>,
    /// Where the leaf attaches to its parent (texture space).
    pub anchor: Vec2,
    pub ref_material: usize,
    pub auto_points: i32,
    pub threshold: f32,
    pub margin: f32,
    pub scale: f32,
    pub flip: bool,
}

impl LeafMesh {
    pub fn card(name: &str) -> Self {
        LeafMesh {
            name: name.to_string(),
            lods: vec![vec![vec2(0.0, 0.0), vec2(1.0, 0.0), vec2(1.0, 1.0), vec2(0.0, 1.0)]],
            anchor: vec2(0.5, 1.0),
            ref_material: 1,
            auto_points: 10,
            threshold: 0.2,
            margin: 0.02,
            scale: 1.0,
            flip: false,
        }
    }
}

pub fn mesh_names(meshes: &[LeafMesh]) -> Vec<String> {
    let mut v = vec!["Card (plain quad)".to_string()];
    for m in meshes {
        v.push(m.name.clone());
    }
    v
}

