            Some("v") => {
                let a: Vec<f32> = it.take(3).filter_map(|s| s.parse().ok()).collect();
                if a.len() == 3 {
                    v.push(vec3(a[0], a[1], a[2]));
                }
            }
            Some("vt") => {
                let a: Vec<f32> = it.take(2).filter_map(|s| s.parse().ok()).collect();
                if !a.is_empty() {
                    vt.push(vec2(a[0], 1.0 - a.get(1).copied().unwrap_or(0.0)));
                }
            }
            Some("vn") => {
                let a: Vec<f32> = it.take(3).filter_map(|s| s.parse().ok()).collect();
