        }
        if changed {
            self.dirty = true;
        }
    }

    fn remove_mesh(&mut self, cur: usize) {
        if self.meshes.is_empty() {
            return;
        }
        self.meshes.remove(cur);
        for n in &mut self.nodes {
            if n.p.leaf_mesh == cur + 1 {
                n.p.leaf_mesh = 0;
            } else if n.p.leaf_mesh > cur + 1 {
                n.p.leaf_mesh -= 1;
            }
        }
        for m in &mut self.meshes {
            if m.more == cur + 1 {
                m.more = 0;
            } else if m.more > cur + 1 {
                m.more -= 1;
            }
        }
        self.mesh_cur = 0;
        self.mesh_lod = 0;
        self.select(Sel::None);
        self.dirty = true;
    }

    fn pick_mesh_file() -> Option<String> {
        rfd::FileDialog::new().add_filter("Mesh (OBJ)", &["obj"]).pick_file().map(|p| p.to_string_lossy().to_string())
    }

    fn add_mesh_from_file(&mut self) {
        if let Some(f) = Self::pick_mesh_file() {
            match meshio::load_obj(&f) {
                Ok(g) => {
                    let name = std::path::Path::new(&f).file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or("Mesh".into());
                    let mut m = LeafMesh::card(&name);
                    m.lods[0] = MeshLod { file: f, outline: vec![], geom: Some(g) };
                    m.ref_material = self.mat_cur.min(self.materials.len().saturating_sub(1));
                    self.meshes.push(m);
                    self.mesh_lod = 0;
                    self.select(Sel::Mesh(self.meshes.len() - 1));
                    self.set_status(&format!("Added mesh \"{}\"", name));
                }
                Err(e) => self.set_status(&format!("Couldn't read that mesh: {}", e)),
            }
        }
    }

    fn browse_lod(&mut self, cur: usize, l: usize) {
        if let Some(f) = Self::pick_mesh_file() {
            match meshio::load_obj(&f) {
                Ok(g) => {
                    self.meshes[cur].lods[l] = MeshLod { file: f, outline: vec![], geom: Some(g) };
                    self.mesh_lod = l;
                    self.dirty = true;
                }
                Err(e) => self.set_status(&format!("Couldn't read that mesh: {}", e)),
            }
        }
    }

    fn reload_lod(&mut self, cur: usize, l: usize) {
        let file = self.meshes[cur].lods[l].file.clone();
        if file.is_empty() {
            self.set_status("This level is a cutout; there is no file to reload");
            return;
        }
        match meshio::load_obj(&file) {
            Ok(g) => {
                self.meshes[cur].lods[l].geom = Some(g);
                self.dirty = true;
                self.set_status("Reloaded");
            }
            Err(e) => self.set_status(&format!("Couldn't reload: {}", e)),
        }
    }

    fn export_lod(&mut self, cur: usize, l: usize) {
        let g = match meshio::processed_geom(&self.meshes, cur, l) {
            Some(g) => g,
            None => {
                self.set_status("This level is empty");
                return;
            }
        };
        let name = format!("{}_{}.obj", self.meshes[cur].name.replace(' ', "_"), LOD_NAMES[l]);
        if let Some(p) = rfd::FileDialog::new().add_filter("Mesh (OBJ)", &["obj"]).set_file_name(&name).save_file() {
            match meshio::save_obj(&p.to_string_lossy(), &g) {
                Ok(()) => self.set_status("Mesh exported"),
                Err(e) => self.set_status(&format!("Couldn't export: {}", e)),
            }
        }
    }

    /// Dropping a mesh on the model: the selected leaf generator uses it (or the first one).
    pub fn drop_mesh_on_model(&mut self, cur: usize) {
        let target = match self.sel {
            Sel::Node(id) if self.node(id).map(|n| n.kind == Kind::Leaf).unwrap_or(false) => Some(id),
            _ => self.nodes.iter().find(|n| n.kind == Kind::Leaf).map(|n| n.id),
        };
        match target {
            Some(id) => {
                let name = self.meshes[cur].name.clone();
                if let Some(n) = self.nodes.iter_mut().find(|n| n.id == id) {
                    n.p.leaf_mesh = cur + 1;
                    let nn = n.name.clone();
                    self.set_status(&format!("\"{}\" now uses mesh \"{}\"", nn, name));
                }
                self.dirty = true;
            }
            None => self.set_status("Add a Leaf generator first"),
        }
    }

    /// The cutout editor ("Edit Mesh..."): outline points and anchor over the reference picture.
    fn draw_cutout_editor(&mut self, ui: &mut Ui, area: Rect, cur: usize) {
        let lod = self.mesh_lod.min(2);
        draw_rectangle(area.x, area.y, area.w, area.h, C_BG);
        let title = format!("Cutout editor: {} level", LOD_NAMES[lod]);
        ui.text(&title, area.x + 6.0, area.y + 4.0, 12.0, C_TEXT);
        if self.meshes[cur].lods[lod].geom.is_some() {
            ui.text("This level comes from a mesh file.", area.x + 6.0, area.y + 30.0, 12.5, C_TEXT_DIM);
            if ui.button("mesh.tocutout", Rect::new(area.x + 6.0, area.y + 52.0, 170.0, 24.0), "Replace with a cutout") {
                self.meshes[cur].lods[lod] = MeshLod { file: String::new(), outline: card_outline(), geom: None };
                self.dirty = true;
            }
            return;
        }
        if self.meshes[cur].lods[lod].outline.len() < 3 {
            ui.text("This level is empty.", area.x + 6.0, area.y + 30.0, 12.5, C_TEXT_DIM);
            if ui.button("mesh.fromhigh", Rect::new(area.x + 6.0, area.y + 52.0, 210.0, 24.0), "Make it from High (fewer points)") {
                let src = self.meshes[cur].lods[0].outline.clone();
                if src.len() >= 3 {
                    let n = (src.len() * if lod == 1 { 2 } else { 1 } / 3).max(3);
                    self.meshes[cur].lods[lod].outline = textures::reduce_outline(src, n);
                } else {
                    self.meshes[cur].lods[lod].outline = card_outline();
                }
                self.dirty = true;
            }
            return;
        }
        let avail = Rect::new(area.x + 6.0, area.y + 22.0, area.w - 12.0, area.h - 44.0);
        let side = avail.w.min(avail.h).max(40.0);
        let cv = Rect::new(avail.x + (avail.w - side) * 0.5, avail.y, side, side);
        checker(cv, 16.0);
        let refm = self.meshes[cur].ref_material;
        if let Some(t) = self.materials.get(refm).and_then(|m| m.tex.as_ref()) {
            draw_texture_ex(t, cv.x, cv.y, WHITE, DrawTextureParams { dest_size: Some(vec2(cv.w, cv.h)), ..Default::default() });
        }
        let to_s = |p: Vec2| vec2(cv.x + p.x * cv.w, cv.y + p.y * cv.h);
        let to_uv = |s: Vec2| vec2((s.x - cv.x) / cv.w, (s.y - cv.y) / cv.h);
        let poly = self.meshes[cur].lods[lod].outline.clone();
        for tri in textures::triangulate(&poly) {
            let a = to_s(poly[tri[0]]);
            let b = to_s(poly[tri[1]]);
            let c = to_s(poly[tri[2]]);
            draw_triangle(a, b, c, Color::new(0.85, 0.59, 0.28, 0.10));
            draw_line(a.x, a.y, b.x, b.y, 1.0, Color::new(1.0, 1.0, 1.0, 0.15));
            draw_line(b.x, b.y, c.x, c.y, 1.0, Color::new(1.0, 1.0, 1.0, 0.15));
        }
        for k in 0..poly.len() {
            let a = to_s(poly[k]);
            let b = to_s(poly[(k + 1) % poly.len()]);
            draw_line(a.x, a.y, b.x, b.y, 2.0, C_ORANGE);
        }
        let m = ui.mouse();
        let mut hover_pt: Option<i32> = None;
        let anc = to_s(self.meshes[cur].anchor);
        if anc.distance(m) < 9.0 {
            hover_pt = Some(-1);
        }
        for (k, p) in poly.iter().enumerate() {
            if to_s(*p).distance(m) < 7.0 {
                hover_pt = Some(k as i32);
            }
        }
        for (k, p) in poly.iter().enumerate() {
            let s = to_s(*p);
            let hot = hover_pt == Some(k as i32) || self.mesh_drag == Some(k as i32);
            draw_rectangle(s.x - 4.0, s.y - 4.0, 8.0, 8.0, if hot { WHITE } else { C_ORANGE });
            draw_rectangle_lines(s.x - 4.0, s.y - 4.0, 8.0, 8.0, 1.0, Color::new(0.0, 0.0, 0.0, 0.6));
        }
        let green = Color::new(0.3, 0.95, 0.4, 1.0);
        draw_circle_lines(anc.x, anc.y, 7.0, 2.0, green);
        draw_line(anc.x - 11.0, anc.y, anc.x + 11.0, anc.y, 1.0, green);
        draw_line(anc.x, anc.y - 11.0, anc.x, anc.y + 11.0, 1.0, green);
        ui.text("anchor", anc.x + 9.0, anc.y + 4.0, 10.5, green);

        let inp = ui.inp.clone();
        let over = cv.contains(m) && !ui.blocked && ui.popup.is_none();
        let mut changed = false;
        if over && ui.active == 0 {
            if inp.l_double && hover_pt.is_none() {
                let uv = to_uv(m);
                let mut best = (f32::MAX, 0usize);
                for k in 0..poly.len() {
                    let a = poly[k];
                    let b = poly[(k + 1) % poly.len()];
                    let ab = b - a;
                    let t = ((uv - a).dot(ab) / ab.length_squared().max(1e-9)).clamp(0.0, 1.0);
                    let d = (a + ab * t).distance(uv);
                    if d < best.0 {
                        best = (d, k);
                    }
                }
                self.meshes[cur].lods[lod].outline.insert(best.1 + 1, uv);
                changed = true;
            } else if inp.l_pressed {
                if let Some(h) = hover_pt {
                    self.mesh_drag = Some(h);
                    ui.active = hid("meshcanvas");
                }
            } else if inp.r_pressed {
                if let Some(h) = hover_pt {
                    if h >= 0 && poly.len() > 3 {
                        self.meshes[cur].lods[lod].outline.remove(h as usize);
                        changed = true;
                    }
                }
            }
        }
        if let Some(h) = self.mesh_drag {
            if inp.l_down {
                let uv = to_uv(m);
                let uv = vec2(uv.x.clamp(-0.1, 1.1), uv.y.clamp(-0.1, 1.1));
                if h < 0 {
                    self.meshes[cur].anchor = vec2(uv.x.clamp(0.0, 1.0), uv.y.clamp(0.0, 1.0));
                } else if (h as usize) < self.meshes[cur].lods[lod].outline.len() {
                    self.meshes[cur].lods[lod].outline[h as usize] = uv;
                }
                changed = true;
            } else {
                self.mesh_drag = None;
            }
        }
        if changed {
            self.dirty = true;
            if self.sel != Sel::Mesh(cur) {
                self.sel = Sel::Mesh(cur);
            }
        }
        ui.text_fit(
            "Drag points or the green anchor • double-click an edge to add • right-click a point to remove",
            area.x + 6.0,
            area.y + area.h - 18.0,
            area.w - 12.0,
            10.5,
            C_TEXT_FAINT,
        );
    }

    /// Render the selected mesh into the Meshes tab's preview picture (before the UI pass).
    pub fn render_mesh_preview(&mut self) {
        if self.tab != 2 || self.mesh_editing || self.meshes.is_empty() {
            return;
        }
        let gm = match &self.gm {
            Some(g) => g,
            None => return,
        };
        let rt = self.mesh_rt.get_or_insert_with(|| {
            let r = render_target_ex(640, 512, RenderTargetParams { depth: true, ..Default::default() });
            r.texture.set_filter(FilterMode::Linear);
            r
        });
        let cur = self.mesh_cur.min(self.meshes.len() - 1);
        let g = meshio::processed_geom(&self.meshes, cur, self.mesh_lod);
        let (bmin, bmax) = g.as_ref().map(meshio::bounds).unwrap_or((Vec3::splat(-0.5), Vec3::splat(0.5)));
        let center = (bmin + bmax) * 0.5;
        let radius = ((bmax - bmin).length() * 0.5).max(0.05);
        let cam = Cam {
            yaw: self.mesh_yaw,
            pitch: self.mesh_pitch,
            dist: radius / (20.0f32.to_radians()).sin() * 1.15 * self.mesh_zoom,
            target: center,
            ortho: false,
            view: 0,
            fov: 40.0,
        };
        let c3 = cam.camera3d(None, self.mesh_preview_aspect.max(0.2), Some(rt.clone()));
        set_camera(&c3);
        clear_background(Color::new(0.0, 0.0, 0.0, 0.0));
        if let Some(g) = &g {
            let refm = self.meshes[cur].ref_material;
            let fallback = Material::new("?", 0);
            let mat = self.materials.get(refm).unwrap_or(&fallback);
            let verts: Vec<macroquad::models::Vertex> = g
                .pos
                .iter()
                .enumerate()
                .map(|(i, p)| macroquad::models::Vertex {
                    position: *p,
                    uv: g.uv[i],
                    color: [255; 4],
                    normal: vec4(g.nrm[i].x, g.nrm[i].y, g.nrm[i].z, 1.0),
                })
                .collect();
            let idx: Vec<u16> = g.idx.iter().map(|&i| i as u16).collect();
            gl_use_material(gm);
            render::apply_material(gm, mat, &self.light, cam.position());
            draw_mesh(&Mesh { vertices: verts, indices: idx, texture: mat.tex.clone() });
            unsafe { get_internal_gl() }.flush();
            gl_use_default_material();
        }
        // axes at the mesh origin (the attachment point), growth axis in yellow
        let len = radius * 1.2;
        draw_line_3d(Vec3::ZERO, Vec3::X * len, Color::new(0.9, 0.35, 0.35, 1.0));
        draw_line_3d(Vec3::ZERO, Vec3::Y * len, Color::new(0.4, 0.85, 0.4, 1.0));
        draw_line_3d(Vec3::ZERO, Vec3::Z * len, Color::new(0.4, 0.55, 1.0, 1.0));
        let ga = meshio::growth_axis(self.meshes[cur].growth) * len * 1.1;
        draw_line_3d(Vec3::ZERO, ga, Color::new(1.0, 0.85, 0.2, 1.0));
        if self.show_alignment {
            // the intended orientation: a leaf lying in X/Y, growing up +Y from the origin, facing +Z
            let s = radius * 1.6;
            let mut prev: Option<Vec3> = None;
            let shape: Vec<Vec3> = (0..=24)
                .map(|i| {
                    let t = i as f32 / 24.0;
                    let a = t * std::f32::consts::TAU;
                    let yv = (1.0 - a.cos()) * 0.5;
                    vec3(a.sin() * 0.35 * (1.0 - yv * 0.4), yv, 0.0) * s
                })
                .collect();
            for p in shape {
                if let Some(q) = prev {
                    draw_line_3d(q, p, Color::new(1.0, 1.0, 1.0, 0.7));
                }
                prev = Some(p);
            }
            draw_line_3d(Vec3::ZERO, Vec3::Y * s, Color::new(1.0, 1.0, 1.0, 0.5));
        }
        set_default_camera();
    }
}

fn group_box(ui: &mut Ui, r: Rect, title: &str) {
    draw_rectangle_lines(r.x, r.y + 6.0, r.w, r.h - 6.0, 1.0, Color::new(1.0, 1.0, 1.0, 0.14));
    if !title.is_empty() {
        let tw = ui.text_w(title, 12.0);
        draw_rectangle(r.x + 6.0, r.y, tw + 8.0, 12.0, C_PANEL);
        ui.text(title, r.x + 10.0, r.y - 1.0, 12.0, C_TEXT_DIM);
    }
}

fn icon_hand(r: Rect) {
    let c = Color::new(1.0, 1.0, 1.0, 0.85);
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    draw_rectangle(cx - 6.0, cy - 1.0, 12.0, 9.0, c);
    for (i, h) in [6.0f32, 9.0, 9.0, 7.0].iter().enumerate() {
        draw_rectangle(cx - 6.0 + i as f32 * 3.2, cy - 1.0 - h, 2.4, *h, c);
    }
    draw_rectangle(cx + 5.0, cy - 2.0, 4.0, 2.4, c);
}

fn icon_reload(r: Rect) {
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    let c = Color::new(1.0, 1.0, 1.0, 0.8);
    let mut prev: Option<Vec2> = None;
    for i in 0..=14 {
        let a = 0.6 + i as f32 / 14.0 * 5.0;
        let p = vec2(cx + a.cos() * 6.0, cy + a.sin() * 6.0);
        if let Some(q) = prev {
            draw_line(q.x, q.y, p.x, p.y, 1.5, c);
        }
        prev = Some(p);
    }
    let tip = vec2(cx + 0.6f32.cos() * 6.0, cy + 0.6f32.sin() * 6.0);
    draw_triangle(tip + vec2(-3.0, -3.0), tip + vec2(3.0, -1.0), tip + vec2(0.0, 3.0), c);
}

fn icon_export(r: Rect) {
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    let c = Color::new(1.0, 1.0, 1.0, 0.8);
    draw_rectangle_lines(cx - 2.0, cy - 6.0, 8.0, 12.0, 1.2, c);
    draw_line(cx - 8.0, cy, cx + 1.0, cy, 1.5, c);
    draw_triangle(vec2(cx + 3.0, cy), vec2(cx - 1.0, cy - 3.5), vec2(cx - 1.0, cy + 3.5), c);
}

fn icon_clipboard(r: Rect) {
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    let c = Color::new(1.0, 1.0, 1.0, 0.85);
    draw_rectangle_lines(cx - 5.0, cy - 6.0, 10.0, 13.0, 1.3, c);
    draw_rectangle(cx - 2.5, cy - 7.5, 5.0, 3.0, c);
    draw_line(cx - 3.0, cy - 1.0, cx + 3.0, cy - 1.0, 1.0, c);
    draw_line(cx - 3.0, cy + 2.0, cx + 3.0, cy + 2.0, 1.0, c);
}

toolu_01CLDJEGCFGRD5FryAqTFMqt.content:
    // ------------------------------------------------------------------ meshes
    /// The Meshes tab, laid out like the original's Meshes panel (fn 0x140076fd0 in 8.4.2):
    /// drag handle, mesh picker, +/-, +, copy/paste; Geometry (Edit Mesh..., High/Med/Low
    /// files, More); preview; Show / Alignment / V:F; Transform; Collection; Wind direction;
    /// Proxy collision.
    fn draw_meshes(&mut self, ui: &mut Ui, tb: Rect, body: Rect) {
        let r = Rect::new(tb.x, tb.y, tb.w, body.y + body.h - tb.y);
        let x0 = r.x + 8.0;
        let w = r.w - 16.0;
        let mut y = r.y + 4.0;

        // ---- top row
        let hand = Rect::new(x0, y, 30.0, 30.0);
        ui.record("btn:mesh.drag", hand);
        let hot = ui.hover(hand);
        draw_rectangle(hand.x, hand.y, hand.w, hand.h, if hot || self.hand_drag { C_BTN_HOT } else { C_BTN });
        icon_hand(hand);
        if hot {
            ui.tooltip = Some("Drag this mesh and drop it on the model to use it.".into());
            if ui.inp.l_pressed && !self.meshes.is_empty() {
                self.hand_drag = true;
                ui.active = hid("mesh.drag");
            }
        }
        let bw = 34.0;
        let combo_w = (w - 36.0 - (bw + 4.0) * 3.0).max(60.0);
        let names: Vec<String> = if self.meshes.is_empty() { vec!["No meshes".into()] } else { self.meshes.iter().map(|m| m.name.clone()).collect() };
        let mut cur = self.mesh_cur.min(self.meshes.len().saturating_sub(1));
        let cr = Rect::new(x0 + 36.0, y + 4.0, combo_w, 22.0);
        if ui.combo("mesh.pick", cr, &names, &mut cur) && !self.meshes.is_empty() {
            self.mesh_lod = 0;
            self.select(Sel::Mesh(cur));
        }
        if ui.hover(cr) {
            ui.tooltip = Some("Select a mesh to edit. Meshes are used as leaf geometry.".into());
        }
        let bx = cr.x + cr.w + 4.0;
        let r1 = Rect::new(bx, y + 4.0, bw, 22.0);
        if ui.button("mesh.addremove", r1, "+/-") {
            ui.open_popup(hid("mesh.addremove"), r1, vec!["Add mesh (card)".into(), "Add cutout from reference material".into(), "Remove this mesh".into()], None);
        }
        if ui.hover(r1) {
            ui.tooltip = Some("Manage the meshes.".into());
        }
        let r2 = Rect::new(bx + bw + 4.0, y + 4.0, bw, 22.0);
        if ui.button("mesh.browseadd", r2, "+") {
            self.add_mesh_from_file();
        }
        if ui.hover(r2) {
            ui.tooltip = Some("Browse for a mesh and add it to the list automatically...".into());
        }
        let r3 = Rect::new(bx + (bw + 4.0) * 2.0, y + 4.0, bw, 22.0);
        if ui.button("mesh.copypaste", r3, "") {
            ui.open_popup(hid("mesh.copypaste"), r3, vec!["Copy".into(), "Paste".into(), "Duplicate".into()], None);
        }
        icon_clipboard(r3);
        if ui.hover(r3) {
            ui.tooltip = Some("Copy/Paste menu...".into());
        }
        if let Some(i) = ui.take_popup_result("mesh.addremove") {
            match i {
                0 | 1 => {
                    let mut m = LeafMesh::card(&format!("Mesh {}", self.meshes.len() + 1));
                    m.ref_material = self.mat_cur.min(self.materials.len().saturating_sub(1));
                    if i == 1 {
                        if let Some(img) = self.materials.get(m.ref_material).and_then(|x| x.adjusted.clone()) {
                            m.lods[0].outline = textures::auto_cutout(&img, m.auto_points as usize, m.threshold, m.margin);
                        }
                    }
                    self.meshes.push(m);
                    self.mesh_lod = 0;
                    self.select(Sel::Mesh(self.meshes.len() - 1));
                }
                _ => self.remove_mesh(cur),
            }
        }
        if let Some(i) = ui.take_popup_result("mesh.copypaste") {
            if !self.meshes.is_empty() {
                match i {
                    0 => {
                        self.mesh_clip = Some(self.meshes[cur].clone());
                        self.set_status("Mesh copied");
                    }
                    1 => match self.mesh_clip.clone() {
                        Some(mut m) => {
                            m.name = self.meshes[cur].name.clone();
                            self.meshes[cur] = m;
                            self.dirty = true;
                            self.set_status("Mesh pasted");
                        }
                        None => self.set_status("Nothing copied yet"),
                    },
                    _ => {
                        let mut m = self.meshes[cur].clone();
                        m.name = format!("{} copy", m.name);
                        self.meshes.push(m);
                        self.select(Sel::Mesh(self.meshes.len() - 1));
                    }
                }
            }
        }
        // drag-and-drop the mesh onto the model
        if self.hand_drag {
            if ui.inp.l_down {
                if let Some(m) = self.meshes.get(cur) {
                    ui.tooltip = Some(format!("Drop on the viewport to use \"{}\" for the leaves", m.name));
                }
            } else {
                self.hand_drag = false;
                if self.viewport.contains(ui.mouse()) && !self.meshes.is_empty() {
                    self.drop_mesh_on_model(cur);
                }
            }
        }
        y += 38.0;
        if self.meshes.is_empty() {
            ui.text("No meshes. Use +/- to add one, or + to load a mesh file.", x0, y + 6.0, 12.5, C_TEXT_FAINT);
            return;
        }
        self.mesh_cur = cur;

        // ---- Geometry
        ui.text("Geometry", x0, y, 12.0, C_TEXT_DIM);
        y += 17.0;
        let lw = 40.0;
        let er = Rect::new(x0 + lw, y, w - lw - 90.0, 22.0);
        let label = if self.mesh_editing { "Done editing" } else { "Edit Mesh..." };
        if ui.button_ex("mesh.edit", er, label, self.mesh_editing, true) {
            self.mesh_editing = !self.mesh_editing;
        }
        y += 26.0;
        for l in 0..3 {
            let lab = LOD_NAMES[l];
            let tw = ui.text_w(lab, 12.0);
            ui.text(lab, x0 + lw - tw - 6.0, y + 4.0, 12.0, C_TEXT_DIM);
            let fr = Rect::new(x0 + lw, y, w - lw - 90.0, 22.0);
            let selected = self.mesh_lod == l;
            draw_rectangle(fr.x, fr.y, fr.w, fr.h, C_FIELD);
            if selected {
                draw_rectangle_lines(fr.x, fr.y, fr.w, fr.h, 1.0, C_ACCENT2);
            }
            let lod = &self.meshes[cur].lods[l];
            let desc = if self.meshes[cur].collection {
                "(collection)".to_string()
            } else if !lod.file.is_empty() {
                std::path::Path::new(&lod.file).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default()
            } else if lod.outline.len() >= 3 {
                format!("cutout, {} points", lod.outline.len())
            } else {
                String::new()
            };
            ui.text_fit(&desc, fr.x + 6.0, fr.y + 4.0, fr.w - 10.0, 12.0, C_TEXT);
            ui.record(&format!("mesh.lodfield.{}", l), fr);
            if ui.clicked(fr) {
                self.mesh_lod = l;
            }
            let b1 = Rect::new(fr.x + fr.w + 4.0, y, 26.0, 22.0);
            if ui.button(&format!("mesh.browse{}", l), b1, "...") {
                self.browse_lod(cur, l);
            }
            if ui.hover(b1) {
                ui.tooltip = Some(format!("Browse for the {} mesh file...", lab.to_lowercase()));
            }
            let b2 = Rect::new(b1.x + 30.0, y, 26.0, 22.0);
            if ui.button(&format!("mesh.reload{}", l), b2, "") {
                self.reload_lod(cur, l);
            }
            icon_reload(b2);
            if ui.hover(b2) {
                ui.tooltip = Some("Reload this mesh.".into());
            }
            let b3 = Rect::new(b2.x + 30.0, y, 26.0, 22.0);
            if ui.button(&format!("mesh.export{}", l), b3, "") {
                self.export_lod(cur, l);
            }
            icon_export(b3);
            if ui.hover(b3) {
                ui.tooltip = Some("Export this mesh...".into());
            }
            y += 25.0;
        }
        {
            let tw = ui.text_w("More", 12.0);
            ui.text("More", x0 + lw - tw - 6.0, y + 4.0, 12.0, C_TEXT_DIM);
            let mut more_names = vec!["None".to_string()];
            for (i, m) in self.meshes.iter().enumerate() {
                more_names.push(if i == cur { format!("{} (this mesh)", m.name) } else { m.name.clone() });
            }
            let mut more = self.meshes[cur].more.min(more_names.len() - 1);
            let mr = Rect::new(x0 + lw, y, w - lw - 90.0, 22.0);
            if ui.combo("mesh.more", mr, &more_names, &mut more) {
                if more == cur + 1 {
                    self.set_status("A mesh can't supply its own extra levels");
                } else {
                    self.meshes[cur].more = more;
                    self.dirty = true;
                }
            }
            if ui.hover(mr) {
                ui.tooltip = Some("Another mesh whose levels continue this one's (LOD 3 and lower).".into());
            }
            y += 28.0;
        }

        // ---- preview / cutout editor
        let bottom_h = 232.0;
        let pv = Rect::new(x0, y, w, (r.y + r.h - bottom_h - y).max(90.0));
        ui.record("meshcanvas", pv);
        if self.mesh_editing {
            self.draw_cutout_editor(ui, pv, cur);
        } else {
            checker(pv, 12.0);
            if let Some(rt) = &self.mesh_rt {
                draw_texture_ex(&rt.texture, pv.x, pv.y, WHITE, DrawTextureParams { dest_size: Some(vec2(pv.w, pv.h)), flip_y: true, ..Default::default() });
            }
            draw_rectangle_lines(pv.x, pv.y, pv.w, pv.h, 1.0, C_LINE);
            ui.text("drag to turn • wheel to zoom • double-click to reset", pv.x + 6.0, pv.y + pv.h - 16.0, 10.5, C_TEXT_FAINT);
            let m = ui.mouse();
            let over = pv.contains(m) && !ui.blocked && ui.popup.is_none();
            if over && ui.active == 0 && ui.inp.l_pressed {
                if ui.inp.l_double {
                    self.mesh_yaw = 0.0;
                    self.mesh_pitch = 0.0;
                    self.mesh_zoom = 1.0;
                } else {
                    self.mesh_orbit = true;
                    ui.active = hid("meshpreview");
                }
            }
            if self.mesh_orbit {
                if ui.inp.l_down {
                    let d = m - self.graph_mouse_prev_mesh;
                    self.mesh_yaw -= d.x * 0.01;
                    self.mesh_pitch = (self.mesh_pitch + d.y * 0.01).clamp(-1.5, 1.5);
                } else {
                    self.mesh_orbit = false;
                }
            }
            if over && ui.inp.wheel != 0.0 {
                self.mesh_zoom = (self.mesh_zoom * 0.88f32.powf(ui.inp.wheel)).clamp(0.2, 5.0);
            }
            self.graph_mouse_prev_mesh = m;
        }
        self.mesh_preview_aspect = pv.w / pv.h.max(1.0);
        y = pv.y + pv.h + 6.0;

        // ---- Show / Alignment / counts
        ui.text("Show", x0, y + 4.0, 12.0, C_TEXT_DIM);
        let shows: Vec<String> = LOD_NAMES.iter().map(|s| s.to_string()).collect();
        let mut show = self.mesh_lod.min(2);
        if ui.combo("mesh.show", Rect::new(x0 + 36.0, y, 70.0, 22.0), &shows, &mut show) {
            self.mesh_lod = show;
        }
        if ui.hover(Rect::new(x0 + 36.0, y, 70.0, 22.0)) {
            ui.tooltip = Some("Choose which LOD mesh is displayed.".into());
        }
        let ar = Rect::new(x0 + 116.0, y, 100.0, 22.0);
        ui.checkbox("mesh.align", ar, &mut self.show_alignment);
        ui.text("Alignment", ar.x + 20.0, y + 4.0, 12.0, C_TEXT);
        if ui.hover(ar) {
            ui.tooltip = Some("Show the intended orientation: use Orient and Flip to match it.".into());
        }
        let (nv, nf) = meshio::processed_geom(&self.meshes, cur, self.mesh_lod).map(|g| (g.pos.len(), g.tris())).unwrap_or((0, 0));
        let vf = format!("V:{} F:{}", nv, nf);
        let vw = ui.text_w(&vf, 12.0);
        ui.text(&vf, x0 + w - vw, y + 4.0, 12.0, C_TEXT_DIM);
        ui.record("mesh.vf", Rect::new(x0 + w - vw, y, vw, 20.0));
        y += 28.0;

        // ---- two columns of settings
        let cw = (w - 8.0) * 0.5;
        let lx = x0;
        let rx = x0 + cw + 8.0;
        let mut changed = false;
        let m = &mut self.meshes[cur];
        // Transform
        group_box(ui, Rect::new(lx, y, cw, 104.0), "Transform");
        let lab_w = 62.0;
        let row = |ui: &mut Ui, x: f32, yy: f32, label: &str| {
            let tw = ui.text_w(label, 12.0);
            ui.text(label, x + lab_w - tw - 6.0, yy + 4.0, 12.0, C_TEXT_DIM);
        };
        let mut yy = y + 16.0;
        row(ui, lx, yy, "Orient");
        let orients: Vec<String> = ORIENTS.iter().map(|o| o.0.to_string()).collect();
        let fr = Rect::new(lx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.orient", fr, &orients, &mut m.orient);
        if ui.hover(fr) {
            ui.tooltip = Some("Reorient the mesh, if necessary (convert coordinate systems).".into());
        }
        yy += 25.0;
        row(ui, lx, yy, "Flip");
        let flips: Vec<String> = FLIPS.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(lx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.flip", fr, &flips, &mut m.flip);
        if ui.hover(fr) {
            ui.tooltip = Some("Flip the model around the specified axis.".into());
        }
        yy += 25.0;
        let cb = Rect::new(lx + 6.0, yy, cw * 0.5 - 6.0, 18.0);
        changed |= ui.checkbox("mesh.flipnormals", cb, &mut m.flip_normals);
        ui.text("Flip normals", cb.x + 20.0, yy + 2.0, 12.0, C_TEXT);
        if ui.hover(cb) {
            ui.tooltip = Some("Make the model's normals point in the opposite direction.".into());
        }
        let cb = Rect::new(lx + cw * 0.5, yy, cw * 0.5 - 6.0, 18.0);
        changed |= ui.checkbox("mesh.fixwinding", cb, &mut m.fix_winding);
        ui.text("Fix winding", cb.x + 20.0, yy + 2.0, 12.0, C_TEXT);
        if ui.hover(cb) {
            ui.tooltip = Some("Make each face's winding match its normals.".into());
        }
        // Collection
        let cy = y + 110.0;
        group_box(ui, Rect::new(lx, cy, cw, 84.0), "");
        let cb = Rect::new(lx + 6.0, cy + 2.0, cw - 12.0, 18.0);
        changed |= ui.checkbox("mesh.collection", cb, &mut m.collection);
        ui.text("Collection", cb.x + 20.0, cy + 4.0, 12.0, C_TEXT);
        if ui.hover(cb) {
            ui.tooltip = Some("Build this mesh from generators marked \"Contribute to collections\".".into());
        }
        let on = m.collection;
        let mut yy = cy + 26.0;
        row(ui, lx, yy, "Spines");
        let sp: Vec<String> = SPINE_STYLES.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(lx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.spines", fr, &sp, &mut m.spine_style);
        if !on {
            draw_rectangle(fr.x, fr.y, fr.w, fr.h, Color::new(0.23, 0.23, 0.23, 0.6));
        }
        yy += 25.0;
        row(ui, lx, yy, "Pivot");
        let pvs: Vec<String> = PIVOT_STYLES.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(lx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.pivot", fr, &pvs, &mut m.pivot_style);
        if !on {
            draw_rectangle(fr.x, fr.y, fr.w, fr.h, Color::new(0.23, 0.23, 0.23, 0.6));
        }
        if ui.hover(fr) {
            ui.tooltip = Some("Origin: lie on the original geometry. First: relative to the first collected object.".into());
        }
        // Wind direction
        group_box(ui, Rect::new(rx, y, cw, 70.0), "Wind direction");
        let mut yy = y + 16.0;
        row(ui, rx, yy, "Growth");
        let gs: Vec<String> = GROWTHS.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(rx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.growth", fr, &gs, &mut m.growth);
        if ui.hover(fr) {
            ui.tooltip = Some("Specifies the axis that will align with the wind direction (and grows along the leaf).".into());
        }
        yy += 25.0;
        row(ui, rx, yy, "Ripple");
        let rs: Vec<String> = RIPPLES.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(rx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.ripple", fr, &rs, &mut m.ripple);
        if ui.hover(fr) {
            ui.tooltip = Some("Specifies the vector along which rippling will occur.".into());
        }
        // Proxy collision
        let py = y + 78.0;
        group_box(ui, Rect::new(rx, py, cw, 70.0), "Proxy collision");
        let mut yy = py + 16.0;
        row(ui, rx, yy, "Scale");
        let fr = Rect::new(rx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.slider("mesh.colscale", fr, &mut m.collision_scale, 0.0, 10.0, 2);
        if ui.hover(fr) {
            ui.tooltip = Some("Multiplies the collision distance for each instance of this mesh.".into());
        }
        yy += 25.0;
        row(ui, rx, yy, "Weight");
        let fr = Rect::new(rx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.slider("mesh.weight", fr, &mut m.weight, 0.0, 10.0, 2);
        if ui.hover(fr) {
            ui.tooltip = Some("Multiplies the likelihood that this mesh is chosen when it collides with another.".into());
        }
        if changed {
            self.dirty = true;
        }
    }

    fn remove_mesh(&mut self, cur: usize) {
        if self.meshes.is_empty() {
            return;
        }
        self.meshes.remove(cur);
        for n in &mut self.nodes {
            if n.p.leaf_mesh == cur + 1 {
                n.p.leaf_mesh = 0;
            } else if n.p.leaf_mesh > cur + 1 {
                n.p.leaf_mesh -= 1;
            }
        }
        for m in &mut self.meshes {
            if m.more == cur + 1 {
                m.more = 0;
            } else if m.more > cur + 1 {
                m.more -= 1;
            }
        }
        self.mesh_cur = 0;
        self.mesh_lod = 0;
        self.select(Sel::None);
        self.dirty = true;
    }

    fn pick_mesh_file() -> Option<String> {
        rfd::FileDialog::new().add_filter("Mesh (OBJ)", &["obj"]).pick_file().map(|p| p.to_string_lossy().to_string())
    }

    fn add_mesh_from_file(&mut self) {
        if let Some(f) = Self::pick_mesh_file() {
            match meshio::load_obj(&f) {
                Ok(g) => {
                    let name = std::path::Path::new(&f).file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or("Mesh".into());
                    let mut m = LeafMesh::card(&name);
                    m.lods[0] = MeshLod { file: f, outline: vec![], geom: Some(g) };
                    m.ref_material = self.mat_cur.min(self.materials.len().saturating_sub(1));
                    self.meshes.push(m);
                    self.mesh_lod = 0;
                    self.select(Sel::Mesh(self.meshes.len() - 1));
                    self.set_status(&format!("Added mesh \"{}\"", name));
                }
                Err(e) => self.set_status(&format!("Couldn't read that mesh: {}", e)),
            }
        }
    }

    fn browse_lod(&mut self, cur: usize, l: usize) {
        if let Some(f) = Self::pick_mesh_file() {
            match meshio::load_obj(&f) {
                Ok(g) => {
                    self.meshes[cur].lods[l] = MeshLod { file: f, outline: vec![], geom: Some(g) };
                    self.mesh_lod = l;
                    self.dirty = true;
                }
                Err(e) => self.set_status(&format!("Couldn't read that mesh: {}", e)),
            }
        }
    }

    fn reload_lod(&mut self, cur: usize, l: usize) {
        let file = self.meshes[cur].lods[l].file.clone();
        if file.is_empty() {
            self.set_status("This level is a cutout; there is no file to reload");
            return;
        }
        match meshio::load_obj(&file) {
            Ok(g) => {
                self.meshes[cur].lods[l].geom = Some(g);
                self.dirty = true;
                self.set_status("Reloaded");
            }
            Err(e) => self.set_status(&format!("Couldn't reload: {}", e)),
        }
    }

    fn export_lod(&mut self, cur: usize, l: usize) {
        let g = match meshio::processed_geom(&self.meshes, cur, l) {
            Some(g) => g,
            None => {
                self.set_status("This level is empty");
                return;
            }
        };
        let name = format!("{}_{}.obj", self.meshes[cur].name.replace(' ', "_"), LOD_NAMES[l]);
        if let Some(p) = rfd::FileDialog::new().add_filter("Mesh (OBJ)", &["obj"]).set_file_name(&name).save_file() {
            match meshio::save_obj(&p.to_string_lossy(), &g) {
                Ok(()) => self.set_status("Mesh exported"),
                Err(e) => self.set_status(&format!("Couldn't export: {}", e)),
            }
        }
    }

    /// Dropping a mesh on the model: the selected leaf generator uses it (or the first one).
    pub fn drop_mesh_on_model(&mut self, cur: usize) {
        let target = match self.sel {
            Sel::Node(id) if self.node(id).map(|n| n.kind == Kind::Leaf).unwrap_or(false) => Some(id),
            _ => self.nodes.iter().find(|n| n.kind == Kind::Leaf).map(|n| n.id),
        };
        match target {
            Some(id) => {
                let name = self.meshes[cur].name.clone();
                if let Some(n) = self.nodes.iter_mut().find(|n| n.id == id) {
                    n.p.leaf_mesh = cur + 1;
                    let nn = n.name.clone();
                    self.set_status(&format!("\"{}\" now uses mesh \"{}\"", nn, name));
                }
                self.dirty = true;
            }
            None => self.set_status("Add a Leaf generator first"),
        }
    }

    /// The cutout editor ("Edit Mesh..."): outline points and anchor over the reference picture.
    fn draw_cutout_editor(&mut self, ui: &mut Ui, area: Rect, cur: usize) {
        let lod = self.mesh_lod.min(2);
        draw_rectangle(area.x, area.y, area.w, area.h, C_BG);
        let title = format!("Cutout editor: {} level", LOD_NAMES[lod]);
        ui.text(&title, area.x + 6.0, area.y + 4.0, 12.0, C_TEXT);
        if self.meshes[cur].lods[lod].geom.is_some() {
            ui.text("This level comes from a mesh file.", area.x + 6.0, area.y + 30.0, 12.5, C_TEXT_DIM);
            if ui.button("mesh.tocutout", Rect::new(area.x + 6.0, area.y + 52.0, 170.0, 24.0), "Replace with a cutout") {
                self.meshes[cur].lods[lod] = MeshLod { file: String::new(), outline: card_outline(), geom: None };
                self.dirty = true;
            }
            return;
        }
        if self.meshes[cur].lods[lod].outline.len() < 3 {
            ui.text("This level is empty.", area.x + 6.0, area.y + 30.0, 12.5, C_TEXT_DIM);
            if ui.button("mesh.fromhigh", Rect::new(area.x + 6.0, area.y + 52.0, 210.0, 24.0), "Make it from High (fewer points)") {
                let src = self.meshes[cur].lods[0].outline.clone();
                if src.len() >= 3 {
                    let n = (src.len() * if lod == 1 { 2 } else { 1 } / 3).max(3);
                    self.meshes[cur].lods[lod].outline = textures::reduce_outline(src, n);
                } else {
                    self.meshes[cur].lods[lod].outline = card_outline();
                }
                self.dirty = true;
            }
            return;
        }
        let avail = Rect::new(area.x + 6.0, area.y + 22.0, area.w - 12.0, area.h - 44.0);
        let side = avail.w.min(avail.h).max(40.0);
        let cv = Rect::new(avail.x + (avail.w - side) * 0.5, avail.y, side, side);
        checker(cv, 16.0);
        let refm = self.meshes[cur].ref_material;
        if let Some(t) = self.materials.get(refm).and_then(|m| m.tex.as_ref()) {
            draw_texture_ex(t, cv.x, cv.y, WHITE, DrawTextureParams { dest_size: Some(vec2(cv.w, cv.h)), ..Default::default() });
        }
        let to_s = |p: Vec2| vec2(cv.x + p.x * cv.w, cv.y + p.y * cv.h);
        let to_uv = |s: Vec2| vec2((s.x - cv.x) / cv.w, (s.y - cv.y) / cv.h);
        let poly = self.meshes[cur].lods[lod].outline.clone();
        for tri in textures::triangulate(&poly) {
            let a = to_s(poly[tri[0]]);
            let b = to_s(poly[tri[1]]);
            let c = to_s(poly[tri[2]]);
            draw_triangle(a, b, c, Color::new(0.85, 0.59, 0.28, 0.10));
            draw_line(a.x, a.y, b.x, b.y, 1.0, Color::new(1.0, 1.0, 1.0, 0.15));
            draw_line(b.x, b.y, c.x, c.y, 1.0, Color::new(1.0, 1.0, 1.0, 0.15));
        }
        for k in 0..poly.len() {
            let a = to_s(poly[k]);
            let b = to_s(poly[(k + 1) % poly.len()]);
            draw_line(a.x, a.y, b.x, b.y, 2.0, C_ORANGE);
        }
        let m = ui.mouse();
        let mut hover_pt: Option<i32> = None;
        let anc = to_s(self.meshes[cur].anchor);
        if anc.distance(m) < 9.0 {
            hover_pt = Some(-1);
        }
        for (k, p) in poly.iter().enumerate() {
            if to_s(*p).distance(m) < 7.0 {
                hover_pt = Some(k as i32);
            }
        }
        for (k, p) in poly.iter().enumerate() {
            let s = to_s(*p);
            let hot = hover_pt == Some(k as i32) || self.mesh_drag == Some(k as i32);
            draw_rectangle(s.x - 4.0, s.y - 4.0, 8.0, 8.0, if hot { WHITE } else { C_ORANGE });
            draw_rectangle_lines(s.x - 4.0, s.y - 4.0, 8.0, 8.0, 1.0, Color::new(0.0, 0.0, 0.0, 0.6));
        }
        let green = Color::new(0.3, 0.95, 0.4, 1.0);
        draw_circle_lines(anc.x, anc.y, 7.0, 2.0, green);
        draw_line(anc.x - 11.0, anc.y, anc.x + 11.0, anc.y, 1.0, green);
        draw_line(anc.x, anc.y - 11.0, anc.x, anc.y + 11.0, 1.0, green);
        ui.text("anchor", anc.x + 9.0, anc.y + 4.0, 10.5, green);

        let inp = ui.inp.clone();
        let over = cv.contains(m) && !ui.blocked && ui.popup.is_none();
        let mut changed = false;
        if over && ui.active == 0 {
            if inp.l_double && hover_pt.is_none() {
                let uv = to_uv(m);
                let mut best = (f32::MAX, 0usize);
                for k in 0..poly.len() {
                    let a = poly[k];
                    let b = poly[(k + 1) % poly.len()];
                    let ab = b - a;
                    let t = ((uv - a).dot(ab) / ab.length_squared().max(1e-9)).clamp(0.0, 1.0);
                    let d = (a + ab * t).distance(uv);
                    if d < best.0 {
                        best = (d, k);
                    }
                }
                self.meshes[cur].lods[lod].outline.insert(best.1 + 1, uv);
                changed = true;
            } else if inp.l_pressed {
                if let Some(h) = hover_pt {
                    self.mesh_drag = Some(h);
                    ui.active = hid("meshcanvas");
                }
            } else if inp.r_pressed {
                if let Some(h) = hover_pt {
                    if h >= 0 && poly.len() > 3 {
                        self.meshes[cur].lods[lod].outline.remove(h as usize);
                        changed = true;
                    }
                }
            }
        }
        if let Some(h) = self.mesh_drag {
            if inp.l_down {
                let uv = to_uv(m);
                let uv = vec2(uv.x.clamp(-0.1, 1.1), uv.y.clamp(-0.1, 1.1));
                if h < 0 {
                    self.meshes[cur].anchor = vec2(uv.x.clamp(0.0, 1.0), uv.y.clamp(0.0, 1.0));
                } else if (h as usize) < self.meshes[cur].lods[lod].outline.len() {
                    self.meshes[cur].lods[lod].outline[h as usize] = uv;
                }
                changed = true;
            } else {
                self.mesh_drag = None;
            }
        }
        if changed {
            self.dirty = true;
            if self.sel != Sel::Mesh(cur) {
                self.sel = Sel::Mesh(cur);
            }
        }
        ui.text_fit(
            "Drag points or the green anchor • double-click an edge to add • right-click a point to remove",
            area.x + 6.0,
            area.y + area.h - 18.0,
            area.w - 12.0,
            10.5,
            C_TEXT_FAINT,
        );
    }

    /// Render the selected mesh into the Meshes tab's preview picture (before the UI pass).
    pub fn render_mesh_preview(&mut self) {
        if self.tab != 2 || self.mesh_editing || self.meshes.is_empty() {
            return;
        }
        let gm = match &self.gm {
            Some(g) => g,
            None => return,
        };
        let rt = self.mesh_rt.get_or_insert_with(|| {
            let r = render_target_ex(640, 512, RenderTargetParams { depth: true, ..Default::default() });
            r.texture.set_filter(FilterMode::Linear);
            r
        });
        let cur = self.mesh_cur.min(self.meshes.len() - 1);
        let g = meshio::processed_geom(&self.meshes, cur, self.mesh_lod);
        let (bmin, bmax) = g.as_ref().map(meshio::bounds).unwrap_or((Vec3::splat(-0.5), Vec3::splat(0.5)));
        let center = (bmin + bmax) * 0.5;
        let radius = ((bmax - bmin).length() * 0.5).max(0.05);
        let cam = Cam {
            yaw: self.mesh_yaw,
            pitch: self.mesh_pitch,
            dist: radius / (20.0f32.to_radians()).sin() * 1.15 * self.mesh_zoom,
            target: center,
            ortho: false,
            view: 0,
            fov: 40.0,
        };
        let c3 = cam.camera3d(None, self.mesh_preview_aspect.max(0.2), Some(rt.clone()));
        set_camera(&c3);
        clear_background(Color::new(0.0, 0.0, 0.0, 0.0));
        if let Some(g) = &g {
            let refm = self.meshes[cur].ref_material;
            let fallback = Material::new("?", 0);
            let mat = self.materials.get(refm).unwrap_or(&fallback);
            let verts: Vec<macroquad::models::Vertex> = g
                .pos
                .iter()
                .enumerate()
                .map(|(i, p)| macroquad::models::Vertex {
                    position: *p,
                    uv: g.uv[i],
                    color: [255; 4],
                    normal: vec4(g.nrm[i].x, g.nrm[i].y, g.nrm[i].z, 1.0),
                })
                .collect();
            let idx: Vec<u16> = g.idx.iter().map(|&i| i as u16).collect();
            gl_use_material(gm);
            render::apply_material(gm, mat, &self.light, cam.position());
            draw_mesh(&Mesh { vertices: verts, indices: idx, texture: mat.tex.clone() });
            unsafe { get_internal_gl() }.flush();
            gl_use_default_material();
        }
        // axes at the mesh origin (the attachment point), growth axis in yellow
        let len = radius * 1.2;
        draw_line_3d(Vec3::ZERO, Vec3::X * len, Color::new(0.9, 0.35, 0.35, 1.0));
        draw_line_3d(Vec3::ZERO, Vec3::Y * len, Color::new(0.4, 0.85, 0.4, 1.0));
        draw_line_3d(Vec3::ZERO, Vec3::Z * len, Color::new(0.4, 0.55, 1.0, 1.0));
        let ga = meshio::growth_axis(self.meshes[cur].growth) * len * 1.1;
        draw_line_3d(Vec3::ZERO, ga, Color::new(1.0, 0.85, 0.2, 1.0));
        if self.show_alignment {
            // the intended orientation: a leaf lying in X/Y, growing up +Y from the origin, facing +Z
            let s = radius * 1.6;
            let mut prev: Option<Vec3> = None;
            let shape: Vec<Vec3> = (0..=24)
                .map(|i| {
                    let t = i as f32 / 24.0;
                    let a = t * std::f32::consts::TAU;
                    let yv = (1.0 - a.cos()) * 0.5;
                    vec3(a.sin() * 0.35 * (1.0 - yv * 0.4), yv, 0.0) * s
                })
                .collect();
            for p in shape {
                if let Some(q) = prev {
                    draw_line_3d(q, p, Color::new(1.0, 1.0, 1.0, 0.7));
                }
                prev = Some(p);
            }
            draw_line_3d(Vec3::ZERO, Vec3::Y * s, Color::new(1.0, 1.0, 1.0, 0.5));
        }
        set_default_camera();
    }
}

fn group_box(ui: &mut Ui, r: Rect, title: &str) {
    draw_rectangle_lines(r.x, r.y + 6.0, r.w, r.h - 6.0, 1.0, Color::new(1.0, 1.0, 1.0, 0.14));
    if !title.is_empty() {
        let tw = ui.text_w(title, 12.0);
        draw_rectangle(r.x + 6.0, r.y, tw + 8.0, 12.0, C_PANEL);
        ui.text(title, r.x + 10.0, r.y - 1.0, 12.0, C_TEXT_DIM);
    }
}

fn icon_hand(r: Rect) {
    let c = Color::new(1.0, 1.0, 1.0, 0.85);
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    draw_rectangle(cx - 6.0, cy - 1.0, 12.0, 9.0, c);
    for (i, h) in [6.0f32, 9.0, 9.0, 7.0].iter().enumerate() {
        draw_rectangle(cx - 6.0 + i as f32 * 3.2, cy - 1.0 - h, 2.4, *h, c);
    }
    draw_rectangle(cx + 5.0, cy - 2.0, 4.0, 2.4, c);
}

fn icon_reload(r: Rect) {
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    let c = Color::new(1.0, 1.0, 1.0, 0.8);
    let mut prev: Option<Vec2> = None;
    for i in 0..=14 {
        let a = 0.6 + i as f32 / 14.0 * 5.0;
        let p = vec2(cx + a.cos() * 6.0, cy + a.sin() * 6.0);
        if let Some(q) = prev {
            draw_line(q.x, q.y, p.x, p.y, 1.5, c);
        }
        prev = Some(p);
    }
    let tip = vec2(cx + 0.6f32.cos() * 6.0, cy + 0.6f32.sin() * 6.0);
    draw_triangle(tip + vec2(-3.0, -3.0), tip + vec2(3.0, -1.0), tip + vec2(0.0, 3.0), c);
}

fn icon_export(r: Rect) {
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    let c = Color::new(1.0, 1.0, 1.0, 0.8);
    draw_rectangle_lines(cx - 2.0, cy - 6.0, 8.0, 12.0, 1.2, c);
    draw_line(cx - 8.0, cy, cx + 1.0, cy, 1.5, c);
    draw_triangle(vec2(cx + 3.0, cy), vec2(cx - 1.0, cy - 3.5), vec2(cx - 1.0, cy + 3.5), c);
}

fn icon_clipboard(r: Rect) {
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    let c = Color::new(1.0, 1.0, 1.0, 0.85);
    draw_rectangle_lines(cx - 5.0, cy - 6.0, 10.0, 13.0, 1.3, c);
    draw_rectangle(cx - 2.5, cy - 7.5, 5.0, 3.0, c);
    draw_line(cx - 3.0, cy - 1.0, cx + 3.0, cy - 1.0, 1.0, c);
    draw_line(cx - 3.0, cy + 2.0, cx + 3.0, cy + 2.0, 1.0, c);
}

toolUseResult.content:
    // ------------------------------------------------------------------ meshes
    /// The Meshes tab, laid out like the original's Meshes panel (fn 0x140076fd0 in 8.4.2):
    /// drag handle, mesh picker, +/-, +, copy/paste; Geometry (Edit Mesh..., High/Med/Low
    /// files, More); preview; Show / Alignment / V:F; Transform; Collection; Wind direction;
    /// Proxy collision.
    fn draw_meshes(&mut self, ui: &mut Ui, tb: Rect, body: Rect) {
        let r = Rect::new(tb.x, tb.y, tb.w, body.y + body.h - tb.y);
        let x0 = r.x + 8.0;
        let w = r.w - 16.0;
        let mut y = r.y + 4.0;

        // ---- top row
        let hand = Rect::new(x0, y, 30.0, 30.0);
        ui.record("btn:mesh.drag", hand);
        let hot = ui.hover(hand);
        draw_rectangle(hand.x, hand.y, hand.w, hand.h, if hot || self.hand_drag { C_BTN_HOT } else { C_BTN });
        icon_hand(hand);
        if hot {
            ui.tooltip = Some("Drag this mesh and drop it on the model to use it.".into());
            if ui.inp.l_pressed && !self.meshes.is_empty() {
                self.hand_drag = true;
                ui.active = hid("mesh.drag");
            }
        }
        let bw = 34.0;
        let combo_w = (w - 36.0 - (bw + 4.0) * 3.0).max(60.0);
        let names: Vec<String> = if self.meshes.is_empty() { vec!["No meshes".into()] } else { self.meshes.iter().map(|m| m.name.clone()).collect() };
        let mut cur = self.mesh_cur.min(self.meshes.len().saturating_sub(1));
        let cr = Rect::new(x0 + 36.0, y + 4.0, combo_w, 22.0);
        if ui.combo("mesh.pick", cr, &names, &mut cur) && !self.meshes.is_empty() {
            self.mesh_lod = 0;
            self.select(Sel::Mesh(cur));
        }
        if ui.hover(cr) {
            ui.tooltip = Some("Select a mesh to edit. Meshes are used as leaf geometry.".into());
        }
        let bx = cr.x + cr.w + 4.0;
        let r1 = Rect::new(bx, y + 4.0, bw, 22.0);
        if ui.button("mesh.addremove", r1, "+/-") {
            ui.open_popup(hid("mesh.addremove"), r1, vec!["Add mesh (card)".into(), "Add cutout from reference material".into(), "Remove this mesh".into()], None);
        }
        if ui.hover(r1) {
            ui.tooltip = Some("Manage the meshes.".into());
        }
        let r2 = Rect::new(bx + bw + 4.0, y + 4.0, bw, 22.0);
        if ui.button("mesh.browseadd", r2, "+") {
            self.add_mesh_from_file();
        }
        if ui.hover(r2) {
            ui.tooltip = Some("Browse for a mesh and add it to the list automatically...".into());
        }
        let r3 = Rect::new(bx + (bw + 4.0) * 2.0, y + 4.0, bw, 22.0);
        if ui.button("mesh.copypaste", r3, "") {
            ui.open_popup(hid("mesh.copypaste"), r3, vec!["Copy".into(), "Paste".into(), "Duplicate".into()], None);
        }
        icon_clipboard(r3);
        if ui.hover(r3) {
            ui.tooltip = Some("Copy/Paste menu...".into());
        }
        if let Some(i) = ui.take_popup_result("mesh.addremove") {
            match i {
                0 | 1 => {
                    let mut m = LeafMesh::card(&format!("Mesh {}", self.meshes.len() + 1));
                    m.ref_material = self.mat_cur.min(self.materials.len().saturating_sub(1));
                    if i == 1 {
                        if let Some(img) = self.materials.get(m.ref_material).and_then(|x| x.adjusted.clone()) {
                            m.lods[0].outline = textures::auto_cutout(&img, m.auto_points as usize, m.threshold, m.margin);
                        }
                    }
                    self.meshes.push(m);
                    self.mesh_lod = 0;
                    self.select(Sel::Mesh(self.meshes.len() - 1));
                }
                _ => self.remove_mesh(cur),
            }
        }
        if let Some(i) = ui.take_popup_result("mesh.copypaste") {
            if !self.meshes.is_empty() {
                match i {
                    0 => {
                        self.mesh_clip = Some(self.meshes[cur].clone());
                        self.set_status("Mesh copied");
                    }
                    1 => match self.mesh_clip.clone() {
                        Some(mut m) => {
                            m.name = self.meshes[cur].name.clone();
                            self.meshes[cur] = m;
                            self.dirty = true;
                            self.set_status("Mesh pasted");
                        }
                        None => self.set_status("Nothing copied yet"),
                    },
                    _ => {
                        let mut m = self.meshes[cur].clone();
                        m.name = format!("{} copy", m.name);
                        self.meshes.push(m);
                        self.select(Sel::Mesh(self.meshes.len() - 1));
                    }
                }
            }
        }
        // drag-and-drop the mesh onto the model
        if self.hand_drag {
            if ui.inp.l_down {
                if let Some(m) = self.meshes.get(cur) {
                    ui.tooltip = Some(format!("Drop on the viewport to use \"{}\" for the leaves", m.name));
                }
            } else {
                self.hand_drag = false;
                if self.viewport.contains(ui.mouse()) && !self.meshes.is_empty() {
                    self.drop_mesh_on_model(cur);
                }
            }
        }
        y += 38.0;
        if self.meshes.is_empty() {
            ui.text("No meshes. Use +/- to add one, or + to load a mesh file.", x0, y + 6.0, 12.5, C_TEXT_FAINT);
            return;
        }
        self.mesh_cur = cur;

        // ---- Geometry
        ui.text("Geometry", x0, y, 12.0, C_TEXT_DIM);
        y += 17.0;
        let lw = 40.0;
        let er = Rect::new(x0 + lw, y, w - lw - 90.0, 22.0);
        let label = if self.mesh_editing { "Done editing" } else { "Edit Mesh..." };
        if ui.button_ex("mesh.edit", er, label, self.mesh_editing, true) {
            self.mesh_editing = !self.mesh_editing;
        }
        y += 26.0;
        for l in 0..3 {
            let lab = LOD_NAMES[l];
            let tw = ui.text_w(lab, 12.0);
            ui.text(lab, x0 + lw - tw - 6.0, y + 4.0, 12.0, C_TEXT_DIM);
            let fr = Rect::new(x0 + lw, y, w - lw - 90.0, 22.0);
            let selected = self.mesh_lod == l;
            draw_rectangle(fr.x, fr.y, fr.w, fr.h, C_FIELD);
            if selected {
                draw_rectangle_lines(fr.x, fr.y, fr.w, fr.h, 1.0, C_ACCENT2);
            }
            let lod = &self.meshes[cur].lods[l];
            let desc = if self.meshes[cur].collection {
                "(collection)".to_string()
            } else if !lod.file.is_empty() {
                std::path::Path::new(&lod.file).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default()
            } else if lod.outline.len() >= 3 {
                format!("cutout, {} points", lod.outline.len())
            } else {
                String::new()
            };
            ui.text_fit(&desc, fr.x + 6.0, fr.y + 4.0, fr.w - 10.0, 12.0, C_TEXT);
            ui.record(&format!("mesh.lodfield.{}", l), fr);
            if ui.clicked(fr) {
                self.mesh_lod = l;
            }
            let b1 = Rect::new(fr.x + fr.w + 4.0, y, 26.0, 22.0);
            if ui.button(&format!("mesh.browse{}", l), b1, "...") {
                self.browse_lod(cur, l);
            }
            if ui.hover(b1) {
                ui.tooltip = Some(format!("Browse for the {} mesh file...", lab.to_lowercase()));
            }
            let b2 = Rect::new(b1.x + 30.0, y, 26.0, 22.0);
            if ui.button(&format!("mesh.reload{}", l), b2, "") {
                self.reload_lod(cur, l);
            }
            icon_reload(b2);
            if ui.hover(b2) {
                ui.tooltip = Some("Reload this mesh.".into());
            }
            let b3 = Rect::new(b2.x + 30.0, y, 26.0, 22.0);
            if ui.button(&format!("mesh.export{}", l), b3, "") {
                self.export_lod(cur, l);
            }
            icon_export(b3);
            if ui.hover(b3) {
                ui.tooltip = Some("Export this mesh...".into());
            }
            y += 25.0;
        }
        {
            let tw = ui.text_w("More", 12.0);
            ui.text("More", x0 + lw - tw - 6.0, y + 4.0, 12.0, C_TEXT_DIM);
            let mut more_names = vec!["None".to_string()];
            for (i, m) in self.meshes.iter().enumerate() {
                more_names.push(if i == cur { format!("{} (this mesh)", m.name) } else { m.name.clone() });
            }
            let mut more = self.meshes[cur].more.min(more_names.len() - 1);
            let mr = Rect::new(x0 + lw, y, w - lw - 90.0, 22.0);
            if ui.combo("mesh.more", mr, &more_names, &mut more) {
                if more == cur + 1 {
                    self.set_status("A mesh can't supply its own extra levels");
                } else {
                    self.meshes[cur].more = more;
                    self.dirty = true;
                }
            }
            if ui.hover(mr) {
                ui.tooltip = Some("Another mesh whose levels continue this one's (LOD 3 and lower).".into());
            }
            y += 28.0;
        }

        // ---- preview / cutout editor
        let bottom_h = 232.0;
        let pv = Rect::new(x0, y, w, (r.y + r.h - bottom_h - y).max(90.0));
        ui.record("meshcanvas", pv);
        if self.mesh_editing {
            self.draw_cutout_editor(ui, pv, cur);
        } else {
            checker(pv, 12.0);
            if let Some(rt) = &self.mesh_rt {
                draw_texture_ex(&rt.texture, pv.x, pv.y, WHITE, DrawTextureParams { dest_size: Some(vec2(pv.w, pv.h)), flip_y: true, ..Default::default() });
            }
            draw_rectangle_lines(pv.x, pv.y, pv.w, pv.h, 1.0, C_LINE);
            ui.text("drag to turn • wheel to zoom • double-click to reset", pv.x + 6.0, pv.y + pv.h - 16.0, 10.5, C_TEXT_FAINT);
            let m = ui.mouse();
            let over = pv.contains(m) && !ui.blocked && ui.popup.is_none();
            if over && ui.active == 0 && ui.inp.l_pressed {
                if ui.inp.l_double {
                    self.mesh_yaw = 0.0;
                    self.mesh_pitch = 0.0;
                    self.mesh_zoom = 1.0;
                } else {
                    self.mesh_orbit = true;
                    ui.active = hid("meshpreview");
                }
            }
            if self.mesh_orbit {
                if ui.inp.l_down {
                    let d = m - self.graph_mouse_prev_mesh;
                    self.mesh_yaw -= d.x * 0.01;
                    self.mesh_pitch = (self.mesh_pitch + d.y * 0.01).clamp(-1.5, 1.5);
                } else {
                    self.mesh_orbit = false;
                }
            }
            if over && ui.inp.wheel != 0.0 {
                self.mesh_zoom = (self.mesh_zoom * 0.88f32.powf(ui.inp.wheel)).clamp(0.2, 5.0);
            }
            self.graph_mouse_prev_mesh = m;
        }
        self.mesh_preview_aspect = pv.w / pv.h.max(1.0);
        y = pv.y + pv.h + 6.0;

        // ---- Show / Alignment / counts
        ui.text("Show", x0, y + 4.0, 12.0, C_TEXT_DIM);
        let shows: Vec<String> = LOD_NAMES.iter().map(|s| s.to_string()).collect();
        let mut show = self.mesh_lod.min(2);
        if ui.combo("mesh.show", Rect::new(x0 + 36.0, y, 70.0, 22.0), &shows, &mut show) {
            self.mesh_lod = show;
        }
        if ui.hover(Rect::new(x0 + 36.0, y, 70.0, 22.0)) {
            ui.tooltip = Some("Choose which LOD mesh is displayed.".into());
        }
        let ar = Rect::new(x0 + 116.0, y, 100.0, 22.0);
        ui.checkbox("mesh.align", ar, &mut self.show_alignment);
        ui.text("Alignment", ar.x + 20.0, y + 4.0, 12.0, C_TEXT);
        if ui.hover(ar) {
            ui.tooltip = Some("Show the intended orientation: use Orient and Flip to match it.".into());
        }
        let (nv, nf) = meshio::processed_geom(&self.meshes, cur, self.mesh_lod).map(|g| (g.pos.len(), g.tris())).unwrap_or((0, 0));
        let vf = format!("V:{} F:{}", nv, nf);
        let vw = ui.text_w(&vf, 12.0);
        ui.text(&vf, x0 + w - vw, y + 4.0, 12.0, C_TEXT_DIM);
        ui.record("mesh.vf", Rect::new(x0 + w - vw, y, vw, 20.0));
        y += 28.0;

        // ---- two columns of settings
        let cw = (w - 8.0) * 0.5;
        let lx = x0;
        let rx = x0 + cw + 8.0;
        let mut changed = false;
        let m = &mut self.meshes[cur];
        // Transform
        group_box(ui, Rect::new(lx, y, cw, 104.0), "Transform");
        let lab_w = 62.0;
        let row = |ui: &mut Ui, x: f32, yy: f32, label: &str| {
            let tw = ui.text_w(label, 12.0);
            ui.text(label, x + lab_w - tw - 6.0, yy + 4.0, 12.0, C_TEXT_DIM);
        };
        let mut yy = y + 16.0;
        row(ui, lx, yy, "Orient");
        let orients: Vec<String> = ORIENTS.iter().map(|o| o.0.to_string()).collect();
        let fr = Rect::new(lx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.orient", fr, &orients, &mut m.orient);
        if ui.hover(fr) {
            ui.tooltip = Some("Reorient the mesh, if necessary (convert coordinate systems).".into());
        }
        yy += 25.0;
        row(ui, lx, yy, "Flip");
        let flips: Vec<String> = FLIPS.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(lx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.flip", fr, &flips, &mut m.flip);
        if ui.hover(fr) {
            ui.tooltip = Some("Flip the model around the specified axis.".into());
        }
        yy += 25.0;
        let cb = Rect::new(lx + 6.0, yy, cw * 0.5 - 6.0, 18.0);
        changed |= ui.checkbox("mesh.flipnormals", cb, &mut m.flip_normals);
        ui.text("Flip normals", cb.x + 20.0, yy + 2.0, 12.0, C_TEXT);
        if ui.hover(cb) {
            ui.tooltip = Some("Make the model's normals point in the opposite direction.".into());
        }
        let cb = Rect::new(lx + cw * 0.5, yy, cw * 0.5 - 6.0, 18.0);
        changed |= ui.checkbox("mesh.fixwinding", cb, &mut m.fix_winding);
        ui.text("Fix winding", cb.x + 20.0, yy + 2.0, 12.0, C_TEXT);
        if ui.hover(cb) {
            ui.tooltip = Some("Make each face's winding match its normals.".into());
        }
        // Collection
        let cy = y + 110.0;
        group_box(ui, Rect::new(lx, cy, cw, 84.0), "");
        let cb = Rect::new(lx + 6.0, cy + 2.0, cw - 12.0, 18.0);
        changed |= ui.checkbox("mesh.collection", cb, &mut m.collection);
        ui.text("Collection", cb.x + 20.0, cy + 4.0, 12.0, C_TEXT);
        if ui.hover(cb) {
            ui.tooltip = Some("Build this mesh from generators marked \"Contribute to collections\".".into());
        }
        let on = m.collection;
        let mut yy = cy + 26.0;
        row(ui, lx, yy, "Spines");
        let sp: Vec<String> = SPINE_STYLES.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(lx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.spines", fr, &sp, &mut m.spine_style);
        if !on {
            draw_rectangle(fr.x, fr.y, fr.w, fr.h, Color::new(0.23, 0.23, 0.23, 0.6));
        }
        yy += 25.0;
        row(ui, lx, yy, "Pivot");
        let pvs: Vec<String> = PIVOT_STYLES.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(lx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.pivot", fr, &pvs, &mut m.pivot_style);
        if !on {
            draw_rectangle(fr.x, fr.y, fr.w, fr.h, Color::new(0.23, 0.23, 0.23, 0.6));
        }
        if ui.hover(fr) {
            ui.tooltip = Some("Origin: lie on the original geometry. First: relative to the first collected object.".into());
        }
        // Wind direction
        group_box(ui, Rect::new(rx, y, cw, 70.0), "Wind direction");
        let mut yy = y + 16.0;
        row(ui, rx, yy, "Growth");
        let gs: Vec<String> = GROWTHS.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(rx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.growth", fr, &gs, &mut m.growth);
        if ui.hover(fr) {
            ui.tooltip = Some("Specifies the axis that will align with the wind direction (and grows along the leaf).".into());
        }
        yy += 25.0;
        row(ui, rx, yy, "Ripple");
        let rs: Vec<String> = RIPPLES.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(rx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.ripple", fr, &rs, &mut m.ripple);
        if ui.hover(fr) {
            ui.tooltip = Some("Specifies the vector along which rippling will occur.".into());
        }
        // Proxy collision
        let py = y + 78.0;
        group_box(ui, Rect::new(rx, py, cw, 70.0), "Proxy collision");
        let mut yy = py + 16.0;
        row(ui, rx, yy, "Scale");
        let fr = Rect::new(rx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.slider("mesh.colscale", fr, &mut m.collision_scale, 0.0, 10.0, 2);
        if ui.hover(fr) {
            ui.tooltip = Some("Multiplies the collision distance for each instance of this mesh.".into());
        }
        yy += 25.0;
        row(ui, rx, yy, "Weight");
        let fr = Rect::new(rx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.slider("mesh.weight", fr, &mut m.weight, 0.0, 10.0, 2);
        if ui.hover(fr) {
            ui.tooltip = Some("Multiplies the likelihood that this mesh is chosen when it collides with another.".into());
        }
        if changed {
            self.dirty = true;
        }
    }

    fn remove_mesh(&mut self, cur: usize) {
        if self.meshes.is_empty() {
            return;
        }
        self.meshes.remove(cur);
        for n in &mut self.nodes {
            if n.p.leaf_mesh == cur + 1 {
                n.p.leaf_mesh = 0;
            } else if n.p.leaf_mesh > cur + 1 {
                n.p.leaf_mesh -= 1;
            }
        }
        for m in &mut self.meshes {
            if m.more == cur + 1 {
                m.more = 0;
            } else if m.more > cur + 1 {
                m.more -= 1;
            }
        }
        self.mesh_cur = 0;
        self.mesh_lod = 0;
        self.select(Sel::None);
        self.dirty = true;
    }

    fn pick_mesh_file() -> Option<String> {
        rfd::FileDialog::new().add_filter("Mesh (OBJ)", &["obj"]).pick_file().map(|p| p.to_string_lossy().to_string())
    }

    fn add_mesh_from_file(&mut self) {
        if let Some(f) = Self::pick_mesh_file() {
            match meshio::load_obj(&f) {
                Ok(g) => {
                    let name = std::path::Path::new(&f).file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or("Mesh".into());
                    let mut m = LeafMesh::card(&name);
                    m.lods[0] = MeshLod { file: f, outline: vec![], geom: Some(g) };
                    m.ref_material = self.mat_cur.min(self.materials.len().saturating_sub(1));
                    self.meshes.push(m);
                    self.mesh_lod = 0;
                    self.select(Sel::Mesh(self.meshes.len() - 1));
                    self.set_status(&format!("Added mesh \"{}\"", name));
                }
                Err(e) => self.set_status(&format!("Couldn't read that mesh: {}", e)),
            }
        }
    }

    fn browse_lod(&mut self, cur: usize, l: usize) {
        if let Some(f) = Self::pick_mesh_file() {
            match meshio::load_obj(&f) {
                Ok(g) => {
                    self.meshes[cur].lods[l] = MeshLod { file: f, outline: vec![], geom: Some(g) };
                    self.mesh_lod = l;
                    self.dirty = true;
                }
                Err(e) => self.set_status(&format!("Couldn't read that mesh: {}", e)),
            }
        }
    }

    fn reload_lod(&mut self, cur: usize, l: usize) {
        let file = self.meshes[cur].lods[l].file.clone();
        if file.is_empty() {
            self.set_status("This level is a cutout; there is no file to reload");
            return;
        }
        match meshio::load_obj(&file) {
            Ok(g) => {
                self.meshes[cur].lods[l].geom = Some(g);
                self.dirty = true;
                self.set_status("Reloaded");
            }
            Err(e) => self.set_status(&format!("Couldn't reload: {}", e)),
        }
    }

    fn export_lod(&mut self, cur: usize, l: usize) {
        let g = match meshio::processed_geom(&self.meshes, cur, l) {
            Some(g) => g,
            None => {
                self.set_status("This level is empty");
                return;
            }
        };
        let name = format!("{}_{}.obj", self.meshes[cur].name.replace(' ', "_"), LOD_NAMES[l]);
        if let Some(p) = rfd::FileDialog::new().add_filter("Mesh (OBJ)", &["obj"]).set_file_name(&name).save_file() {
            match meshio::save_obj(&p.to_string_lossy(), &g) {
                Ok(()) => self.set_status("Mesh exported"),
                Err(e) => self.set_status(&format!("Couldn't export: {}", e)),
            }
        }
    }

    /// Dropping a mesh on the model: the selected leaf generator uses it (or the first one).
    pub fn drop_mesh_on_model(&mut self, cur: usize) {
        let target = match self.sel {
            Sel::Node(id) if self.node(id).map(|n| n.kind == Kind::Leaf).unwrap_or(false) => Some(id),
            _ => self.nodes.iter().find(|n| n.kind == Kind::Leaf).map(|n| n.id),
        };
        match target {
            Some(id) => {
                let name = self.meshes[cur].name.clone();
                if let Some(n) = self.nodes.iter_mut().find(|n| n.id == id) {
                    n.p.leaf_mesh = cur + 1;
                    let nn = n.name.clone();
                    self.set_status(&format!("\"{}\" now uses mesh \"{}\"", nn, name));
                }
                self.dirty = true;
            }
            None => self.set_status("Add a Leaf generator first"),
        }
    }

    /// The cutout editor ("Edit Mesh..."): outline points and anchor over the reference picture.
    fn draw_cutout_editor(&mut self, ui: &mut Ui, area: Rect, cur: usize) {
        let lod = self.mesh_lod.min(2);
        draw_rectangle(area.x, area.y, area.w, area.h, C_BG);
        let title = format!("Cutout editor: {} level", LOD_NAMES[lod]);
        ui.text(&title, area.x + 6.0, area.y + 4.0, 12.0, C_TEXT);
        if self.meshes[cur].lods[lod].geom.is_some() {
            ui.text("This level comes from a mesh file.", area.x + 6.0, area.y + 30.0, 12.5, C_TEXT_DIM);
            if ui.button("mesh.tocutout", Rect::new(area.x + 6.0, area.y + 52.0, 170.0, 24.0), "Replace with a cutout") {
                self.meshes[cur].lods[lod] = MeshLod { file: String::new(), outline: card_outline(), geom: None };
                self.dirty = true;
            }
            return;
        }
        if self.meshes[cur].lods[lod].outline.len() < 3 {
            ui.text("This level is empty.", area.x + 6.0, area.y + 30.0, 12.5, C_TEXT_DIM);
            if ui.button("mesh.fromhigh", Rect::new(area.x + 6.0, area.y + 52.0, 210.0, 24.0), "Make it from High (fewer points)") {
                let src = self.meshes[cur].lods[0].outline.clone();
                if src.len() >= 3 {
                    let n = (src.len() * if lod == 1 { 2 } else { 1 } / 3).max(3);
                    self.meshes[cur].lods[lod].outline = textures::reduce_outline(src, n);
                } else {
                    self.meshes[cur].lods[lod].outline = card_outline();
                }
                self.dirty = true;
            }
            return;
        }
        let avail = Rect::new(area.x + 6.0, area.y + 22.0, area.w - 12.0, area.h - 44.0);
        let side = avail.w.min(avail.h).max(40.0);
        let cv = Rect::new(avail.x + (avail.w - side) * 0.5, avail.y, side, side);
        checker(cv, 16.0);
        let refm = self.meshes[cur].ref_material;
        if let Some(t) = self.materials.get(refm).and_then(|m| m.tex.as_ref()) {
            draw_texture_ex(t, cv.x, cv.y, WHITE, DrawTextureParams { dest_size: Some(vec2(cv.w, cv.h)), ..Default::default() });
        }
        let to_s = |p: Vec2| vec2(cv.x + p.x * cv.w, cv.y + p.y * cv.h);
        let to_uv = |s: Vec2| vec2((s.x - cv.x) / cv.w, (s.y - cv.y) / cv.h);
        let poly = self.meshes[cur].lods[lod].outline.clone();
        for tri in textures::triangulate(&poly) {
            let a = to_s(poly[tri[0]]);
            let b = to_s(poly[tri[1]]);
            let c = to_s(poly[tri[2]]);
            draw_triangle(a, b, c, Color::new(0.85, 0.59, 0.28, 0.10));
            draw_line(a.x, a.y, b.x, b.y, 1.0, Color::new(1.0, 1.0, 1.0, 0.15));
            draw_line(b.x, b.y, c.x, c.y, 1.0, Color::new(1.0, 1.0, 1.0, 0.15));
        }
        for k in 0..poly.len() {
            let a = to_s(poly[k]);
            let b = to_s(poly[(k + 1) % poly.len()]);
            draw_line(a.x, a.y, b.x, b.y, 2.0, C_ORANGE);
        }
        let m = ui.mouse();
        let mut hover_pt: Option<i32> = None;
        let anc = to_s(self.meshes[cur].anchor);
        if anc.distance(m) < 9.0 {
            hover_pt = Some(-1);
        }
        for (k, p) in poly.iter().enumerate() {
            if to_s(*p).distance(m) < 7.0 {
                hover_pt = Some(k as i32);
            }
        }
        for (k, p) in poly.iter().enumerate() {
            let s = to_s(*p);
            let hot = hover_pt == Some(k as i32) || self.mesh_drag == Some(k as i32);
            draw_rectangle(s.x - 4.0, s.y - 4.0, 8.0, 8.0, if hot { WHITE } else { C_ORANGE });
            draw_rectangle_lines(s.x - 4.0, s.y - 4.0, 8.0, 8.0, 1.0, Color::new(0.0, 0.0, 0.0, 0.6));
        }
        let green = Color::new(0.3, 0.95, 0.4, 1.0);
        draw_circle_lines(anc.x, anc.y, 7.0, 2.0, green);
        draw_line(anc.x - 11.0, anc.y, anc.x + 11.0, anc.y, 1.0, green);
        draw_line(anc.x, anc.y - 11.0, anc.x, anc.y + 11.0, 1.0, green);
        ui.text("anchor", anc.x + 9.0, anc.y + 4.0, 10.5, green);

        let inp = ui.inp.clone();
        let over = cv.contains(m) && !ui.blocked && ui.popup.is_none();
        let mut changed = false;
        if over && ui.active == 0 {
            if inp.l_double && hover_pt.is_none() {
                let uv = to_uv(m);
                let mut best = (f32::MAX, 0usize);
                for k in 0..poly.len() {
                    let a = poly[k];
                    let b = poly[(k + 1) % poly.len()];
                    let ab = b - a;
                    let t = ((uv - a).dot(ab) / ab.length_squared().max(1e-9)).clamp(0.0, 1.0);
                    let d = (a + ab * t).distance(uv);
                    if d < best.0 {
                        best = (d, k);
                    }
                }
                self.meshes[cur].lods[lod].outline.insert(best.1 + 1, uv);
                changed = true;
            } else if inp.l_pressed {
                if let Some(h) = hover_pt {
                    self.mesh_drag = Some(h);
                    ui.active = hid("meshcanvas");
                }
            } else if inp.r_pressed {
                if let Some(h) = hover_pt {
                    if h >= 0 && poly.len() > 3 {
                        self.meshes[cur].lods[lod].outline.remove(h as usize);
                        changed = true;
                    }
                }
            }
        }
        if let Some(h) = self.mesh_drag {
            if inp.l_down {
                let uv = to_uv(m);
                let uv = vec2(uv.x.clamp(-0.1, 1.1), uv.y.clamp(-0.1, 1.1));
                if h < 0 {
                    self.meshes[cur].anchor = vec2(uv.x.clamp(0.0, 1.0), uv.y.clamp(0.0, 1.0));
                } else if (h as usize) < self.meshes[cur].lods[lod].outline.len() {
                    self.meshes[cur].lods[lod].outline[h as usize] = uv;
                }
                changed = true;
            } else {
                self.mesh_drag = None;
            }
        }
        if changed {
            self.dirty = true;
            if self.sel != Sel::Mesh(cur) {
                self.sel = Sel::Mesh(cur);
            }
        }
        ui.text_fit(
            "Drag points or the green anchor • double-click an edge to add • right-click a point to remove",
            area.x + 6.0,
            area.y + area.h - 18.0,
            area.w - 12.0,
            10.5,
            C_TEXT_FAINT,
        );
    }

    /// Render the selected mesh into the Meshes tab's preview picture (before the UI pass).
    pub fn render_mesh_preview(&mut self) {
        if self.tab != 2 || self.mesh_editing || self.meshes.is_empty() {
            return;
        }
        let gm = match &self.gm {
            Some(g) => g,
            None => return,
        };
        let rt = self.mesh_rt.get_or_insert_with(|| {
            let r = render_target_ex(640, 512, RenderTargetParams { depth: true, ..Default::default() });
            r.texture.set_filter(FilterMode::Linear);
            r
        });
        let cur = self.mesh_cur.min(self.meshes.len() - 1);
        let g = meshio::processed_geom(&self.meshes, cur, self.mesh_lod);
        let (bmin, bmax) = g.as_ref().map(meshio::bounds).unwrap_or((Vec3::splat(-0.5), Vec3::splat(0.5)));
        let center = (bmin + bmax) * 0.5;
        let radius = ((bmax - bmin).length() * 0.5).max(0.05);
        let cam = Cam {
            yaw: self.mesh_yaw,
            pitch: self.mesh_pitch,
            dist: radius / (20.0f32.to_radians()).sin() * 1.15 * self.mesh_zoom,
            target: center,
            ortho: false,
            view: 0,
            fov: 40.0,
        };
        let c3 = cam.camera3d(None, self.mesh_preview_aspect.max(0.2), Some(rt.clone()));
        set_camera(&c3);
        clear_background(Color::new(0.0, 0.0, 0.0, 0.0));
        if let Some(g) = &g {
            let refm = self.meshes[cur].ref_material;
            let fallback = Material::new("?", 0);
            let mat = self.materials.get(refm).unwrap_or(&fallback);
            let verts: Vec<macroquad::models::Vertex> = g
                .pos
                .iter()
                .enumerate()
                .map(|(i, p)| macroquad::models::Vertex {
                    position: *p,
                    uv: g.uv[i],
                    color: [255; 4],
                    normal: vec4(g.nrm[i].x, g.nrm[i].y, g.nrm[i].z, 1.0),
                })
                .collect();
            let idx: Vec<u16> = g.idx.iter().map(|&i| i as u16).collect();
            gl_use_material(gm);
            render::apply_material(gm, mat, &self.light, cam.position());
            draw_mesh(&Mesh { vertices: verts, indices: idx, texture: mat.tex.clone() });
            unsafe { get_internal_gl() }.flush();
            gl_use_default_material();
        }
        // axes at the mesh origin (the attachment point), growth axis in yellow
        let len = radius * 1.2;
        draw_line_3d(Vec3::ZERO, Vec3::X * len, Color::new(0.9, 0.35, 0.35, 1.0));
        draw_line_3d(Vec3::ZERO, Vec3::Y * len, Color::new(0.4, 0.85, 0.4, 1.0));
        draw_line_3d(Vec3::ZERO, Vec3::Z * len, Color::new(0.4, 0.55, 1.0, 1.0));
        let ga = meshio::growth_axis(self.meshes[cur].growth) * len * 1.1;
        draw_line_3d(Vec3::ZERO, ga, Color::new(1.0, 0.85, 0.2, 1.0));
        if self.show_alignment {
            // the intended orientation: a leaf lying in X/Y, growing up +Y from the origin, facing +Z
            let s = radius * 1.6;
            let mut prev: Option<Vec3> = None;
            let shape: Vec<Vec3> = (0..=24)
                .map(|i| {
                    let t = i as f32 / 24.0;
                    let a = t * std::f32::consts::TAU;
                    let yv = (1.0 - a.cos()) * 0.5;
                    vec3(a.sin() * 0.35 * (1.0 - yv * 0.4), yv, 0.0) * s
                })
                .collect();
            for p in shape {
                if let Some(q) = prev {
                    draw_line_3d(q, p, Color::new(1.0, 1.0, 1.0, 0.7));
                }
                prev = Some(p);
            }
            draw_line_3d(Vec3::ZERO, Vec3::Y * s, Color::new(1.0, 1.0, 1.0, 0.5));
        }
        set_default_camera();
    }
}

fn group_box(ui: &mut Ui, r: Rect, title: &str) {
    draw_rectangle_lines(r.x, r.y + 6.0, r.w, r.h - 6.0, 1.0, Color::new(1.0, 1.0, 1.0, 0.14));
    if !title.is_empty() {
        let tw = ui.text_w(title, 12.0);
        draw_rectangle(r.x + 6.0, r.y, tw + 8.0, 12.0, C_PANEL);
        ui.text(title, r.x + 10.0, r.y - 1.0, 12.0, C_TEXT_DIM);
    }
}

fn icon_hand(r: Rect) {
    let c = Color::new(1.0, 1.0, 1.0, 0.85);
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    draw_rectangle(cx - 6.0, cy - 1.0, 12.0, 9.0, c);
    for (i, h) in [6.0f32, 9.0, 9.0, 7.0].iter().enumerate() {
        draw_rectangle(cx - 6.0 + i as f32 * 3.2, cy - 1.0 - h, 2.4, *h, c);
    }
    draw_rectangle(cx + 5.0, cy - 2.0, 4.0, 2.4, c);
}

fn icon_reload(r: Rect) {
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    let c = Color::new(1.0, 1.0, 1.0, 0.8);
    let mut prev: Option<Vec2> = None;
    for i in 0..=14 {
        let a = 0.6 + i as f32 / 14.0 * 5.0;
        let p = vec2(cx + a.cos() * 6.0, cy + a.sin() * 6.0);
        if let Some(q) = prev {
            draw_line(q.x, q.y, p.x, p.y, 1.5, c);
        }
        prev = Some(p);
    }
    let tip = vec2(cx + 0.6f32.cos() * 6.0, cy + 0.6f32.sin() * 6.0);
    draw_triangle(tip + vec2(-3.0, -3.0), tip + vec2(3.0, -1.0), tip + vec2(0.0, 3.0), c);
}

fn icon_export(r: Rect) {
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    let c = Color::new(1.0, 1.0, 1.0, 0.8);
    draw_rectangle_lines(cx - 2.0, cy - 6.0, 8.0, 12.0, 1.2, c);
    draw_line(cx - 8.0, cy, cx + 1.0, cy, 1.5, c);
    draw_triangle(vec2(cx + 3.0, cy), vec2(cx - 1.0, cy - 3.5), vec2(cx - 1.0, cy + 3.5), c);
}

fn icon_clipboard(r: Rect) {
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    let c = Color::new(1.0, 1.0, 1.0, 0.85);
    draw_rectangle_lines(cx - 5.0, cy - 6.0, 10.0, 13.0, 1.3, c);
    draw_rectangle(cx - 2.5, cy - 7.5, 5.0, 3.0, c);
    draw_line(cx - 3.0, cy - 1.0, cx + 3.0, cy - 1.0, 1.0, c);
    draw_line(cx - 3.0, cy + 2.0, cx + 3.0, cy + 2.0, 1.0, c);
}

input.content:
    // ------------------------------------------------------------------ meshes
    /// The Meshes tab, laid out like the original's Meshes panel (fn 0x140076fd0 in 8.4.2):
    /// drag handle, mesh picker, +/-, +, copy/paste; Geometry (Edit Mesh..., High/Med/Low
    /// files, More); preview; Show / Alignment / V:F; Transform; Collection; Wind direction;
    /// Proxy collision.
    fn draw_meshes(&mut self, ui: &mut Ui, tb: Rect, body: Rect) {
        let r = Rect::new(tb.x, tb.y, tb.w, body.y + body.h - tb.y);
        let x0 = r.x + 8.0;
        let w = r.w - 16.0;
        let mut y = r.y + 4.0;

        // ---- top row
        let hand = Rect::new(x0, y, 30.0, 30.0);
        ui.record("btn:mesh.drag", hand);
        let hot = ui.hover(hand);
        draw_rectangle(hand.x, hand.y, hand.w, hand.h, if hot || self.hand_drag { C_BTN_HOT } else { C_BTN });
        icon_hand(hand);
        if hot {
            ui.tooltip = Some("Drag this mesh and drop it on the model to use it.".into());
            if ui.inp.l_pressed && !self.meshes.is_empty() {
                self.hand_drag = true;
                ui.active = hid("mesh.drag");
            }
        }
        let bw = 34.0;
        let combo_w = (w - 36.0 - (bw + 4.0) * 3.0).max(60.0);
        let names: Vec<String> = if self.meshes.is_empty() { vec!["No meshes".into()] } else { self.meshes.iter().map(|m| m.name.clone()).collect() };
        let mut cur = self.mesh_cur.min(self.meshes.len().saturating_sub(1));
        let cr = Rect::new(x0 + 36.0, y + 4.0, combo_w, 22.0);
        if ui.combo("mesh.pick", cr, &names, &mut cur) && !self.meshes.is_empty() {
            self.mesh_lod = 0;
            self.select(Sel::Mesh(cur));
        }
        if ui.hover(cr) {
            ui.tooltip = Some("Select a mesh to edit. Meshes are used as leaf geometry.".into());
        }
        let bx = cr.x + cr.w + 4.0;
        let r1 = Rect::new(bx, y + 4.0, bw, 22.0);
        if ui.button("mesh.addremove", r1, "+/-") {
            ui.open_popup(hid("mesh.addremove"), r1, vec!["Add mesh (card)".into(), "Add cutout from reference material".into(), "Remove this mesh".into()], None);
        }
        if ui.hover(r1) {
            ui.tooltip = Some("Manage the meshes.".into());
        }
        let r2 = Rect::new(bx + bw + 4.0, y + 4.0, bw, 22.0);
        if ui.button("mesh.browseadd", r2, "+") {
            self.add_mesh_from_file();
        }
        if ui.hover(r2) {
            ui.tooltip = Some("Browse for a mesh and add it to the list automatically...".into());
        }
        let r3 = Rect::new(bx + (bw + 4.0) * 2.0, y + 4.0, bw, 22.0);
        if ui.button("mesh.copypaste", r3, "") {
            ui.open_popup(hid("mesh.copypaste"), r3, vec!["Copy".into(), "Paste".into(), "Duplicate".into()], None);
        }
        icon_clipboard(r3);
        if ui.hover(r3) {
            ui.tooltip = Some("Copy/Paste menu...".into());
        }
        if let Some(i) = ui.take_popup_result("mesh.addremove") {
            match i {
                0 | 1 => {
                    let mut m = LeafMesh::card(&format!("Mesh {}", self.meshes.len() + 1));
                    m.ref_material = self.mat_cur.min(self.materials.len().saturating_sub(1));
                    if i == 1 {
                        if let Some(img) = self.materials.get(m.ref_material).and_then(|x| x.adjusted.clone()) {
                            m.lods[0].outline = textures::auto_cutout(&img, m.auto_points as usize, m.threshold, m.margin);
                        }
                    }
                    self.meshes.push(m);
                    self.mesh_lod = 0;
                    self.select(Sel::Mesh(self.meshes.len() - 1));
                }
                _ => self.remove_mesh(cur),
            }
        }
        if let Some(i) = ui.take_popup_result("mesh.copypaste") {
            if !self.meshes.is_empty() {
                match i {
                    0 => {
                        self.mesh_clip = Some(self.meshes[cur].clone());
                        self.set_status("Mesh copied");
                    }
                    1 => match self.mesh_clip.clone() {
                        Some(mut m) => {
                            m.name = self.meshes[cur].name.clone();
                            self.meshes[cur] = m;
                            self.dirty = true;
                            self.set_status("Mesh pasted");
                        }
                        None => self.set_status("Nothing copied yet"),
                    },
                    _ => {
                        let mut m = self.meshes[cur].clone();
                        m.name = format!("{} copy", m.name);
                        self.meshes.push(m);
                        self.select(Sel::Mesh(self.meshes.len() - 1));
                    }
                }
            }
        }
        // drag-and-drop the mesh onto the model
        if self.hand_drag {
            if ui.inp.l_down {
                if let Some(m) = self.meshes.get(cur) {
                    ui.tooltip = Some(format!("Drop on the viewport to use \"{}\" for the leaves", m.name));
                }
            } else {
                self.hand_drag = false;
                if self.viewport.contains(ui.mouse()) && !self.meshes.is_empty() {
                    self.drop_mesh_on_model(cur);
                }
            }
        }
        y += 38.0;
        if self.meshes.is_empty() {
            ui.text("No meshes. Use +/- to add one, or + to load a mesh file.", x0, y + 6.0, 12.5, C_TEXT_FAINT);
            return;
        }
        self.mesh_cur = cur;

        // ---- Geometry
        ui.text("Geometry", x0, y, 12.0, C_TEXT_DIM);
        y += 17.0;
        let lw = 40.0;
        let er = Rect::new(x0 + lw, y, w - lw - 90.0, 22.0);
        let label = if self.mesh_editing { "Done editing" } else { "Edit Mesh..." };
        if ui.button_ex("mesh.edit", er, label, self.mesh_editing, true) {
            self.mesh_editing = !self.mesh_editing;
        }
        y += 26.0;
        for l in 0..3 {
            let lab = LOD_NAMES[l];
            let tw = ui.text_w(lab, 12.0);
            ui.text(lab, x0 + lw - tw - 6.0, y + 4.0, 12.0, C_TEXT_DIM);
            let fr = Rect::new(x0 + lw, y, w - lw - 90.0, 22.0);
            let selected = self.mesh_lod == l;
            draw_rectangle(fr.x, fr.y, fr.w, fr.h, C_FIELD);
            if selected {
                draw_rectangle_lines(fr.x, fr.y, fr.w, fr.h, 1.0, C_ACCENT2);
            }
            let lod = &self.meshes[cur].lods[l];
            let desc = if self.meshes[cur].collection {
                "(collection)".to_string()
            } else if !lod.file.is_empty() {
                std::path::Path::new(&lod.file).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default()
            } else if lod.outline.len() >= 3 {
                format!("cutout, {} points", lod.outline.len())
            } else {
                String::new()
            };
            ui.text_fit(&desc, fr.x + 6.0, fr.y + 4.0, fr.w - 10.0, 12.0, C_TEXT);
            ui.record(&format!("mesh.lodfield.{}", l), fr);
            if ui.clicked(fr) {
                self.mesh_lod = l;
            }
            let b1 = Rect::new(fr.x + fr.w + 4.0, y, 26.0, 22.0);
            if ui.button(&format!("mesh.browse{}", l), b1, "...") {
                self.browse_lod(cur, l);
            }
            if ui.hover(b1) {
                ui.tooltip = Some(format!("Browse for the {} mesh file...", lab.to_lowercase()));
            }
            let b2 = Rect::new(b1.x + 30.0, y, 26.0, 22.0);
            if ui.button(&format!("mesh.reload{}", l), b2, "") {
                self.reload_lod(cur, l);
            }
            icon_reload(b2);
            if ui.hover(b2) {
                ui.tooltip = Some("Reload this mesh.".into());
            }
            let b3 = Rect::new(b2.x + 30.0, y, 26.0, 22.0);
            if ui.button(&format!("mesh.export{}", l), b3, "") {
                self.export_lod(cur, l);
            }
            icon_export(b3);
            if ui.hover(b3) {
                ui.tooltip = Some("Export this mesh...".into());
            }
            y += 25.0;
        }
        {
            let tw = ui.text_w("More", 12.0);
            ui.text("More", x0 + lw - tw - 6.0, y + 4.0, 12.0, C_TEXT_DIM);
            let mut more_names = vec!["None".to_string()];
            for (i, m) in self.meshes.iter().enumerate() {
                more_names.push(if i == cur { format!("{} (this mesh)", m.name) } else { m.name.clone() });
            }
            let mut more = self.meshes[cur].more.min(more_names.len() - 1);
            let mr = Rect::new(x0 + lw, y, w - lw - 90.0, 22.0);
            if ui.combo("mesh.more", mr, &more_names, &mut more) {
                if more == cur + 1 {
                    self.set_status("A mesh can't supply its own extra levels");
                } else {
                    self.meshes[cur].more = more;
                    self.dirty = true;
                }
            }
            if ui.hover(mr) {
                ui.tooltip = Some("Another mesh whose levels continue this one's (LOD 3 and lower).".into());
            }
            y += 28.0;
        }

        // ---- preview / cutout editor
        let bottom_h = 232.0;
        let pv = Rect::new(x0, y, w, (r.y + r.h - bottom_h - y).max(90.0));
        ui.record("meshcanvas", pv);
        if self.mesh_editing {
            self.draw_cutout_editor(ui, pv, cur);
        } else {
            checker(pv, 12.0);
            if let Some(rt) = &self.mesh_rt {
                draw_texture_ex(&rt.texture, pv.x, pv.y, WHITE, DrawTextureParams { dest_size: Some(vec2(pv.w, pv.h)), flip_y: true, ..Default::default() });
            }
            draw_rectangle_lines(pv.x, pv.y, pv.w, pv.h, 1.0, C_LINE);
            ui.text("drag to turn • wheel to zoom • double-click to reset", pv.x + 6.0, pv.y + pv.h - 16.0, 10.5, C_TEXT_FAINT);
            let m = ui.mouse();
            let over = pv.contains(m) && !ui.blocked && ui.popup.is_none();
            if over && ui.active == 0 && ui.inp.l_pressed {
                if ui.inp.l_double {
                    self.mesh_yaw = 0.0;
                    self.mesh_pitch = 0.0;
                    self.mesh_zoom = 1.0;
                } else {
                    self.mesh_orbit = true;
                    ui.active = hid("meshpreview");
                }
            }
            if self.mesh_orbit {
                if ui.inp.l_down {
                    let d = m - self.graph_mouse_prev_mesh;
                    self.mesh_yaw -= d.x * 0.01;
                    self.mesh_pitch = (self.mesh_pitch + d.y * 0.01).clamp(-1.5, 1.5);
                } else {
                    self.mesh_orbit = false;
                }
            }
            if over && ui.inp.wheel != 0.0 {
                self.mesh_zoom = (self.mesh_zoom * 0.88f32.powf(ui.inp.wheel)).clamp(0.2, 5.0);
            }
            self.graph_mouse_prev_mesh = m;
        }
        self.mesh_preview_aspect = pv.w / pv.h.max(1.0);
        y = pv.y + pv.h + 6.0;

        // ---- Show / Alignment / counts
        ui.text("Show", x0, y + 4.0, 12.0, C_TEXT_DIM);
        let shows: Vec<String> = LOD_NAMES.iter().map(|s| s.to_string()).collect();
        let mut show = self.mesh_lod.min(2);
        if ui.combo("mesh.show", Rect::new(x0 + 36.0, y, 70.0, 22.0), &shows, &mut show) {
            self.mesh_lod = show;
        }
        if ui.hover(Rect::new(x0 + 36.0, y, 70.0, 22.0)) {
            ui.tooltip = Some("Choose which LOD mesh is displayed.".into());
        }
        let ar = Rect::new(x0 + 116.0, y, 100.0, 22.0);
        ui.checkbox("mesh.align", ar, &mut self.show_alignment);
        ui.text("Alignment", ar.x + 20.0, y + 4.0, 12.0, C_TEXT);
        if ui.hover(ar) {
            ui.tooltip = Some("Show the intended orientation: use Orient and Flip to match it.".into());
        }
        let (nv, nf) = meshio::processed_geom(&self.meshes, cur, self.mesh_lod).map(|g| (g.pos.len(), g.tris())).unwrap_or((0, 0));
        let vf = format!("V:{} F:{}", nv, nf);
        let vw = ui.text_w(&vf, 12.0);
        ui.text(&vf, x0 + w - vw, y + 4.0, 12.0, C_TEXT_DIM);
        ui.record("mesh.vf", Rect::new(x0 + w - vw, y, vw, 20.0));
        y += 28.0;

        // ---- two columns of settings
        let cw = (w - 8.0) * 0.5;
        let lx = x0;
        let rx = x0 + cw + 8.0;
        let mut changed = false;
        let m = &mut self.meshes[cur];
        // Transform
        group_box(ui, Rect::new(lx, y, cw, 104.0), "Transform");
        let lab_w = 62.0;
        let row = |ui: &mut Ui, x: f32, yy: f32, label: &str| {
            let tw = ui.text_w(label, 12.0);
            ui.text(label, x + lab_w - tw - 6.0, yy + 4.0, 12.0, C_TEXT_DIM);
        };
        let mut yy = y + 16.0;
        row(ui, lx, yy, "Orient");
        let orients: Vec<String> = ORIENTS.iter().map(|o| o.0.to_string()).collect();
        let fr = Rect::new(lx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.orient", fr, &orients, &mut m.orient);
        if ui.hover(fr) {
            ui.tooltip = Some("Reorient the mesh, if necessary (convert coordinate systems).".into());
        }
        yy += 25.0;
        row(ui, lx, yy, "Flip");
        let flips: Vec<String> = FLIPS.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(lx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.flip", fr, &flips, &mut m.flip);
        if ui.hover(fr) {
            ui.tooltip = Some("Flip the model around the specified axis.".into());
        }
        yy += 25.0;
        let cb = Rect::new(lx + 6.0, yy, cw * 0.5 - 6.0, 18.0);
        changed |= ui.checkbox("mesh.flipnormals", cb, &mut m.flip_normals);
        ui.text("Flip normals", cb.x + 20.0, yy + 2.0, 12.0, C_TEXT);
        if ui.hover(cb) {
            ui.tooltip = Some("Make the model's normals point in the opposite direction.".into());
        }
        let cb = Rect::new(lx + cw * 0.5, yy, cw * 0.5 - 6.0, 18.0);
        changed |= ui.checkbox("mesh.fixwinding", cb, &mut m.fix_winding);
        ui.text("Fix winding", cb.x + 20.0, yy + 2.0, 12.0, C_TEXT);
        if ui.hover(cb) {
            ui.tooltip = Some("Make each face's winding match its normals.".into());
        }
        // Collection
        let cy = y + 110.0;
        group_box(ui, Rect::new(lx, cy, cw, 84.0), "");
        let cb = Rect::new(lx + 6.0, cy + 2.0, cw - 12.0, 18.0);
        changed |= ui.checkbox("mesh.collection", cb, &mut m.collection);
        ui.text("Collection", cb.x + 20.0, cy + 4.0, 12.0, C_TEXT);
        if ui.hover(cb) {
            ui.tooltip = Some("Build this mesh from generators marked \"Contribute to collections\".".into());
        }
        let on = m.collection;
        let mut yy = cy + 26.0;
        row(ui, lx, yy, "Spines");
        let sp: Vec<String> = SPINE_STYLES.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(lx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.spines", fr, &sp, &mut m.spine_style);
        if !on {
            draw_rectangle(fr.x, fr.y, fr.w, fr.h, Color::new(0.23, 0.23, 0.23, 0.6));
        }
        yy += 25.0;
        row(ui, lx, yy, "Pivot");
        let pvs: Vec<String> = PIVOT_STYLES.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(lx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.pivot", fr, &pvs, &mut m.pivot_style);
        if !on {
            draw_rectangle(fr.x, fr.y, fr.w, fr.h, Color::new(0.23, 0.23, 0.23, 0.6));
        }
        if ui.hover(fr) {
            ui.tooltip = Some("Origin: lie on the original geometry. First: relative to the first collected object.".into());
        }
        // Wind direction
        group_box(ui, Rect::new(rx, y, cw, 70.0), "Wind direction");
        let mut yy = y + 16.0;
        row(ui, rx, yy, "Growth");
        let gs: Vec<String> = GROWTHS.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(rx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.growth", fr, &gs, &mut m.growth);
        if ui.hover(fr) {
            ui.tooltip = Some("Specifies the axis that will align with the wind direction (and grows along the leaf).".into());
        }
        yy += 25.0;
        row(ui, rx, yy, "Ripple");
        let rs: Vec<String> = RIPPLES.iter().map(|s| s.to_string()).collect();
        let fr = Rect::new(rx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.combo("mesh.ripple", fr, &rs, &mut m.ripple);
        if ui.hover(fr) {
            ui.tooltip = Some("Specifies the vector along which rippling will occur.".into());
        }
        // Proxy collision
        let py = y + 78.0;
        group_box(ui, Rect::new(rx, py, cw, 70.0), "Proxy collision");
        let mut yy = py + 16.0;
        row(ui, rx, yy, "Scale");
        let fr = Rect::new(rx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.slider("mesh.colscale", fr, &mut m.collision_scale, 0.0, 10.0, 2);
        if ui.hover(fr) {
            ui.tooltip = Some("Multiplies the collision distance for each instance of this mesh.".into());
        }
        yy += 25.0;
        row(ui, rx, yy, "Weight");
        let fr = Rect::new(rx + lab_w, yy, cw - lab_w - 6.0, 22.0);
        changed |= ui.slider("mesh.weight", fr, &mut m.weight, 0.0, 10.0, 2);
        if ui.hover(fr) {
            ui.tooltip = Some("Multiplies the likelihood that this mesh is chosen when it collides with another.".into());
        }
        if changed {
            self.dirty = true;
        }
    }

    fn remove_mesh(&mut self, cur: usize) {
        if self.meshes.is_empty() {
            return;
        }
        self.meshes.remove(cur);
        for n in &mut self.nodes {
            if n.p.leaf_mesh == cur + 1 {
                n.p.leaf_mesh = 0;
            } else if n.p.leaf_mesh > cur + 1 {
                n.p.leaf_mesh -= 1;
            }
        }
        for m in &mut self.meshes {
            if m.more == cur + 1 {
                m.more = 0;
            } else if m.more > cur + 1 {
                m.more -= 1;
            }
        }
        self.mesh_cur = 0;
        self.mesh_lod = 0;
        self.select(Sel::None);
        self.dirty = true;
    }

    fn pick_mesh_file() -> Option<String> {
        rfd::FileDialog::new().add_filter("Mesh (OBJ)", &["obj"]).pick_file().map(|p| p.to_string_lossy().to_string())
    }

    fn add_mesh_from_file(&mut self) {
        if let Some(f) = Self::pick_mesh_file() {
            match meshio::load_obj(&f) {
                Ok(g) => {
                    let name = std::path::Path::new(&f).file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or("Mesh".into());
                    let mut m = LeafMesh::card(&name);
                    m.lods[0] = MeshLod { file: f, outline: vec![], geom: Some(g) };
                    m.ref_material = self.mat_cur.min(self.materials.len().saturating_sub(1));
                    self.meshes.push(m);
                    self.mesh_lod = 0;
                    self.select(Sel::Mesh(self.meshes.len() - 1));
                    self.set_status(&format!("Added mesh \"{}\"", name));
                }
                Err(e) => self.set_status(&format!("Couldn't read that mesh: {}", e)),
            }
        }
    }

    fn browse_lod(&mut self, cur: usize, l: usize) {
        if let Some(f) = Self::pick_mesh_file() {
            match meshio::load_obj(&f) {
                Ok(g) => {
                    self.meshes[cur].lods[l] = MeshLod { file: f, outline: vec![], geom: Some(g) };
                    self.mesh_lod = l;
                    self.dirty = true;
                }
                Err(e) => self.set_status(&format!("Couldn't read that mesh: {}", e)),
            }
        }
    }

    fn reload_lod(&mut self, cur: usize, l: usize) {
        let file = self.meshes[cur].lods[l].file.clone();
        if file.is_empty() {
            self.set_status("This level is a cutout; there is no file to reload");
            return;
        }
        match meshio::load_obj(&file) {
            Ok(g) => {
                self.meshes[cur].lods[l].geom = Some(g);
                self.dirty = true;
                self.set_status("Reloaded");
            }
            Err(e) => self.set_status(&format!("Couldn't reload: {}", e)),
        }
    }

    fn export_lod(&mut self, cur: usize, l: usize) {
        let g = match meshio::processed_geom(&self.meshes, cur, l) {
            Some(g) => g,
            None => {
                self.set_status("This level is empty");
                return;
            }
        };
        let name = format!("{}_{}.obj", self.meshes[cur].name.replace(' ', "_"), LOD_NAMES[l]);
        if let Some(p) = rfd::FileDialog::new().add_filter("Mesh (OBJ)", &["obj"]).set_file_name(&name).save_file() {
            match meshio::save_obj(&p.to_string_lossy(), &g) {
                Ok(()) => self.set_status("Mesh exported"),
                Err(e) => self.set_status(&format!("Couldn't export: {}", e)),
            }
        }
    }

    /// Dropping a mesh on the model: the selected leaf generator uses it (or the first one).
    pub fn drop_mesh_on_model(&mut self, cur: usize) {
        let target = match self.sel {
            Sel::Node(id) if self.node(id).map(|n| n.kind == Kind::Leaf).unwrap_or(false) => Some(id),
            _ => self.nodes.iter().find(|n| n.kind == Kind::Leaf).map(|n| n.id),
        };
        match target {
            Some(id) => {
                let name = self.meshes[cur].name.clone();
                if let Some(n) = self.nodes.iter_mut().find(|n| n.id == id) {
                    n.p.leaf_mesh = cur + 1;
                    let nn = n.name.clone();
                    self.set_status(&format!("\"{}\" now uses mesh \"{}\"", nn, name));
                }
                self.dirty = true;
            }
            None => self.set_status("Add a Leaf generator first"),
        }
    }

    /// The cutout editor ("Edit Mesh..."): outline points and anchor over the reference picture.
    fn draw_cutout_editor(&mut self, ui: &mut Ui, area: Rect, cur: usize) {
        let lod = self.mesh_lod.min(2);
        draw_rectangle(area.x, area.y, area.w, area.h, C_BG);
        let title = format!("Cutout editor: {} level", LOD_NAMES[lod]);
        ui.text(&title, area.x + 6.0, area.y + 4.0, 12.0, C_TEXT);
        if self.meshes[cur].lods[lod].geom.is_some() {
            ui.text("This level comes from a mesh file.", area.x + 6.0, area.y + 30.0, 12.5, C_TEXT_DIM);
            if ui.button("mesh.tocutout", Rect::new(area.x + 6.0, area.y + 52.0, 170.0, 24.0), "Replace with a cutout") {
                self.meshes[cur].lods[lod] = MeshLod { file: String::new(), outline: card_outline(), geom: None };
                self.dirty = true;
            }
            return;
        }
        if self.meshes[cur].lods[lod].outline.len() < 3 {
            ui.text("This level is empty.", area.x + 6.0, area.y + 30.0, 12.5, C_TEXT_DIM);
            if ui.button("mesh.fromhigh", Rect::new(area.x + 6.0, area.y + 52.0, 210.0, 24.0), "Make it from High (fewer points)") {
                let src = self.meshes[cur].lods[0].outline.clone();
                if src.len() >= 3 {
                    let n = (src.len() * if lod == 1 { 2 } else { 1 } / 3).max(3);
                    self.meshes[cur].lods[lod].outline = textures::reduce_outline(src, n);
                } else {
                    self.meshes[cur].lods[lod].outline = card_outline();
                }
                self.dirty = true;
            }
            return;
        }
        let avail = Rect::new(area.x + 6.0, area.y + 22.0, area.w - 12.0, area.h - 44.0);
        let side = avail.w.min(avail.h).max(40.0);
        let cv = Rect::new(avail.x + (avail.w - side) * 0.5, avail.y, side, side);
        checker(cv, 16.0);
        let refm = self.meshes[cur].ref_material;
        if let Some(t) = self.materials.get(refm).and_then(|m| m.tex.as_ref()) {
            draw_texture_ex(t, cv.x, cv.y, WHITE, DrawTextureParams { dest_size: Some(vec2(cv.w, cv.h)), ..Default::default() });
        }
        let to_s = |p: Vec2| vec2(cv.x + p.x * cv.w, cv.y + p.y * cv.h);
        let to_uv = |s: Vec2| vec2((s.x - cv.x) / cv.w, (s.y - cv.y) / cv.h);
        let poly = self.meshes[cur].lods[lod].outline.clone();
        for tri in textures::triangulate(&poly) {
            let a = to_s(poly[tri[0]]);
            let b = to_s(poly[tri[1]]);
            let c = to_s(poly[tri[2]]);
            draw_triangle(a, b, c, Color::new(0.85, 0.59, 0.28, 0.10));
            draw_line(a.x, a.y, b.x, b.y, 1.0, Color::new(1.0, 1.0, 1.0, 0.15));
            draw_line(b.x, b.y, c.x, c.y, 1.0, Color::new(1.0, 1.0, 1.0, 0.15));
        }
        for k in 0..poly.len() {
            let a = to_s(poly[k]);
            let b = to_s(poly[(k + 1) % poly.len()]);
            draw_line(a.x, a.y, b.x, b.y, 2.0, C_ORANGE);
        }
        let m = ui.mouse();
        let mut hover_pt: Option<i32> = None;
        let anc = to_s(self.meshes[cur].anchor);
        if anc.distance(m) < 9.0 {
            hover_pt = Some(-1);
        }
        for (k, p) in poly.iter().enumerate() {
            if to_s(*p).distance(m) < 7.0 {
                hover_pt = Some(k as i32);
            }
        }
        for (k, p) in poly.iter().enumerate() {
            let s = to_s(*p);
            let hot = hover_pt == Some(k as i32) || self.mesh_drag == Some(k as i32);
            draw_rectangle(s.x - 4.0, s.y - 4.0, 8.0, 8.0, if hot { WHITE } else { C_ORANGE });
            draw_rectangle_lines(s.x - 4.0, s.y - 4.0, 8.0, 8.0, 1.0, Color::new(0.0, 0.0, 0.0, 0.6));
        }
        let green = Color::new(0.3, 0.95, 0.4, 1.0);
        draw_circle_lines(anc.x, anc.y, 7.0, 2.0, green);
        draw_line(anc.x - 11.0, anc.y, anc.x + 11.0, anc.y, 1.0, green);
        draw_line(anc.x, anc.y - 11.0, anc.x, anc.y + 11.0, 1.0, green);
        ui.text("anchor", anc.x + 9.0, anc.y + 4.0, 10.5, green);

        let inp = ui.inp.clone();
        let over = cv.contains(m) && !ui.blocked && ui.popup.is_none();
        let mut changed = false;
        if over && ui.active == 0 {
            if inp.l_double && hover_pt.is_none() {
                let uv = to_uv(m);
                let mut best = (f32::MAX, 0usize);
                for k in 0..poly.len() {
                    let a = poly[k];
                    let b = poly[(k + 1) % poly.len()];
                    let ab = b - a;
                    let t = ((uv - a).dot(ab) / ab.length_squared().max(1e-9)).clamp(0.0, 1.0);
                    let d = (a + ab * t).distance(uv);
                    if d < best.0 {
                        best = (d, k);
                    }
                }
                self.meshes[cur].lods[lod].outline.insert(best.1 + 1, uv);
                changed = true;
            } else if inp.l_pressed {
                if let Some(h) = hover_pt {
                    self.mesh_drag = Some(h);
                    ui.active = hid("meshcanvas");
                }
            } else if inp.r_pressed {
                if let Some(h) = hover_pt {
                    if h >= 0 && poly.len() > 3 {
                        self.meshes[cur].lods[lod].outline.remove(h as usize);
                        changed = true;
                    }
                }
            }
        }
        if let Some(h) = self.mesh_drag {
            if inp.l_down {
                let uv = to_uv(m);
                let uv = vec2(uv.x.clamp(-0.1, 1.1), uv.y.clamp(-0.1, 1.1));
                if h < 0 {
                    self.meshes[cur].anchor = vec2(uv.x.clamp(0.0, 1.0), uv.y.clamp(0.0, 1.0));
                } else if (h as usize) < self.meshes[cur].lods[lod].outline.len() {
                    self.meshes[cur].lods[lod].outline[h as usize] = uv;
                }
                changed = true;
            } else {
                self.mesh_drag = None;
            }
        }
        if changed {
            self.dirty = true;
            if self.sel != Sel::Mesh(cur) {
                self.sel = Sel::Mesh(cur);
            }
        }
        ui.text_fit(
            "Drag points or the green anchor • double-click an edge to add • right-click a point to remove",
            area.x + 6.0,
            area.y + area.h - 18.0,
            area.w - 12.0,
            10.5,
            C_TEXT_FAINT,
        );
    }

    /// Render the selected mesh into the Meshes tab's preview picture (before the UI pass).
    pub fn render_mesh_preview(&mut self) {
        if self.tab != 2 || self.mesh_editing || self.meshes.is_empty() {
            return;
        }
        let gm = match &self.gm {
            Some(g) => g,
            None => return,
        };
        let rt = self.mesh_rt.get_or_insert_with(|| {
            let r = render_target_ex(640, 512, RenderTargetParams { depth: true, ..Default::default() });
            r.texture.set_filter(FilterMode::Linear);
            r
        });
        let cur = self.mesh_cur.min(self.meshes.len() - 1);
        let g = meshio::processed_geom(&self.meshes, cur, self.mesh_lod);
        let (bmin, bmax) = g.as_ref().map(meshio::bounds).unwrap_or((Vec3::splat(-0.5), Vec3::splat(0.5)));
        let center = (bmin + bmax) * 0.5;
        let radius = ((bmax - bmin).length() * 0.5).max(0.05);
        let cam = Cam {
            yaw: self.mesh_yaw,
            pitch: self.mesh_pitch,
            dist: radius / (20.0f32.to_radians()).sin() * 1.15 * self.mesh_zoom,
            target: center,
            ortho: false,
            view: 0,
            fov: 40.0,
        };
        let c3 = cam.camera3d(None, self.mesh_preview_aspect.max(0.2), Some(rt.clone()));
        set_camera(&c3);
        clear_background(Color::new(0.0, 0.0, 0.0, 0.0));
        if let Some(g) = &g {
            let refm = self.meshes[cur].ref_material;
            let fallback = Material::new("?", 0);
            let mat = self.materials.get(refm).unwrap_or(&fallback);
            let verts: Vec<macroquad::models::Vertex> = g
                .pos
                .iter()
                .enumerate()
                .map(|(i, p)| macroquad::models::Vertex {
                    position: *p,
                    uv: g.uv[i],
                    color: [255; 4],
                    normal: vec4(g.nrm[i].x, g.nrm[i].y, g.nrm[i].z, 1.0),
                })
                .collect();
            let idx: Vec<u16> = g.idx.iter().map(|&i| i as u16).collect();
            gl_use_material(gm);
            render::apply_material(gm, mat, &self.light, cam.position());
            draw_mesh(&Mesh { vertices: verts, indices: idx, texture: mat.tex.clone() });
            unsafe { get_internal_gl() }.flush();
            gl_use_default_material();
        }
        // axes at the mesh origin (the attachment point), growth axis in yellow
        let len = radius * 1.2;
        draw_line_3d(Vec3::ZERO, Vec3::X * len, Color::new(0.9, 0.35, 0.35, 1.0));
        draw_line_3d(Vec3::ZERO, Vec3::Y * len, Color::new(0.4, 0.85, 0.4, 1.0));
        draw_line_3d(Vec3::ZERO, Vec3::Z * len, Color::new(0.4, 0.55, 1.0, 1.0));
        let ga = meshio::growth_axis(self.meshes[cur].growth) * len * 1.1;
        draw_line_3d(Vec3::ZERO, ga, Color::new(1.0, 0.85, 0.2, 1.0));
        if self.show_alignment {
            // the intended orientation: a leaf lying in X/Y, growing up +Y from the origin, facing +Z
            let s = radius * 1.6;
            let mut prev: Option<Vec3> = None;
            let shape: Vec<Vec3> = (0..=24)
                .map(|i| {
                    let t = i as f32 / 24.0;
                    let a = t * std::f32::consts::TAU;
                    let yv = (1.0 - a.cos()) * 0.5;
                    vec3(a.sin() * 0.35 * (1.0 - yv * 0.4), yv, 0.0) * s
                })
                .collect();
            for p in shape {
                if let Some(q) = prev {
                    draw_line_3d(q, p, Color::new(1.0, 1.0, 1.0, 0.7));
                }
                prev = Some(p);
            }
            draw_line_3d(Vec3::ZERO, Vec3::Y * s, Color::new(1.0, 1.0, 1.0, 0.5));
        }
        set_default_camera();
    }
}

fn group_box(ui: &mut Ui, r: Rect, title: &str) {
    draw_rectangle_lines(r.x, r.y + 6.0, r.w, r.h - 6.0, 1.0, Color::new(1.0, 1.0, 1.0, 0.14));
    if !title.is_empty() {
        let tw = ui.text_w(title, 12.0);
        draw_rectangle(r.x + 6.0, r.y, tw + 8.0, 12.0, C_PANEL);
        ui.text(title, r.x + 10.0, r.y - 1.0, 12.0, C_TEXT_DIM);
    }
}

fn icon_hand(r: Rect) {
    let c = Color::new(1.0, 1.0, 1.0, 0.85);
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    draw_rectangle(cx - 6.0, cy - 1.0, 12.0, 9.0, c);
    for (i, h) in [6.0f32, 9.0, 9.0, 7.0].iter().enumerate() {
        draw_rectangle(cx - 6.0 + i as f32 * 3.2, cy - 1.0 - h, 2.4, *h, c);
    }
    draw_rectangle(cx + 5.0, cy - 2.0, 4.0, 2.4, c);
}

fn icon_reload(r: Rect) {
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    let c = Color::new(1.0, 1.0, 1.0, 0.8);
    let mut prev: Option<Vec2> = None;
    for i in 0..=14 {
        let a = 0.6 + i as f32 / 14.0 * 5.0;
        let p = vec2(cx + a.cos() * 6.0, cy + a.sin() * 6.0);
        if let Some(q) = prev {
            draw_line(q.x, q.y, p.x, p.y, 1.5, c);
        }
        prev = Some(p);
    }
    let tip = vec2(cx + 0.6f32.cos() * 6.0, cy + 0.6f32.sin() * 6.0);
    draw_triangle(tip + vec2(-3.0, -3.0), tip + vec2(3.0, -1.0), tip + vec2(0.0, 3.0), c);
}

fn icon_export(r: Rect) {
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    let c = Color::new(1.0, 1.0, 1.0, 0.8);
    draw_rectangle_lines(cx - 2.0, cy - 6.0, 8.0, 12.0, 1.2, c);
    draw_line(cx - 8.0, cy, cx + 1.0, cy, 1.5, c);
    draw_triangle(vec2(cx + 3.0, cy), vec2(cx - 1.0, cy - 3.5), vec2(cx - 1.0, cy + 3.5), c);
}

fn icon_clipboard(r: Rect) {
    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    let c = Color::new(1.0, 1.0, 1.0, 0.85);
    draw_rectangle_lines(cx - 5.0, cy - 6.0, 10.0, 13.0, 1.3, c);
    draw_rectangle(cx - 2.5, cy - 7.5, 5.0, 3.0, c);
    draw_line(cx - 3.0, cy - 1.0, cx + 3.0, cy - 1.0, 1.0, c);
    draw_line(cx - 3.0, cy + 2.0, cx + 3.0, cy + 2.0, 1.0, c);
}

