pub fn bounds(g: &MeshGeom) -> (Vec3, Vec3) {
    let mut a = Vec3::splat(f32::MAX);
    let mut b = Vec3::splat(f32::MIN);
    for p in &g.pos {
        a = a.min(*p);
        b = b.max(*p);
    }
    if a.x > b.x {
        (Vec3::splat(-0.5), Vec3::splat(0.5))
    } else {
        (a, b)
    }
}

