/// Finished geometry for a level after Orient, Flip, Scale, Fix winding and Flip normals.
/// Levels 3 and up come from the "More" mesh's levels.
pub fn processed_geom(meshes: &[LeafMesh], mi: usize, lod: usize) -> Option<MeshGeom> {
    let m = meshes.get(mi)?;
    if lod >= 3 && m.more >= 1 && m.more - 1 != mi {
        return processed_geom(meshes, m.more - 1, lod - 3);
    }
    let l = m.lod_index(lod);
    let mut g = raw_geom(m, l)?;
    let orient = ORIENTS.get(m.orient).map(|o| o.1).unwrap_or(6);
    let s = flip_signs(m.flip);
    for p in &mut g.pos {
        *p = orient_point(orient, *p) * s * m.scale;
    }
    for n in &mut g.nrm {
        *n = (orient_point(orient, *n) * s).normalize_or_zero();
    }
    // the original counts mirrors (orient 1/2/5/8/9 count one, each flipped axis one) and reverses
    // the faces when the count is odd (fn 0x1400ab6c0)
    let mirrored = (s.x * s.y * s.z < 0.0) ^ matches!(orient, 1 | 2 | 5 | 8 | 9);
    if mirrored {
        for f in g.idx.chunks_mut(3) {
            f.swap(1, 2);
        }
    }
    if m.fix_winding {
        // make each face's winding agree with its vertex normals
        for f in g.idx.chunks_mut(3) {
            let (a, b, c) = (f[0] as usize, f[1] as usize, f[2] as usize);
            let fnn = (g.pos[b] - g.pos[a]).cross(g.pos[c] - g.pos[a]);
            let vn = g.nrm[a] + g.nrm[b] + g.nrm[c];
            if fnn.dot(vn) < 0.0 {
                f.swap(1, 2);
            }
        }
    }
    if m.flip_normals {
        for n in &mut g.nrm {
            *n = -*n;
        }

