//! The "Meshes" add/remove dialog opened by the +/- button, matching the original's
//! CAssetAddRemoveDialog (texts and tooltips set in fn 0x14004e3a0, 8.4.2): Add new, Duplicate,
//! Rename, Move up, Move down, Remove, a list of names, and OK / Cancel. Changes apply on OK.
use crate::app::{App, Sel};
use crate::model::*;
use crate::ui::*;
use macroquad::prelude::*;

pub struct MeshDialog {
    /// (original index, mesh) in the order shown; None = added in this dialog.
    pub items: Vec<(Option<usize>, LeafMesh)>,
    pub selected: Vec<bool>,
    pub current: Option<usize>,
    pub editing: Option<(usize, String)>,
    pub pos: Vec2,
    drag: Option<Vec2>,
    caret_t: f64,
}

const W: f32 = 490.0;
const H: f32 = 380.0;

impl MeshDialog {
    pub fn open(meshes: &[LeafMesh], current: usize, sw: f32, sh: f32) -> Self {
        let n = meshes.len();
        let mut selected = vec![false; n];
        let cur = if n > 0 { Some(current.min(n - 1)) } else { None };
        if let Some(c) = cur {
            selected[c] = true;
        }
        MeshDialog {
            items: meshes.iter().cloned().enumerate().map(|(i, m)| (Some(i), m)).collect(),
            selected,
            current: cur,
            editing: None,
            pos: vec2((sw - W) * 0.5, (sh - H) * 0.4),
            drag: None,
            caret_t: get_time(),
        }
    }

    fn unique_name(&self, base: &str) -> String {
        let taken = |s: &str| self.items.iter().any(|(_, m)| m.name == s);
        if !taken(base) {
            return base.to_string();
        }
        let mut k = 2;
        loop {
            let s = format!("{} {}", base, k);
            if !taken(&s) {
                return s;
            }
            k += 1;
        }
    }

    fn select_only(&mut self, i: usize) {
        for s in &mut self.selected {
            *s = false;
        }
        if i < self.selected.len() {
            self.selected[i] = true;
            self.current = Some(i);
        }
    }

    fn add_new(&mut self, ref_material: usize) {
        let name = self.unique_name("Mesh");
        let mut m = LeafMesh::card(&name);
        m.ref_material = ref_material;
        self.items.push((None, m));
        self.selected.push(false);
        let i = self.items.len() - 1;
        self.select_only(i);
    }

    fn duplicate(&mut self) {
        if let Some(c) = self.current {
            let mut m = self.items[c].1.clone();
            m.name = self.unique_name(&format!("{} copy", m.name));
            self.items.insert(c + 1, (None, m));
            self.selected.insert(c + 1, false);
            self.select_only(c + 1);
        }
    }

    fn move_by(&mut self, d: i32) {
        if let Some(c) = self.current {
            let t = c as i32 + d;
            if t >= 0 && (t as usize) < self.items.len() {
                self.items.swap(c, t as usize);
                self.selected.swap(c, t as usize);
                self.current = Some(t as usize);
            }
        }
    }

    fn remove_selected(&mut self) {
        let mut i = 0;
        while i < self.items.len() {
            if self.selected[i] {
                self.items.remove(i);
                self.selected.remove(i);
            } else {
                i += 1;
            }
        }
        self.current = None;
        if !self.items.is_empty() {
            let c = 0;
            self.select_only(c);
        }
    }

    fn start_rename(&mut self) {
        if let Some(c) = self.current {
            self.editing = Some((c, self.items[c].1.name.clone()));
            self.caret_t = get_time();
        }
    }

    fn commit_rename(&mut self) {
        if let Some((i, text)) = self.editing.take() {
            let t = text.trim();
            if !t.is_empty() && i < self.items.len() {
                self.items[i].1.name = t.to_string();
            }
        }
    }
}

impl App {
    pub fn open_mesh_dialog(&mut self, sw: f32, sh: f32) {
        self.mesh_dialog = Some(MeshDialog::open(&self.meshes, self.mesh_cur, sw, sh));
    }

    /// Apply the dialog's list: new order, names, additions and removals. References from
    /// leaf generators, "More" links and material cutouts follow their meshes.
    fn apply_mesh_dialog(&mut self, d: MeshDialog) {
        let old_len = self.meshes.len();
        // old index -> new index (None when removed)
        let mut map: Vec<Option<usize>> = vec![None; old_len];
        for (ni, (oi, _)) in d.items.iter().enumerate() {
            if let Some(o) = oi {
                if *o < old_len {
                    map[*o] = Some(ni);
