            m.more = remap(m.more);
        }
        for n in &mut self.nodes {
            n.p.leaf_mesh = remap(n.p.leaf_mesh);
        }
        for mat in &mut self.materials {
            mat.cutout_mesh = remap(mat.cutout_mesh);
