    let (cx, cy) = (r.x + r.w * 0.5, r.y + r.h * 0.5);
    if up {
        draw_triangle(vec2(cx, cy - 8.0), vec2(cx - 7.0, cy), vec2(cx + 7.0, cy), c);
        draw_rectangle(cx - 2.5, cy, 5.0, 8.0, c);
    } else {
        draw_triangle(vec2(cx, cy + 8.0), vec2(cx - 7.0, cy), vec2(cx + 7.0, cy), c);
        draw_rectangle(cx - 2.5, cy - 8.0, 5.0, 8.0, c);
    }
}

