/// Browse… for one level, following the original (fn 0x1406003e0 cases 3 and 8): loading a file
/// over a level's own cutout asks first; loading High offers to find the related LOD files.
fn browse_lod(&mut self, cur: usize, l: usize) {
    if self.meshes[cur].lods[l].outline.len() >= 3 && self.meshes[cur].lods[l].geom.is_none() {
        let go = rfd::MessageDialog::new()
            .set_title("TreeCraft")
            .set_description("Loading a file will delete this asset's embedded data.\n\nDo you wish to continue?")
            .set_buttons(rfd::MessageButtons::YesNo)
            .show();
        if go != rfd::MessageDialogResult::Yes {
            return;
        }
    }
    let f = match Self::pick_mesh_file() {
        Some(f) => f,
        None => return,
    };
    match meshio::load_obj(&f) {
        Ok(g) => {
            self.meshes[cur].lods[l] = MeshLod { file: f.clone(), outline: vec![], geom: Some(g) };
            self.mesh_lod = l;
            self.dirty = true;
        }
        Err(e) => {
            self.set_status(&format!("Couldn't read that mesh: {}", e));
            return;
        }
    }
    if l == 0 {
        let ask = rfd::MessageDialog::new()
            .set_title("TreeCraft")
            .set_description("Attempt to find associated LOD meshes?")
            .set_buttons(rfd::MessageButtons::YesNo)
            .show();
        if ask == rfd::MessageDialogResult::Yes {
            let found = meshio::find_lod_files(&f);
            let mut n = 0;
            for (k, path) in found.iter().take(2).enumerate() {
                if let Ok(g) = meshio::load_obj(path) {
                    self.meshes[cur].lods[k + 1] = MeshLod { file: path.clone(), outline: vec![], geom: Some(g) };
                    n += 1;
                }
            }
            self.set_status(&format!("Found {} more LOD mesh{}", n, if n == 1 { "" } else { "es" }));
        }
    }
}

/// A file name's stem with trailing digits removed, then a trailing "lod" (any case) removed.
fn lod_base(stem: &str) -> (String, bool) {
    let s = stem.trim_end_matches(|c: char| c.is_ascii_digit());
    let lower = s.to_lowercase();
    if lower.ends_with("lod") {
        (s[..s.len() - 3].to_string(), true)
    } else {
        (s.to_string(), false)
    }
}

/// The original's "Attempt to find associated LOD meshes?" search (fn 0x1406003e0 case 8):
/// take the chosen file's name base (trailing digits and a trailing "lod" removed), list
/// "<base>*" mesh files in the same folder in name order, and return the files after the chosen
/// one whose names end in "lod" + digits. This build reads OBJ files only.
pub fn find_lod_files(chosen: &str) -> Vec<String> {
    let p = std::path::Path::new(chosen);
    let dir = match p.parent() {
        Some(d) => d,
        None => return vec![],
    };
    let stem = p.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
    let (base, _) = lod_base(&stem);
    let base_l = base.to_lowercase();
    let mut files: Vec<String> = match std::fs::read_dir(dir) {
        Ok(rd) => rd
            .filter_map(|e| e.ok())
            .map(|e| e.path())
            .filter(|q| q.extension().map(|x| x.to_string_lossy().eq_ignore_ascii_case("obj")).unwrap_or(false))
            .filter(|q| q.file_stem().map(|s| s.to_string_lossy().to_lowercase().starts_with(&base_l)).unwrap_or(false))
            .map(|q| q.to_string_lossy().to_string())
            .collect(),
        Err(_) => return vec![],
    };
    files.sort_by_key(|s| s.to_lowercase());
    let mut out = vec![];
    let mut seen_chosen = false;
    for f in files {
        if std::path::Path::new(&f) == p {
            seen_chosen = true;
            continue;
        }
        if seen_chosen {
            let st = std::path::Path::new(&f).file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
            let (b, is_lod) = lod_base(&st);
            if is_lod && b.eq_ignore_ascii_case(&base) {
                out.push(f);
            }
        }
    }
    out
}

