#[derive(Clone)]
pub struct Material {
    pub name: String,
    pub two_sided: bool,
    pub color: [f32; 3],
    pub source: usize,
    pub file: String,
    pub brightness: f32,
    pub contrast: f32,
    pub saturation: f32,
    pub hue: f32,
    pub opacity_from_alpha: bool,
    pub cutoff: f32,
    pub normal_strength: f32,
    pub gloss: f32,
    pub specular: f32,
    pub metallic: f32,
    pub sss_color: [f32; 3],
    pub sss_amount: f32,
    pub ao: f32,
    pub variation: f32,
    pub var_colors: [[f32; 3]; 3],
    pub cutout_mesh: usize,
    pub base: Option<ImageBuf>,
    pub adjusted: Option<ImageBuf>,
    pub tex: Option<Texture2D>,
    pub dirty_base: bool,
    pub dirty_tex: bool,
}

impl Material {
    pub fn new(name: &str, source: usize) -> Self {
        Material {
            name: name.to_string(),
            two_sided: false,
            color: [1.0, 1.0, 1.0],
            source,
            file: String::new(),
            brightness: 0.0,
            contrast: 0.0,
            saturation: 0.0,
            hue: 0.0,
            opacity_from_alpha: true,
            cutoff: 0.33,
            normal_strength: 0.5,
            gloss: 0.25,
            specular: 0.2,
            metallic: 0.0,
            sss_color: [0.75, 0.85, 0.3],
            sss_amount: 0.0,
            ao: 0.6,
            variation: 0.0,
            // Variation colours from the original's sample material
            var_colors: [[0.28, 0.37, 0.0], [0.59, 0.72, 0.32], [0.46, 0.55, 0.2]],
            cutout_mesh: 0,
            base: None,
            adjusted: None,
            tex: None,
            dirty_base: true,
            dirty_tex: true,
        }
    }
    pub fn bark() -> Self {
        let mut m = Material::new("Bark", 1);
        m.normal_strength = 1.0;
        m.gloss = 0.15;
        m.specular = 0.1;
        m
    }
    pub fn leaf() -> Self {
        let mut m = Material::new("Leaf", 2);
        m.two_sided = true;
        m.sss_amount = 0.45;
        m.gloss = 0.45;
        m.specular = 0.3;
        m.normal_strength = 0.3;
        m.variation = 0.35;
        m.cutout_mesh = 1;
        m
    }
}

