    FLAT_NORMAL.with(|c| {
        let mut b = c.borrow_mut();
        if b.is_none() {
            *b = Some(Texture2D::from_rgba8(1, 1, &[128, 128, 255, 255]));
        }
        b.clone().unwrap()
    })
}

