60	        }
61	    }
62	
63	    fn unique_name(&self, base: &str) -> String {
64	        let names: Vec<String> = self.items.iter().map(|(_, m)| m.name.clone()).collect();
65	        unique_name_in(&names, base)
66	    }
67	
68	    fn select_only(&mut self, i: usize) {
69	        for s in &mut self.selected {
70	            *s = false;
71	        }
72	        if i < self.selected.len() {
73	            self.selected[i] = true;
74	            self.current = Some(i);
75	        }
76	    }
77	
78	    fn add_new(&mut self, ref_material: usize) {
79	        let name = self.unique_name("Mesh");
80	        // a new mesh starts empty: no cutout or file in any level, so the preview is blank
81	        let mut m = LeafMesh::empty(&name);
82	        m.ref_material = ref_material;
83	        self.items.push((None, m));
84	        self.selected.push(false);
85	        let i = self.items.len() - 1;
86	        self.select_only(i);
87	    }
88	
89	    /// Duplicate (fn 0x1405ff5d0 case 4): the copy is named "<name> Copy", added at the end of the
90	    /// list, and its name is opened for editing straight away.
91	    fn duplicate(&mut self) {
92	        if let Some(c) = self.current {
93	            let mut m = self.items[c].1.clone();
94	            m.name = self.unique_name(&format!("{} Copy", m.name));
95	            self.items.push((None, m));
96	            self.selected.push(false);
97	            let i = self.items.len() - 1;
98	            self.select_only(i);
99	            self.start_rename();
100	        }
101	    }
102	
103	    /// Move up / Move down (fn 0x1405ff5d0 cases 0 and 1): every selected item moves one place,
104	    /// and stays selected.
105	    fn move_by(&mut self, d: i32) {
106	        let n = self.items.len();
107	        if n < 2 {
108	            return;
109	        }
110	        let order: Vec<usize> = if d < 0 { (1..n).collect() } else { (0..n - 1).rev().collect() };
111	        for i in order {
112	            let t = (i as i32 + d) as usize;
113	            if self.selected[i] && !self.selected[t] {
114	                self.items.swap(i, t);
115	                self.selected.swap(i, t);
116	                if self.current == Some(i) {
117	                    self.current = Some(t);
118	                } else if self.current == Some(t) {
119	                    self.current = Some(i);
120	                }
121	            }
122	        }
123	    }
124	
125	    fn remove_selected(&mut self) {
126	        let mut i = 0;
127	        while i < self.items.len() {
128	            if self.selected[i] {
129	                self.items.remove(i);
130	                self.selected.remove(i);
131	            } else {
132	                i += 1;
