595	    fn draw_generation(&mut self, ui: &mut Ui, tb: Rect, body: Rect) {
596	        let sel_node = if let Sel::Node(id) = self.sel { Some(id) } else { None };
597	        let (add, act, rnd) = self.toolbar(ui, tb, "gen", &["Trunk", "Branch", "Leaf"], &["Duplicate", "Delete", "Hide / show", "Arrange nodes", "Frame graph"], true);
598	        if let Some(i) = add {
599	            let kind = [Kind::Trunk, Kind::Branch, Kind::Leaf][i];
600	            let parent = sel_node.unwrap_or_else(|| {
601	                // default parent: Tree for trunks, newest branch-type node otherwise
602	                if kind == Kind::Trunk {
603	                    self.root_id()
604	                } else {
605	                    self.nodes.iter().rev().find(|n| n.kind.makes_spines()).map(|n| n.id).unwrap_or(self.root_id())
606	                }
607	            });
608	            self.add_node(kind, parent);
609	        }
610	        if let Some(i) = act {
611	            match (i, sel_node) {
612	                (0, Some(id)) => self.duplicate_node(id),
613	                (1, Some(id)) => self.delete_node(id),
614	                (2, Some(id)) => {
615	                    if let Some(n) = self.nodes.iter_mut().find(|n| n.id == id) {
616	                        n.hidden = !n.hidden;
617	                    }
618	                    self.dirty = true;
619	                }
620	                (3, _) => self.arrange(),
621	                (4, _) => {
622	                    self.graph_off = Vec2::ZERO;
623	                    self.graph_zoom = 1.0;
624	                }
625	                _ => self.set_status("Select a node first"),
626	            }
627	        }
628	        if rnd {
629	            self.randomize(sel_node);
630	        }
631	        // context menu result
632	        if let Some(i) = ui.take_popup_result("gen.ctx") {
633	            if let Some(id) = sel_node {
634	                match i {
635	                    0 => {
636	                        self.add_node(Kind::Branch, id);
637	                    }
638	                    1 => {
639	                        self.add_node(Kind::Leaf, id);
640	                    }
641	                    2 => self.duplicate_node(id),
642	                    3 => {
643	                        if let Some(n) = self.nodes.iter_mut().find(|n| n.id == id) {
644	                            n.hidden = !n.hidden;
645	                        }
646	                        self.dirty = true;
647	                    }
648	                    _ => self.delete_node(id),
649	                }
650	            }
651	        }
652	
653	        ui.set_clip(Some(body));
654	        // background grid dots
655	        let step = 40.0 * self.graph_zoom;
656	        let o = self.graph_to_screen(body, Vec2::ZERO);
657	        let mut gx = body.x + (o.x - body.x).rem_euclid(step);
658	        while gx < body.x + body.w {
659	            let mut gy = body.y + (o.y - body.y).rem_euclid(step);
660	            while gy < body.y + body.h {
661	                draw_rectangle(gx, gy, 1.5, 1.5, Color::new(1.0, 1.0, 1.0, 0.07));
662	                gy += step;
663	            }
664	            gx += step;
665	        }
666	        let rad = 26.0 * self.graph_zoom;
667	        // links
668	        for n in &self.nodes {
669	            if let Some(pid) = n.parent {
670	                if let Some(p) = self.node(pid) {
671	                    let a = self.graph_to_screen(body, p.pos) - vec2(0.0, rad);
672	                    let b = self.graph_to_screen(body, n.pos) + vec2(0.0, rad);
673	                    let c = if sel_node == Some(n.id) { C_ORANGE } else { Color::new(1.0, 1.0, 1.0, 0.35) };
674	                    draw_line(a.x, a.y, b.x, b.y, 2.0, c);
675	                    draw_circle(a.x, a.y, 3.0, c);
676	                }
677	            }
678	        }
679	        let m = ui.mouse();
680	        let mut hover_node = None;
681	        for n in self.nodes.iter() {
682	            let c = self.graph_to_screen(body, n.pos);
683	            if c.distance(m) <= rad && body.contains(m) && !ui.blocked {
684	                hover_node = Some(n.id);
685	            }
686	        }
687	        // nodes
688	        let nodes = self.nodes.clone();
689	        for n in &nodes {
690	            let c = self.graph_to_screen(body, n.pos);
691	            let alpha = if n.hidden { 0.35 } else { 1.0 };
692	            let tex = self.icons.for_kind(n.kind);
693	            let tint = if n.kind == Kind::Trunk { Color::new(0.85, 0.75, 0.7, alpha) } else { Color::new(1.0, 1.0, 1.0, alpha) };
694	            draw_circle(c.x + 2.0, c.y + 3.0, rad, Color::new(0.0, 0.0, 0.0, 0.3));
695	            draw_texture_ex(tex, c.x - rad, c.y - rad, tint, DrawTextureParams { dest_size: Some(vec2(rad * 2.0, rad * 2.0)), ..Default::default() });
696	            let selected = sel_node == Some(n.id);
697	            if selected || hover_node == Some(n.id) {
698	                let rr = rad * 1.18;
699	                let col = if selected { C_ORANGE } else { Color::new(1.0, 1.0, 1.0, 0.45) };
700	                draw_texture_ex(&self.icons.ring, c.x - rr, c.y - rr, col, DrawTextureParams { dest_size: Some(vec2(rr * 2.0, rr * 2.0)), ..Default::default() });
701	            }
702	            let fs = (12.0 * self.graph_zoom.sqrt()).clamp(9.0, 15.0);
703	            ui.text(&n.name, c.x + rad + 8.0, c.y - fs * 0.5 - 1.0, fs, if selected { WHITE } else { C_TEXT });
704	            if n.kind != Kind::Tree {
705	                let cnt = self.instance_count(n.id).to_string();
706	                let cw = ui.text_w(&cnt, 10.5) + 8.0;
707	                let br = Rect::new(c.x + rad * 0.55, c.y - rad * 1.05, cw, 15.0);
708	                draw_rectangle(br.x, br.y, br.w, br.h, Color::new(0.1, 0.1, 0.1, 0.85));
709	                ui.text_center(&cnt, br, 10.5, C_TEXT_DIM);
710	            }
711	            ui.record(&format!("node:{}", n.name), Rect::new(c.x - rad, c.y - rad, rad * 2.0, rad * 2.0));
712	        }
713	
714	        // interaction
715	        let inp = ui.inp.clone();
716	        let in_body = body.contains(m) && !ui.blocked && ui.popup.is_none();
717	        if in_body && inp.wheel != 0.0 {
718	            let before = (m - self.graph_to_screen(body, Vec2::ZERO)) / self.graph_zoom;
719	            self.graph_zoom = (self.graph_zoom * 1.1f32.powf(inp.wheel)).clamp(0.4, 2.5);
720	            let after = (m - self.graph_to_screen(body, Vec2::ZERO)) / self.graph_zoom;
721	            self.graph_off += after - before;
722	        }
723	        if in_body && ui.active == 0 && self.graph_drag == GraphDrag::None {
724	            if inp.l_pressed {
725	                if let Some(id) = hover_node {
726	                    self.select(Sel::Node(id));
727	                    self.graph_drag = if inp.shift { GraphDrag::Link { from: id } } else { GraphDrag::Node { id, start: m, moved: false } };
728	                    ui.active = hid("graph");
729	                } else {
730	                    self.select(Sel::None);
731	                    self.graph_drag = GraphDrag::Pan;
732	                    ui.active = hid("graph");
733	                }
734	            } else if inp.r_pressed {
735	                if let Some(id) = hover_node {
736	                    self.select(Sel::Node(id));
737	                    ui.open_popup(hid("gen.ctx"), Rect::new(m.x, m.y, 10.0, 0.0), vec!["Add branch".into(), "Add leaf".into(), "Duplicate".into(), "Hide / show".into(), "Delete".into()], None);
738	                } else {
739	                    self.graph_drag = GraphDrag::Pan;
740	                }
741	            } else if inp.m_pressed {
742	                self.graph_drag = GraphDrag::Pan;
743	            }
744	        }
745	        let d = m - self.last_graph_mouse();
746	        match self.graph_drag {
747	            GraphDrag::Node { id, start, moved } => {
748	                if inp.l_down {
749	                    let mv = moved || start.distance(m) > 4.0;
750	                    if mv {
