190	/// A cutout outline as geometry: x = across, y = from the anchor toward the tip, z = 0,
191	/// facing +Z. Triangles are split once so folding and curling bend smoothly.
192	pub fn outline_geom(outline: &[Vec2], anchor: Vec2) -> MeshGeom {
193	    let tris = triangulate(outline);
194	    let mut uvs: Vec<Vec2> = outline.to_vec();
195	    let mut idx: Vec<u32> = vec![];
196	    let mut mid: HashMap<(usize, usize), usize> = HashMap::new();
197	    let mut midp = |a: usize, b: usize, uvs: &mut Vec<Vec2>| -> usize {
198	        let key = if a < b { (a, b) } else { (b, a) };
199	        if let Some(&i) = mid.get(&key) {
200	            return i;
201	        }
202	        uvs.push((uvs[a] + uvs[b]) * 0.5);
203	        mid.insert(key, uvs.len() - 1);
204	        uvs.len() - 1
205	    };
206	    for t in &tris {
207	        let ab = midp(t[0], t[1], &mut uvs);
208	        let bc = midp(t[1], t[2], &mut uvs);
209	        let ca = midp(t[2], t[0], &mut uvs);
210	        for f in [[t[0], ab, ca], [ab, t[1], bc], [ca, bc, t[2]], [ab, bc, ca]] {
211	            idx.extend(f.iter().map(|&i| i as u32));
212	        }
213	    }
214	    let pos: Vec<Vec3> = uvs.iter().map(|uv| vec3(uv.x - anchor.x, anchor.y - uv.y, 0.0)).collect();
215	    // make the front face (+Z) wind counter-clockwise
216	    let mut g = MeshGeom { nrm: vec![Vec3::Z; pos.len()], pos, uv: uvs, idx };
217	    for f in g.idx.chunks_mut(3) {
218	        let (a, b, c) = (f[0] as usize, f[1] as usize, f[2] as usize);
219	        if (g.pos[b] - g.pos[a]).cross(g.pos[c] - g.pos[a]).z < 0.0 {
220	            f.swap(1, 2);
221	        }
222	    }
223	    g
224	}
