226	/// Reorient a point: the original's axis matrix for each Orient value, read from the mesh
227	/// processing switch in fn 0x1400ab6c0 (8.4.2). Values 1, 2, 5, 8 and 9 mirror the mesh.
228	pub fn orient_point(value: i32, p: Vec3) -> Vec3 {
229	    match value {
230	        1 | 9 => vec3(p.x, p.z, p.y),  // XZY, Y-up left-handed
231	        2 => vec3(p.y, p.x, p.z),      // YXZ
232	        3 => vec3(p.y, -p.z, -p.x),    // YZX
233	        4 => vec3(-p.z, p.x, -p.y),    // ZXY
234	        5 => vec3(p.z, p.y, p.x),      // ZYX
235	        7 => vec3(p.x, -p.z, p.y),     // Y-up right-handed
236	        8 => vec3(p.x, p.y, -p.z),     // Z-up left-handed
237	        _ => p,                        // 0 XYZ, 6 Z-up right-handed: unchanged
238	    }
239	}
