241	pub fn flip_signs(flip: usize) -> Vec3 {
242	    let label = FLIPS.get(flip).copied().unwrap_or("X Y Z");
243	    let mut s = Vec3::ONE;
244	    for tok in label.split_whitespace() {
245	        let neg = tok.starts_with('-');
246	        let v = if neg { -1.0 } else { 1.0 };
247	        match tok.trim_start_matches('-') {
248	            "X" => s.x = v,
249	            "Y" => s.y = v,
250	            _ => s.z = v,
251	        }
252	    }
253	    s
254	}
