256	pub fn growth_axis(g: usize) -> Vec3 {
257	    match g {
258	        0 => Vec3::X,
259	        1 => Vec3::Y,
260	        2 => Vec3::Z,
261	        3 => -Vec3::X,
262	        4 => -Vec3::Y,
263	        _ => -Vec3::Z,
264	    }
265	}
