267	/// The leaf frame implied by a mesh's Growth axis: (right, growth, face normal).
268	pub fn growth_frame(growth: usize) -> (Vec3, Vec3, Vec3) {
269	    let g = growth_axis(growth);
270	    let n = if g.z.abs() > 0.5 { Vec3::Y } else { Vec3::Z };
271	    let r = g.cross(n).normalize();
272	    (r, g, n)
273	}
