/// The cutout editor's Options (the original's "Options" group in the Edit Cutout window,
/// fn 0x1402f32a0: Tessellation, Angle, Double-sided, Improve folding). How each one shapes the
/// mesh is estimated; the defaults give the same mesh as before these options existed.
#[derive(Clone, Copy, Default)]
pub struct CutOpts {
    /// 0..1: extra subdivision passes (0 = one split, 1 = four).
    pub tessellation: f32,
    /// 0..1: outline points that turn less than Angle x 20 degrees are dropped.
    pub angle: f32,
    /// Also make the back faces.
    pub double_sided: bool,
    /// Add outline points where it crosses the vertical line through the anchor and split once
    /// more, so the leaf folds along its middle.
    pub improve_folding: bool,
}

impl CutOpts {
    pub fn of(m: &LeafMesh) -> Self {
        CutOpts { tessellation: m.tessellation, angle: m.angle, double_sided: m.double_sided, improve_folding: m.improve_folding }
    }
}

/// Outline points kept after the Angle option (never fewer than 3).
pub fn simplify_by_angle(outline: &[Vec2], angle: f32) -> Vec<Vec2> {
    if angle <= 0.0 || outline.len() <= 3 {
        return outline.to_vec();
    }
    let lim = (angle * 20.0).to_radians();
    let mut pts = outline.to_vec();
    loop {
        let n = pts.len();
        if n <= 3 {
            break;
        }
        let mut best: Option<(f32, usize)> = None;
        for i in 0..n {
            let a = pts[(i + n - 1) % n];
            let b = pts[i];
            let c = pts[(i + 1) % n];
            let (u, v) = (b - a, c - b);
            if u.length_squared() < 1e-12 || v.length_squared() < 1e-12 {
                best = Some((0.0, i));
                break;
            }
            let turn = u.angle_between(v).abs();
            if turn < lim && best.map(|(t, _)| turn < t).unwrap_or(true) {
                best = Some((turn, i));
            }
        }
        match best {
            Some((_, i)) => {
                pts.remove(i);
            }
            None => break,
        }
    }
    pts
}

/// Insert outline points where it crosses the vertical line x = mid (Improve folding).
fn add_fold_points(outline: &[Vec2], mid: f32) -> Vec<Vec2> {
    let n = outline.len();
    let mut out = Vec::with_capacity(n + 2);
    for i in 0..n {
        let a = outline[i];
        let b = outline[(i + 1) % n];
        out.push(a);
        if (a.x - mid) * (b.x - mid) < 0.0 {
            let t = (mid - a.x) / (b.x - a.x);
            out.push(a + (b - a) * t);
        }
    }
    out
}

/// A cutout outline as geometry: x = across, y = from the anchor toward the tip, z = 0,
/// facing +Z. Triangles are split once so folding and curling bend smoothly.
pub fn outline_geom(outline: &[Vec2], anchor: Vec2) -> MeshGeom {
    outline_geom_opts(outline, anchor, CutOpts::default())
}

/// outline_geom with the cutout editor's Options.
pub fn outline_geom_opts(outline: &[Vec2], anchor: Vec2, o: CutOpts) -> MeshGeom {
    let mut shape = simplify_by_angle(outline, o.angle);
    if o.improve_folding {
        shape = add_fold_points(&shape, anchor.x);
    }
    let tris = triangulate(&shape);
    let mut uvs: Vec<Vec2> = shape;
    let mut faces: Vec<[usize; 3]> = tris;
    let passes = 1 + (o.tessellation.clamp(0.0, 1.0) * 3.0).round() as usize + usize::from(o.improve_folding);
    for _ in 0..passes {
        let mut mid: HashMap<(usize, usize), usize> = HashMap::new();
        let mut midp = |a: usize, b: usize, uvs: &mut Vec<Vec2>| -> usize {
            let key = if a < b { (a, b) } else { (b, a) };
            if let Some(&i) = mid.get(&key) {
                return i;
            }
            uvs.push((uvs[a] + uvs[b]) * 0.5);
            mid.insert(key, uvs.len() - 1);
            uvs.len() - 1
        };
        let mut next = Vec::with_capacity(faces.len() * 4);
        for t in &faces {
            let ab = midp(t[0], t[1], &mut uvs);
            let bc = midp(t[1], t[2], &mut uvs);
            let ca = midp(t[2], t[0], &mut uvs);
            next.extend([[t[0], ab, ca], [ab, t[1], bc], [ca, bc, t[2]], [ab, bc, ca]]);
        }
        faces = next;
        if faces.len() > 20000 {
            break;
        }
    }
    let mut idx: Vec<u32> = faces.iter().flat_map(|f| f.iter().map(|&i| i as u32)).collect();
    let mut pos: Vec<Vec3> = uvs.iter().map(|uv| vec3(uv.x - anchor.x, anchor.y - uv.y, 0.0)).collect();
    // make the front face (+Z) wind counter-clockwise
    for f in idx.chunks_mut(3) {
        let (a, b, c) = (f[0] as usize, f[1] as usize, f[2] as usize);
        if (pos[b] - pos[a]).cross(pos[c] - pos[a]).z < 0.0 {
            f.swap(1, 2);
        }
    }
    let mut nrm = vec![Vec3::Z; pos.len()];
    if o.double_sided {
        // back faces: their own vertices facing -Z, wound the other way
        let n = pos.len() as u32;
        pos.extend_from_within(..);
        let back_uv = uvs.clone();
        uvs.extend(back_uv);
        nrm.extend(std::iter::repeat(-Vec3::Z).take(n as usize));
        let front = idx.clone();
        for f in front.chunks(3) {
            idx.extend([f[0] + n, f[2] + n, f[1] + n]);
        }
    }
    MeshGeom { nrm, pos, uv: uvs, idx }
}

