    let passes = 1 + (o.tessellation.clamp(0.0, 1.0) * 3.0).round() as usize + usize::from(o.improve_folding);
    for _ in 0..passes {
        let mut mid: HashMap<(usize, usize), usize> = HashMap::new();
        let mut midp = |a: usize, b: usize, uvs: &mut Vec<Vec2>| -> usize {
            let key = if a < b { (a, b) } else { (b, a) };
            if let Some(&i) = mid.get(&key) {
                return i;
            }
            uvs.push((uvs[a] + uvs[b]) * 0.5);
            mid.insert(key, uvs.len() - 1);
            uvs.len() - 1
        };
        let mut next = Vec::with_capacity(faces.len() * 4);
        for t in &faces {
            let ab = midp(t[0], t[1], &mut uvs);
            let bc = midp(t[1], t[2], &mut uvs);
            let ca = midp(t[2], t[0], &mut uvs);
            next.extend([[t[0], ab, ca], [ab, t[1], bc], [ca, bc, t[2]], [ab, bc, ca]]);
        }
        faces = next;
        if faces.len() > 20000 {
            break;
        }
    }
    let mut idx: Vec<u32> = faces.iter().flat_map(|f| f.iter().map(|&i| i as u32)).collect();
    let mut pos: Vec<Vec3> = uvs.iter().map(|uv| vec3(uv.x - anchor.x, anchor.y - uv.y, 0.0)).collect();
    // make the front face (+Z) wind counter-clockwise
    for f in idx.chunks_mut(3) {
        let (a, b, c) = (f[0] as usize, f[1] as usize, f[2] as usize);
        if (pos[b] - pos[a]).cross(pos[c] - pos[a]).z < 0.0 {
            f.swap(1, 2);
        }
    }
    let mut nrm = vec![Vec3::Z; pos.len()];
    if o.double_sided {
        // back faces: their own vertices facing -Z, wound the other way
        let n = pos.len() as u32;
        pos.extend_from_within(..);
        let back_uv = uvs.clone();
        uvs.extend(back_uv);
        nrm.extend(std::iter::repeat(-Vec3::Z).take(n as usize));
        let front = idx.clone();
        for f in front.chunks(3) {
            idx.extend([f[0] + n, f[2] + n, f[1] + n]);
        }
    }
    MeshGeom { nrm, pos, uv: uvs, idx }
}

