/// The cutout editor's Options (the original's "Options" group in the Edit Cutout window,
/// fn 0x1402f32a0: Tessellation, Angle, Double-sided, Improve folding). How each one shapes the
/// mesh is estimated; the defaults give the same mesh as before these options existed.
#[derive(Clone, Copy, Default)]
pub struct CutOpts {
    /// 0..1: extra subdivision passes (0 = one split, 1 = four).
    pub tessellation: f32,
    /// 0..1: outline points that turn less than Angle x 20 degrees are dropped.
    pub angle: f32,
    /// Also make the back faces.
    pub double_sided: bool,
    /// Add outline points where it crosses the vertical line through the anchor and split once
    /// more, so the leaf folds along its middle.
    pub improve_folding: bool,
}

impl CutOpts {
    pub fn of(m: &LeafMesh) -> Self {
        CutOpts { tessellation: m.tessellation, angle: m.angle, double_sided: m.double_sided, improve_folding: m.improve_folding }
    }
}

