    if over && ui.active == 0 && inp.l_pressed {
        match ed.tool {
            Tool::AddPoints => {
                if let Some(k) = hover_pt {
                    ed.drag = Some((false, k));
                } else {
                    let at = insert_index(&ed.outline, uv);
                    let mut next = ed.outline.clone();
                    next.insert(at, uv);
                    if is_simple(&next) {
                        ed.outline = next;
                        ed.drag = Some((false, at));
                    } else {
                        ed.warn = Some(("A point there would make the outline cross itself".into(), get_time()));
                    }
                }
            }
            Tool::RemovePoints => {
                if let Some(k) = hover_pt {
                    if ed.outline.len() > 3 {
                        let mut next = ed.outline.clone();
                        next.remove(k);
                        if is_simple(&next) {
                            ed.outline = next;
                        } else {
                            ed.warn = Some(("Removing that point would make the outline cross itself".into(), get_time()));
                        }
                    } else {
                        ed.warn = Some(("An outline needs at least 3 points".into(), get_time()));
                    }
                }
            }
            Tool::AddAnchors => {
                if let Some(k) = hover_anc {
                    ed.drag = Some((true, k));
                } else {
                    ed.anchors.push(uv);
                    ed.drag = Some((true, ed.anchors.len() - 1));
                }
            }
            Tool::RemoveAnchors => {
                if let Some(k) = hover_anc {
                    if ed.anchors.len() > 1 {
                        ed.anchors.remove(k);
                    } else {
                        ed.warn = Some(("A mesh keeps at least one anchor".into(), get_time()));
                    }
                }
            }
        }
        if ed.drag.is_some() {
            ui.active = hid("cutout.drag");
        }
    }
    if let Some((anchor, k)) = ed.drag {
        if inp.l_down {
            if anchor {
                if k < ed.anchors.len() {
                    ed.anchors[k] = uv;
                }
            } else if k < ed.outline.len() {
                // a move that would make the outline cross itself is refused
                let mut next = ed.outline.clone();
                next[k] = uv;
                if is_simple(&next) {
                    ed.outline = next;
                }
            }
        } else {
            ed.drag = None;
        }
    }
    let hint = match ed.tool {
        Tool::AddPoints => "Click to add a point on the nearest edge, drag a point to move it",
        Tool::RemovePoints => "Click a point to remove it",
