        let c = outline_centroid(&uvs);
        if let Some(k) = faces.iter().position(|t| in_triangle(c, uvs[t[0]], uvs[t[1]], uvs[t[2]])) {
            let t = faces.remove(k);
            uvs.push(c);
            if use_col {
                let a = avg_col(&[cols[t[0]], cols[t[1]], cols[t[2]]]);
                cols.push(a);
            }
            let ci = uvs.len() - 1;

