fn apply_cutout(&mut self, ed: &CutoutEditor) {
    let mut lods = ed.lods.clone();
    if ed.outline.len() >= 3 {
        lods[ed.target] = MeshLod { file: String::new(), outline: ed.outline.clone(), geom: None };
    } else if lods[ed.target].geom.is_none() {
        lods[ed.target].outline.clear(); // cleared in the window: the level is empty
    }
    let m = &mut self.meshes[ed.mesh];
    m.lods = lods;
    m.anchor = ed.anchors[0];
    m.extra_anchors = ed.anchors[1..].to_vec();
    m.extra_anchor_angles = ed.anchor_angles[1..].to_vec();
    m.tessellation = ed.opts.tessellation;
    m.angle = ed.opts.angle;
    m.double_sided = ed.opts.double_sided;
    m.improve_folding = ed.opts.improve_folding;
    m.embedded = true;
    if ed.material > 0 {
        m.ref_material = ed.material - 1;
    }
    self.mesh_lod = ed.target;
    self.dirty = true;
}

