230	fn in_triangle(p: Vec2, a: Vec2, b: Vec2, c: Vec2) -> bool {
231	    let (d1, d2, d3) = ((b - a).perp_dot(p - a), (c - b).perp_dot(p - b), (a - c).perp_dot(p - c));
232	    let neg = d1 < 0.0 || d2 < 0.0 || d3 < 0.0;
233	    let pos = d1 > 0.0 || d2 > 0.0 || d3 > 0.0;
234	    !(neg && pos)
235	}
