238	/// facing +Z. Triangles are split once so folding and curling bend smoothly.
239	pub fn outline_geom(outline: &[Vec2], anchor: Vec2) -> MeshGeom {
240	    outline_geom_opts(outline, anchor, CutOpts::default())
241	}
