248	fn avg_col(cs: &[[f32; 3]]) -> [f32; 3] {
249	    let n = cs.len().max(1) as f32;
250	    let mut s = [0.0f32; 3];
251	    for c in cs {
252	        for k in 0..3 {
253	            s[k] += c[k] / n;
254	        }
255	    }
256	    s
257	}
