260	/// average of the points they're made from.
261	pub fn outline_geom_col(outline: &[Vec2], colors: &[[f32; 3]], anchor: Vec2, o: CutOpts) -> MeshGeom {
262	    let mut uvs: Vec<Vec2> = outline.to_vec();
263	    let use_col = colors.len() == outline.len() && !colors.is_empty();
264	    let mut cols: Vec<[f32; 3]> = if use_col { colors.to_vec() } else { vec![] };
265	    let mut faces: Vec<[usize; 3]> = triangulate(&uvs);
