270	            let t = faces.remove(k);
271	            uvs.push(c);
272	            if use_col {
273	                let a = avg_col(&[cols[t[0]], cols[t[1]], cols[t[2]]]);
274	                cols.push(a);
275	            }
276	            let ci = uvs.len() - 1;
277	            faces.extend([[t[0], t[1], ci], [t[1], t[2], ci], [t[2], t[0], ci]]);
278	        }
279	    }
280	    // no automatic subdivision (the person's request): only the Tessellation option splits
281	    let passes = (o.tessellation.clamp(0.0, 1.0) * 3.0).round() as usize;
