    uvs.push((uvs[e0] + uvs[e1]) * 0.5);
    if use_col {
        let col = avg_col(&[cols[e0], cols[e1]]);
        cols.push(col);
    }
    let m = uvs.len() - 1;
    let mut out = Vec::with_capacity(faces.len() + 2);
    for t in faces.iter() {
        let mut split = false;
        for j in 0..3 {
