        let ca = midp(t[2], t[0], &mut uvs, &mut cols);
        next.extend([[t[0], ab, ca], [ab, t[1], bc], [ca, bc, t[2]], [ab, bc, ca]]);
    }
    faces = next;
    if faces.len() > 20000 {
        break;
    }
}

