    let crosses = |a: f32, b: f32| (a > 0.0 && b < 0.0) || (a < 0.0 && b > 0.0);
    let area = |a: usize, b: usize, e: usize| (uvs[b] - uvs[a]).perp_dot(uvs[e] - uvs[a]);
